/** Failed-inspection-state-flow API calls: fetch states, submit skip/unskip, update report. */
export const apiScripts = `
        function fetchAndApplyFailedInspectionStates() {
            var ctx = window.A11Y_AUDIT_CONTEXT;
            if (!ctx || !ctx.repository) {
                console.warn('[failed-inspection-state] fetchAndApplyFailedInspectionStates: no ctx or repository, aborting.', { ctx: ctx });
                removeSkipLoading();
                return;
            }

            var baseUrl = getServiceBaseUrl();
            var allStates = [];
            var cursor = null;

            function fetchPage() {
                var url = baseUrl + '/v1/inspection-states/' + encodeURIComponent(ctx.repository) + '?paging.limit=100';
                if (cursor) url += '&paging.cursor=' + encodeURIComponent(cursor);
                console.info('[failed-inspection-state] fetchPage URL:', url);

                return fetch(url)
                    .then(function(res) {
                        console.info('[failed-inspection-state] fetchPage response:', res.status, res.statusText);
                        if (!res.ok) throw new Error('Fetch failed inspection states failed: ' + res.status);
                        return res.json();
                    })
                    .then(function(data) {
                        console.info('[failed-inspection-state] fetchPage data:', JSON.stringify(data).substring(0, 500));
                        var states = data.inspectionStates || [];
                        allStates = allStates.concat(states);
                        var nextCursor = data.pagingMetadata && data.pagingMetadata.cursors && data.pagingMetadata.cursors.next;
                        if (nextCursor) {
                            cursor = nextCursor;
                            return fetchPage();
                        }
                    });
            }

            fetchPage()
                .then(function() {
                    console.info('[failed-inspection-state] Total states fetched:', allStates.length);
                    _failedInspectionStatesCache = allStates;
                    if (allStates.length === 0) return;

                    var prNumber = ctx.prNumber ? Number(ctx.prNumber) : null;
                    var now = new Date().toISOString();

                    var cardIndex = {};
                    var items = document.querySelectorAll('.audits-group-item[data-inspection-id][data-page-url]');
                    for (var i = 0; i < items.length; i++) {
                        var item = items[i];
                        var purl = item.getAttribute('data-page-url');
                        if (!purl) continue;
                        var content = item.querySelector('.audits-group-item-content');
                        if (!content) continue;
                        var cards = content.querySelectorAll('.failed-inspection-card, .failed-inspection-item');
                        var csel = item.getAttribute('data-container-selector') || '';
                        for (var j = 0; j < cards.length; j++) {
                            var card = cards[j];
                            var rid = getRuleId(card, item);
                            var selectorEl = card.querySelector('.element-selector, .affected-element-selector');
                            if (!selectorEl) continue;
                            var sel = (selectorEl.textContent || '').trim();
                            if (rid && sel) cardIndex[rid + '::' + sel + '::' + purl + '::' + csel] = card;
                        }
                    }

                    allStates.forEach(function(state) {
                        if (!state.inspection) return;

                        var v = state.inspection;
                        var key = (v.ruleId || '') + '::' + (v.elementSelector || '') + '::' + (v.url || '') + '::' + (v.containerSelector || '');
                        var matched = cardIndex[key];
                        if (!matched) return;

                        var stateType = state.state;

                        if (stateType === 'SKIPPED_INDEFINITE') {
                            applySkipToCard(matched, stateType, state.reason || '');
                        } else if (stateType === 'SKIPPED_PR') {
                            if (state.prNumber != null && Number(state.prNumber) === prNumber) {
                                applySkipToCard(matched, stateType, state.reason || '');
                            }
                        } else if (stateType === 'BENCHMARKED') {
                            var expired = state.benchmarkExpiresAt && new Date(state.benchmarkExpiresAt).getTime() < new Date(now).getTime();
                            if (!expired) {
                                applyBenchmarkToCard(matched);
                            }
                        }
                    });
                })
                .then(function() {
                    updateAnalysisSummary();
                    reconcileAuditStatus();
                    removeSkipLoading();
                })
                .catch(function(err) {
                    console.warn('[failed-inspection-state] Failed to fetch/apply failed inspection states:', err);
                    removeSkipLoading();
                });
        }

        function fireAndForgetReportUpdate() {
            var ctx = window.A11Y_AUDIT_CONTEXT;
            if (!ctx) return;
            var baseUrl = getServiceBaseUrl();
            var updateBody = {
                s3Key: getS3Key(),
                repository: ctx.repository,
                commitSha: ctx.commitSha
            };
            updateBody.prNumber = ctx.prNumber;
            console.info('[failed-inspection-state] fireAndForgetReportUpdate:', JSON.stringify(updateBody));
            fetch(baseUrl + '/v1/update-audit-report', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(updateBody)
            }).then(function(res) {
                console.info('[failed-inspection-state] reportUpdate response:', res.status, res.statusText);
                if (!res.ok) throw new Error(String(res.status));
            }).catch(function(err) {
                console.warn('[failed-inspection-state] Failed to update report:', err);
            });
        }

        function submitSkip(scope) {
            if (!_skipPending) return;
            var ctx = window.A11Y_AUDIT_CONTEXT;
            if (!ctx) return;

            var reason = getSkipReason();
            if (!validateSkipReason(reason)) return;

            setSkipModalState('loading');

            var pendingRuleId = _skipPending.ruleId;
            var pendingSelector = _skipPending.elementSelector;
            var pendingPageUrl = _skipPending.pageUrl;
            var pendingContainerSelector = _skipPending.containerSelector || '';

            var body = {
                inspectionState: {
                    repository: ctx.repository,
                    inspection: {
                        ruleId: pendingRuleId,
                        elementSelector: pendingSelector,
                        url: pendingPageUrl,
                        containerSelector: pendingContainerSelector
                    },
                    state: scope === 'pr' ? 'SKIPPED_PR' : 'SKIPPED_INDEFINITE'
                },
                dashboardUrl: window.location.href
            };
            body.inspectionState.prNumber = Number(ctx.prNumber);
            if (reason) {
                body.inspectionState.reason = reason;
            }

            var baseUrl = getServiceBaseUrl();
            console.info('[failed-inspection-state] submitSkip:', scope, JSON.stringify(body));
            fetch(baseUrl + '/v1/inspection-state', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(body)
            })
            .then(function(res) {
                console.info('[failed-inspection-state] submitSkip response:', res.status, res.statusText);
                if (!res.ok) throw new Error('Skip failed: ' + res.status);
                return res.json();
            })
            .then(function() {
                closeSkipModal();

                var card = findCardForFailedInspection(pendingRuleId, pendingSelector, pendingPageUrl, pendingContainerSelector);
                var appliedSkipType = scope === 'pr' ? 'SKIPPED_PR' : 'SKIPPED_INDEFINITE';
                if (card) {
                    if (card.classList.contains('failed-inspection-benchmarked')) {
                        removeBenchmarkFromCard(card);
                    }
                    applySkipToCard(card, appliedSkipType, reason);
                }

                updateAnalysisSummary();
                reconcileAuditStatus();
                showToast('Failed inspection skipped');
                fireAndForgetReportUpdate();

                try {
                    if (typeof biModalCtaClick === 'function') {
                        biModalCtaClick('failed inspection state flow', 'skip', '', pendingPageUrl);
                    }
                } catch(e) {}
            })
            .catch(function(err) {
                setSkipModalState('error', err.message || 'An error occurred');
            });
        }

        function submitUnskip(btn, ruleId, elementSelector, pageUrl, containerSelector) {
            var ctx = window.A11Y_AUDIT_CONTEXT;
            if (!ctx) return;
            if (btn.disabled) return;

            btn.disabled = true;
            btn.textContent = 'Restoring\\u2026';

            var baseUrl = getServiceBaseUrl();
            var body = {
                inspectionState: {
                    repository: ctx.repository,
                    inspection: {
                        ruleId: ruleId,
                        elementSelector: elementSelector,
                        url: pageUrl,
                        containerSelector: containerSelector || ''
                    }
                }
            };

            var unskipUrl = baseUrl + '/v1/inspection-states/' + encodeURIComponent(ctx.repository);
            console.info('[failed-inspection-state] submitUnskip URL:', unskipUrl, JSON.stringify(body));
            fetch(unskipUrl, {
                method: 'DELETE',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(body)
            })
            .then(function(res) {
                console.info('[failed-inspection-state] submitUnskip response:', res.status, res.statusText);
                if (!res.ok) throw new Error('Unskip failed: ' + res.status);
                return res.json();
            })
            .then(function(data) {
                var card = btn.closest('.failed-inspection-card, .failed-inspection-item');

                if (card) {
                    var action = data && data.action;

                    if (action === 'RESTORED_TO_BENCHMARKED') {
                        removeSkipFromCard(card);
                        applyBenchmarkToCard(card);
                        showToast('Failed inspection restored to pre-existing (non-blocking)');
                    } else {
                        removeSkipFromCard(card);
                        showToast('Failed inspection restored');
                    }
                }

                updateAnalysisSummary();
                reconcileAuditStatus();
                fireAndForgetReportUpdate();
            })
            .catch(function(err) {
                console.error('Failed to restore failed inspection:', err.message || err);
                btn.disabled = false;
                btn.textContent = '';
                btn.classList.add('unskip-error');
                btn.appendChild(document.createTextNode('Failed \\u2013 Retry'));
                btn.title = err.message || 'An error occurred';
            });
        }

        function submitFixWithAi(target) {
            if (!_fixAiPending) return;
            var ctx = window.A11Y_AUDIT_CONTEXT;
            if (!ctx) return;

            setFixAiModalState('loading');

            var pendingRuleId = _fixAiPending.ruleId;
            var pendingSelector = _fixAiPending.elementSelector;
            var pendingPageUrl = _fixAiPending.pageUrl;

            var card = findCardForFailedInspection(pendingRuleId, pendingSelector, pendingPageUrl, _fixAiPending.containerSelector);

            var failedInspection = {
                ruleId: pendingRuleId,
                elementSelector: pendingSelector,
                pageUrl: pendingPageUrl
            };

            if (card) {
                var msgEl = card.querySelector('.failed-inspection-message');
                if (msgEl) failedInspection.message = (msgEl.textContent || '').trim();

                var htmlEl = card.querySelector('.failed-inspection-html code');
                if (htmlEl) failedInspection.html = (htmlEl.textContent || '').trim();

                var helpEl = card.querySelector('.failed-inspection-help-link');
                if (helpEl) failedInspection.helpUrl = helpEl.getAttribute('href') || '';

                var titleEl = card.querySelector('.failed-inspection-title');
                if (titleEl) failedInspection.title = (titleEl.textContent || '').trim();

                var severityEl = card.querySelector('.severity-badge');
                if (severityEl) failedInspection.severity = (severityEl.textContent || '').trim().toLowerCase();

                var checkItems = card.querySelectorAll('.failed-inspection-check-list li');
                if (checkItems.length > 0) {
                    failedInspection.fixSuggestions = [];
                    for (var i = 0; i < checkItems.length; i++) {
                        var text = (checkItems[i].textContent || '').trim();
                        if (text) failedInspection.fixSuggestions.push(text);
                    }
                }
            }

            var body = {
                repository: ctx.repository,
                branch: ctx.branch || 'master',
                commitSha: ctx.commitSha,
                slackUsername: ctx.slackUsername || null,
                target: target === 'PR_BRANCH' ? 'FIX_TARGET_PR_BRANCH' : 'FIX_TARGET_MASTER',
                failedInspection: failedInspection
            };

            var baseUrl = getServiceBaseUrl();
            console.info('[fix-with-ai] submitFixWithAi:', target, JSON.stringify(body));
            fetch(baseUrl + '/v1/fix-with-ai', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(body)
            })
            .then(function(res) {
                console.info('[fix-with-ai] response:', res.status, res.statusText);
                if (!res.ok) throw new Error('Fix with AI failed: ' + res.status);
                return res.json();
            })
            .then(function() {
                closeFixAiModal();

                if (card) {
                    var existingBtn = card.querySelector('.fix-with-ai-btn');
                    if (existingBtn) {
                        existingBtn.disabled = true;
                        existingBtn.classList.add('fix-submitted');
                        existingBtn.textContent = '';
                        var checkSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
                        checkSvg.setAttribute('fill', 'none');
                        checkSvg.setAttribute('stroke', 'currentColor');
                        checkSvg.setAttribute('viewBox', '0 0 24 24');
                        var checkPath = document.createElementNS('http://www.w3.org/2000/svg', 'path');
                        checkPath.setAttribute('stroke-linecap', 'round');
                        checkPath.setAttribute('stroke-linejoin', 'round');
                        checkPath.setAttribute('stroke-width', '2');
                        checkPath.setAttribute('d', 'M5 13l4 4L19 7');
                        checkSvg.appendChild(checkPath);
                        existingBtn.appendChild(checkSvg);
                        existingBtn.appendChild(document.createTextNode('Submitted'));
                    }
                }

                var toastMsg = ctx.slackUsername
                    ? 'AI fix task submitted \\u2014 check Slack for the draft PR'
                    : 'AI fix task submitted \\u2014 a draft PR will be created';
                showToast(toastMsg);
            })
            .catch(function(err) {
                setFixAiModalState('error', err.message || 'An error occurred');
            });
        }
`;
