/**
 * Favicon data URL for embedding in HTML head
 */
export const A11Y_FAVICON_DATA_URL = `data:image/svg+xml,${encodeURIComponent(
  A11Y_LOGO_SVG,
)}`;

/**
 * Generates the favicon link tag for HTML head
 */
export const getFaviconLink = (): string =>
  `<link rel="icon" type="image/svg+xml" href="${A11Y_FAVICON_DATA_URL}">`;

/**
 * Converts an image source (URL string or ImageData) to an img src attribute value.
 * Supports both URL strings and ImageData objects with buffer or url.
 */
const getImageSrc = (image: string | ImageData | undefined): string | null => {
  if (!image) {
    return null;
  }
  if (typeof image === 'string') {
    return image;
  }
  if (image.buffer) {
    return `data:image/png;base64,${image.buffer.toString('base64')}`;
  }
  return image.url || null;
};

export const renderSuccessState = (options: SuccessStateOptions): string => {
  const {
    title,
    description,
    showIcon = true,
    iconColor = COLORS.status.success,
  } = options;

  const iconHtml = showIcon
    ? `
    <svg style="width: 24px; height: 24px; color: ${iconColor}; margin-bottom: 12px;" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" 
            d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
    </svg>`
    : '';

  return `
    <div class="passed-state">
      ${iconHtml}
      <h4>${title}</h4>
      <p>${description}</p>
    </div>`;
};

export const renderStatusBadge = (options: StatusBadgeOptions): string => {
  const { status, variant = 'default', className = '' } = options;
  const statusClass = getStatusClass(status);
  const sizeClass =
    variant === 'large'
      ? 'status-badge-large'
      : variant === 'small'
      ? 'status-badge-small'
      : '';

  return `<span class="status-badge ${statusClass} ${sizeClass} ${className}">${status.toUpperCase()}</span>`;
};

export const renderElementSelector = (selector: string): string =>
  `<div class="element-selector">${escapeHtml(selector)}</div>`;

export const renderElementCard = (options: ElementCardOptions): string => {
  const {
    selector,
    message,
    expandable = false,
    images,
    statusBadge = 'FAILED',
  } = options;

  const expandableAttrs = expandable
    ? 'tabindex="0" role="button" aria-expanded="false" onclick="toggleElement(this)" onkeydown="handleElementKeydown(event, this)"'
    : '';
  const chevronIcon = expandable
    ? `
    <svg class="element-chevron" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7" />
    </svg>`
    : '';

  const detailsSection = expandable
    ? `
    <div class="element-details">
      ${
        images
          ? renderImageComparison({
              afterImage: images.after,
              beforeImage: images.before,
            })
          : ''
      }
      <div class="reason">${escapeHtml(message)}</div>
    </div>`
    : `<div class="reason">${escapeHtml(message)}</div>`;

  return `
    <div class="element-card">
      <div class="element-header" ${expandableAttrs}>
        ${renderElementSelector(selector)}
        <div class="element-actions">
          ${renderStatusBadge({ status: statusBadge })}
          ${chevronIcon}
        </div>
      </div>
      ${detailsSection}
    </div>`;
};

export const renderImageComparison = (
  options: ImageComparisonOptions,
): string => {
  const {
    beforeImage,
    afterImage,
    beforeLabel = 'Before Focus',
    afterLabel = 'After Focus',
  } = options;

  if (!beforeImage && !afterImage) {
    return '';
  }

  return `
    <div class="image-comparison">
      <div class="image-container">
        <h4 class="image-label">${beforeLabel}</h4>
        ${createImageHtml(beforeImage, beforeLabel)}
      </div>
      <div class="image-container">
        <h4 class="image-label">${afterLabel}</h4>
        ${createImageHtml(afterImage, afterLabel)}
      </div>
    </div>`;
};

export const renderFailedInspectionList = (
  options: FailedInspectionListOptions,
): string => {
  const { failedInspections, showExpandable = false } = options;

  if (failedInspections.length === 0) {
    return `
      <div class="no-failures">
        <p>No specific failed inspections were identified.</p>
      </div>`;
  }

  return failedInspections
    .map((failedInspection) => {
      if (showExpandable) {
        return renderElementCard({
          expandable: true,
          message: failedInspection.message,
          selector: failedInspection.elementSelector || 'Unknown element',
        });
      } else {
        return `
          <div class="failed-inspection-item">
            ${renderElementSelector(
              failedInspection.elementSelector || 'Unknown element',
            )}
            <div class="failed-inspection-message">${escapeHtml(
              failedInspection.message,
            )}</div>
          </div>`;
      }
    })
    .join('');
};

export const renderWarningBox = (title: string, message: string): string => `
    <div class="warning-box">
      <h4>${escapeHtml(title)}</h4>
      <p>${escapeHtml(message)}</p>
    </div>`;

// Helper functions
const getStatusClass = (status: string): string => {
  switch (String(status).toUpperCase()) {
    case 'PASSED':
      return 'status-passed';
    case 'FAILED':
      return 'status-failed';
    case 'ERROR':
      return 'status-error';
    case 'SKIPPED':
      return 'status-skipped';
    default:
      return 'status-skipped';
  }
};

const createImageHtml = (
  image: string | ImageData | undefined,
  altText: string,
): string => {
  const src = getImageSrc(image);
  return src
    ? `<img src="${escapeHtml(src)}" alt="${escapeHtml(
        altText,
      )}" class="comparison-image" loading="lazy" />`
    : '<div class="image-placeholder">No image available</div>';
};

export const escapeHtml = (unsafe: string): string =>
  unsafe
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');

