import {
  SEVERITY_ALL,
  SEVERITY_CRITICAL,
  SEVERITY_MODERATE,
  SEVERITY_SERIOUS,
} from '../constants/report-strings';

export interface MainHeaderCounts {
  severity: { critical: number; serious: number; moderate: number };
}

export const mainHeaderTemplate = (counts: MainHeaderCounts): string => {
  const sev = counts.severity;
  const totalSev = sev.critical + sev.serious + sev.moderate;

  return `
    <div class="main-header">
      <div class="main-title-group">
        <h2 class="main-title" id="mainTitle">All failed components</h2>
        <span class="main-scope" id="mainScope" aria-live="polite"></span>
      </div>
      <div class="severity-dropdown-wrap" id="severityFilters">
        <button class="severity-dropdown-btn"
                id="sevDropdownBtn"
                type="button"
                aria-haspopup="listbox"
                aria-expanded="false"
                onclick="toggleSeverityDropdown(event)">
          <span class="severity-dropdown-label">${SEVERITY_ALL}</span>
        </button>
        <div class="severity-dropdown-menu" id="sevDropdownMenu" role="listbox" aria-label="Filter by severity">
          <button class="severity-dropdown-item active"
                  role="option"
                  type="button"
                  aria-selected="true"
                  data-severity="all"
                  onclick="selectSeverity(this)">
            <span class="sev-label">${SEVERITY_ALL}</span>
            <span class="sev-count">(${totalSev})</span>
          </button>
          <button class="severity-dropdown-item"
                  role="option"
                  type="button"
                  aria-selected="false"
                  data-severity="critical"
                  onclick="selectSeverity(this)">
            <span class="sev-dot critical" aria-hidden="true"></span>
            <span class="sev-label">${SEVERITY_CRITICAL}</span>
            <span class="sev-count">(${sev.critical})</span>
          </button>
          <button class="severity-dropdown-item"
                  role="option"
                  type="button"
                  aria-selected="false"
                  data-severity="serious"
                  onclick="selectSeverity(this)">
            <span class="sev-dot serious" aria-hidden="true"></span>
            <span class="sev-label">${SEVERITY_SERIOUS}</span>
            <span class="sev-count">(${sev.serious})</span>
          </button>
          <button class="severity-dropdown-item"
                  role="option"
                  type="button"
                  aria-selected="false"
                  data-severity="moderate"
                  onclick="selectSeverity(this)">
            <span class="sev-dot moderate" aria-hidden="true"></span>
            <span class="sev-label">${SEVERITY_MODERATE}</span>
            <span class="sev-count">(${sev.moderate})</span>
          </button>
        </div>
      </div>
    </div>`;
};
