/** Event listeners: DOMContentLoaded bootstrap and Escape key handler. */
export const initScripts = `
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape') {
                var modal = document.getElementById('skip-failed-inspection-modal');
                if (modal && modal.classList.contains('active')) {
                    closeSkipModal();
                }
                var fixAiModal = document.getElementById('fix-ai-modal');
                if (fixAiModal && fixAiModal.classList.contains('active')) {
                    closeFixAiModal();
                }
            }
        });

        document.addEventListener('DOMContentLoaded', function() {
            var ctx = window.A11Y_AUDIT_CONTEXT;
            console.info('[failed-inspection-state] DOMContentLoaded — ctx:', ctx ? JSON.stringify(ctx) : 'MISSING');
            injectSkipButtons();
            if (window.ENABLE_FIX_WITH_AI) {
                injectFixWithAiButtons();
            }
            injectUnskipButtons();
            fetchAndApplyFailedInspectionStates();
        });
`;
