/**
 * JavaScript for modal functionality
 * Provides functions to open/close modals with accessibility support
 */
export const modalScripts = `
    function openModal(modalId) {
        const modal = document.getElementById(modalId);
        if (modal) {
            modal.classList.add('active');
            document.body.style.overflow = 'hidden';

            // Focus the modal for accessibility
            const closeBtn = modal.querySelector('.modal-close');
            if (closeBtn) closeBtn.focus();

            // Add escape key listener
            document.addEventListener('keydown', handleEscapeKey);

            // BI: modal view
            try {
                if (typeof biModalView === 'function') {
                    var auditName = _biGetAuditNameFromModal(modal);
                    var url = _biGetUrlFromModal(modal);
                    var counts = _biGetModalInspectionCounts(modal);
                    biModalView('audit details', auditName, counts.total, counts.passed, counts.failed, url);
                }
            } catch(e) {}
        }
    }
    
    function closeModal(modalId) {
        const modal = document.getElementById(modalId);
        if (modal) {
            modal.classList.remove('active');
            document.body.style.overflow = '';
            document.removeEventListener('keydown', handleEscapeKey);
        }
    }
    
    function closeModalOnOverlay(event, modalId) {
        // Only close if clicking the overlay itself, not the modal content
        if (event.target.classList.contains('modal-overlay')) {
            closeModal(modalId);
        }
    }
    
    function handleEscapeKey(event) {
        if (event.key === 'Escape') {
            const activeModal = document.querySelector('.modal-overlay.active');
            if (activeModal) {
                closeModal(activeModal.id);
            }
        }
    }

    function toggleAuditSection(header) {
        const content = header.nextElementSibling;
        const isCollapsed = content.classList.contains('collapsed');
        
        if (isCollapsed) {
            content.classList.remove('collapsed');
            header.classList.add('expanded');
        } else {
            content.classList.add('collapsed');
            header.classList.remove('expanded');
        }
    }

    function toggleAuditsGroup(header) {
        const content = header.nextElementSibling;
        const isCollapsed = content.classList.contains('collapsed');

        if (isCollapsed) {
            content.classList.remove('collapsed');
            header.classList.add('expanded');
        } else {
            content.classList.add('collapsed');
            header.classList.remove('expanded');
        }

        // BI: section expand/collapse
        try {
            if (typeof biSectionExpandCollapse === 'function') {
                var section = _biGetSectionType(header);
                var titleEl = header.querySelector('.audits-group-title h3');
                var auditName = titleEl ? titleEl.textContent.trim() : '';
                var countEl = header.querySelector('.audits-group-count');
                var countText = countEl ? countEl.textContent.replace(/[()]/g, '').trim() : '';
                var modal = header.closest('.modal-overlay');
                var url = modal ? _biGetUrlFromModal(modal) : '';
                biSectionExpandCollapse(isCollapsed ? 'expand' : 'collapse', section, auditName, countText, '', '', url);
            }
        } catch(e) {}
    }

    function toggleAuditsGroupItem(header) {
        const content = header.nextElementSibling;
        const isCollapsed = content.classList.contains('collapsed');

        if (isCollapsed) {
            content.classList.remove('collapsed');
            header.classList.add('expanded');
        } else {
            content.classList.add('collapsed');
            header.classList.remove('expanded');
        }

        // BI: inspection expand/collapse
        try {
            if (typeof biInspectionExpandCollapse === 'function') {
                var ctx = _biGetInspectionContext(header);
                var modal = header.closest('.modal-overlay');
                var url = modal ? _biGetUrlFromModal(modal) : '';
                biInspectionExpandCollapse(
                    isCollapsed ? 'expand' : 'collapse',
                    ctx.auditName || '',
                    ctx.inspectionName || '',
                    '',
                    0, 0, 0, 0, 0,
                    url
                );
            }
        } catch(e) {}
    }
`;
