import { ReportStats } from '../types';

export const fillTemplate = (
  template: string,
  data: Record<string, unknown>,
): string => {
  return Object.entries(data).reduce(
    (result, [key, value]) =>
      result.replace(new RegExp(`{{${key}}}`, 'g'), String(value ?? '')),
    template,
  );
};

export const calculateCoverage = (
  totalElements: number,
  failedElements: number,
): number => {
  if (totalElements === 0) {
    return 100;
  }
  return Math.round(((totalElements - failedElements) / totalElements) * 100);
};

export const createReportStats = (
  totalElements: number = 0,
  failedElements: number = 0,
): ReportStats => {
  return {
    coverage: calculateCoverage(totalElements, failedElements),
    failedElements,
    totalElements,
  };
};

export const groupBy = <T, K extends string | number>(
  array: T[],
  keyFn: (item: T) => K,
): Record<K, T[]> => {
  return array.reduce((groups, item) => {
    const key = keyFn(item);
    if (!groups[key]) {
      groups[key] = [];
    }
    groups[key].push(item);
    return groups;
  }, {} as Record<K, T[]>);
};

export const ensureValidUrl = (url: string | undefined): string | undefined => {
  if (!url) {
    return undefined;
  }

  try {
    new URL(url);
    return url;
  } catch {
    return url.startsWith('http') ? url : undefined;
  }
};
