import { biScripts } from '../../../../bi';
import { getWebBiLoggerBundle } from '../../../../bi/bi-bundle';
import {
  ENABLE_FAILED_INSPECTION_STATE_FLOW,
  ENABLE_FIX_WITH_AI,
} from '../../../../constants';
import { failedInspectionStateScripts } from '../../../../failed-inspection-state-flow/dashboard';
import { escapeHtml, getFaviconLink } from '../../components';
import {
  layoutStyles,
  modalScripts,
  modalStyles,
  multiPageScripts,
  multiPageStyles,
  themeToggleScripts,
} from '../../styles';
import type { MultiPageReportData } from '../../types';
import { InspectionStatus } from '../../types';
import { failedInspectionsListTemplate } from './sections/failed-inspection-cards';
import { fixWithAiModalTemplate } from './sections/fix-with-ai-modal';
import { multiPageHeaderTemplate } from './sections/header';
import { mainHeaderTemplate } from './sections/main-header';
import { groupedModalTemplate } from './sections/modal';
import { sidebarTemplate } from './sections/sidebar';
import { skipModalTemplate } from './sections/skip-modal';
import { summaryBannerTemplate } from './sections/summary-banner';
import { getReportTitle, toSafeJson } from './utils';
import {
  aggregatePackageTree,
  aggregateRuleGroups,
} from './utils/aggregate-rule-groups';

export const multiPageReportTemplate = (data: MultiPageReportData): string => {
  const { summary, metadata, pages } = data;
  const warningsCount =
    pages.filter((page) => page.status === InspectionStatus.WARNING).length +
    (data.benchmarkPages?.filter(
      (page) => page.status === InspectionStatus.WARNING,
    ).length ?? 0);

  const { ruleGroups, passed } = aggregateRuleGroups(data);
  const packageTree = aggregatePackageTree(data, ruleGroups);

  const failedGroupCount = ruleGroups.filter((rg) =>
    rg.instances.some((i) => i.status === 'new'),
  ).length;
  const preExistingGroupCount = ruleGroups.filter((rg) =>
    rg.instances.every((i) => i.status === 'pre-existing'),
  ).length;
  const passedCount = passed.length;
  const totalComponents = ruleGroups.length + passedCount;

  const severityCounts = ruleGroups.reduce(
    (acc, rg) => {
      if (rg.highestSeverity === 'critical') {
        acc.critical += 1;
      } else if (rg.highestSeverity === 'serious') {
        acc.serious += 1;
      } else if (rg.highestSeverity === 'moderate') {
        acc.moderate += 1;
      }
      return acc;
    },
    { critical: 0, moderate: 0, serious: 0 },
  );

  const bannerCounts = {
    failed: failedGroupCount,
    passed: passedCount,
    preExisting: preExistingGroupCount,
    total: totalComponents,
  };

  const mainHeaderCounts = {
    severity: severityCounts,
  };

  const allPages = [...pages, ...(data.benchmarkPages ?? [])];
  const modalsHtml = allPages
    .filter((group) => group.audits.some((audit) => audit.reportContent))
    .map((group) => groupedModalTemplate(group))
    .join('\n');

  const reportTitle = getReportTitle();

  return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>ELEVEN A11Y Plugin - ${escapeHtml(reportTitle)}</title>
    ${getFaviconLink()}
    <style>{{styles}}
    ${multiPageStyles}
    ${modalStyles}
    ${layoutStyles}
    </style>
    <script>${themeToggleScripts}</script>
</head>
<body${data.metadata.auditContext ? ' data-skip-loading' : ''}>
    ${multiPageHeaderTemplate()}

    <div class="page-wrapper">
        ${summaryBannerTemplate(summary, metadata, bannerCounts)}

        <div class="layout">
            ${sidebarTemplate(packageTree)}

            <main class="main-content" aria-label="Audit details">
                ${mainHeaderTemplate(mainHeaderCounts)}
                ${failedInspectionsListTemplate(packageTree, passed)}
            </main>
        </div>
    </div>

    ${modalsHtml}

    ${data.metadata.auditContext ? skipModalTemplate() : ''}
    ${
      ENABLE_FIX_WITH_AI && data.metadata.auditContext
        ? fixWithAiModalTemplate()
        : ''
    }

    <script type="application/json" id="a11y-report-data">${toSafeJson(
      data,
    )}</script>
    ${
      data.metadata.auditContext
        ? `<script>window.A11Y_AUDIT_CONTEXT = ${toSafeJson(
            data.metadata.auditContext,
          )};</script>`
        : ''
    }
    ${
      data.metadata.benchmarkMetadata
        ? `<script>window.A11Y_BENCHMARK_METADATA = ${toSafeJson(
            data.metadata.benchmarkMetadata,
          )};</script>`
        : ''
    }
    <script>window.ENABLE_FAILED_INSPECTION_STATE_FLOW = ${ENABLE_FAILED_INSPECTION_STATE_FLOW};</script>
    <script>window.ENABLE_FIX_WITH_AI = ${ENABLE_FIX_WITH_AI};</script>
    <script>window.A11Y_BI_META = ${toSafeJson({
      failedAuditsCount: String(summary.failedPages),
      passedAuditsCount: String(summary.passedPages),
      reportGeneratedTs: data.metadata.timestamp,
      totalAuditsCount: String(summary.totalPages),
      totalFailedInspections: summary.totalFailedInspections,
      warningsCount: String(warningsCount),
    })};</script>
    <script>${getWebBiLoggerBundle()}</script>
    <script>{{scripts}}
    ${multiPageScripts}
    ${modalScripts}
    ${data.metadata.auditContext ? failedInspectionStateScripts : ''}
    ${biScripts}
    </script>
</body>
</html>`;
};
