/** Benchmarked failed inspections container: create, toggle, and update count. */
export const benchmarkedContainerScripts = `
        function getOrCreateBenchmarkedContainer(groupContent) {
            var existing = groupContent.querySelector('.benchmarked-failed-inspections-container');
            if (existing) return existing;

            var container = document.createElement('div');
            container.className = 'benchmarked-failed-inspections-container';

            var header = document.createElement('div');
            header.className = 'benchmarked-failed-inspections-header';
            header.setAttribute('role', 'button');
            header.setAttribute('tabindex', '0');
            header.setAttribute('aria-expanded', 'false');
            header.addEventListener('click', function() {
                toggleBenchmarkedSection(header);
            });
            header.addEventListener('keydown', function(e) {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    toggleBenchmarkedSection(header);
                }
            });

            var labelSpan = document.createElement('span');
            labelSpan.className = 'benchmarked-failed-inspections-label';
            labelSpan.appendChild(document.createTextNode('Pre-existing '));

            var badge = document.createElement('span');
            badge.className = 'benchmark-badge';
            badge.textContent = 'Non-blocking';
            labelSpan.appendChild(badge);

            labelSpan.appendChild(document.createTextNode(' ('));
            var countSpan = document.createElement('span');
            countSpan.className = 'benchmarked-count';
            countSpan.textContent = '0';
            labelSpan.appendChild(countSpan);
            labelSpan.appendChild(document.createTextNode(')'));
            header.appendChild(labelSpan);

            var chevron = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
            chevron.setAttribute('class', 'benchmarked-chevron');
            chevron.setAttribute('fill', 'none');
            chevron.setAttribute('stroke', 'currentColor');
            chevron.setAttribute('viewBox', '0 0 24 24');
            var chevronPath = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            chevronPath.setAttribute('stroke-linecap', 'round');
            chevronPath.setAttribute('stroke-linejoin', 'round');
            chevronPath.setAttribute('stroke-width', '2');
            chevronPath.setAttribute('d', 'M19 9l-7 7-7-7');
            chevron.appendChild(chevronPath);
            header.appendChild(chevron);

            container.appendChild(header);

            var list = document.createElement('div');
            list.className = 'benchmarked-failed-inspections-list';
            container.appendChild(list);

            groupContent.appendChild(container);
            return container;
        }

        function toggleBenchmarkedSection(header) {
            var container = header.closest('.benchmarked-failed-inspections-container');
            if (!container) return;
            container.classList.toggle('expanded');
            var isExpanded = container.classList.contains('expanded');
            header.setAttribute('aria-expanded', isExpanded ? 'true' : 'false');
        }

        function updateBenchmarkedCount(container) {
            var list = container.querySelector('.benchmarked-failed-inspections-list');
            var count = list ? list.children.length : 0;
            var label = container.querySelector('.benchmarked-count');
            if (label) label.textContent = count;
            container.style.display = count > 0 ? '' : 'none';
        }
`;
