/** Audit-level status reconciliation: moves page rows between groups when all failed inspections are skipped/unskipped. */
export const auditStatusScripts = `
        function isFailedInspectionStateFlowEnabled() {
            return !!window.ENABLE_FAILED_INSPECTION_STATE_FLOW;
        }

        function getOrCreateSkippedPageGroup() {
            var existing = document.querySelector('.page-group-skipped');
            if (existing) return existing;

            var group = document.createElement('div');
            group.className = 'page-group page-group-skipped';

            var header = document.createElement('div');
            header.className = 'page-group-header collapsible';
            header.setAttribute('onclick', 'togglePageGroup(this)');

            var titleDiv = document.createElement('div');
            titleDiv.className = 'page-group-title';

            var iconSpan = document.createElement('span');
            iconSpan.className = 'group-icon';
            var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
            svg.setAttribute('fill', 'none');
            svg.setAttribute('stroke', 'currentColor');
            svg.setAttribute('viewBox', '0 0 24 24');
            svg.setAttribute('width', '24');
            svg.setAttribute('height', '24');
            var path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            path.setAttribute('stroke-linecap', 'round');
            path.setAttribute('stroke-linejoin', 'round');
            path.setAttribute('stroke-width', '2');
            path.setAttribute('d', 'M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z');
            svg.appendChild(path);
            iconSpan.appendChild(svg);

            var h2 = document.createElement('h2');
            h2.textContent = 'Skipped Audits';

            var pageCount = document.createElement('span');
            pageCount.className = 'page-count';
            pageCount.textContent = '(0)';

            titleDiv.appendChild(iconSpan);
            titleDiv.appendChild(h2);
            titleDiv.appendChild(pageCount);

            var chevron = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
            chevron.setAttribute('class', 'chevron');
            chevron.setAttribute('fill', 'none');
            chevron.setAttribute('stroke', 'currentColor');
            chevron.setAttribute('viewBox', '0 0 24 24');
            var chevronPath = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            chevronPath.setAttribute('stroke-linecap', 'round');
            chevronPath.setAttribute('stroke-linejoin', 'round');
            chevronPath.setAttribute('stroke-width', '2');
            chevronPath.setAttribute('d', 'M19 9l-7 7-7-7');
            chevron.appendChild(chevronPath);

            header.appendChild(titleDiv);
            header.appendChild(chevron);

            var content = document.createElement('div');
            content.className = 'page-group-content';

            var table = document.createElement('table');
            table.className = 'pages-table';
            var thead = document.createElement('thead');
            var tr = document.createElement('tr');
            var headers = ['Audits', 'Inspections', 'Failed Inspections'];
            var colClasses = ['col-page', 'col-audits', 'col-failed-inspections'];
            if (isFailedInspectionStateFlowEnabled()) {
                headers.push('Skipped Inspections');
                colClasses.push('col-skipped');
            }
            headers.push('Actions');
            colClasses.push('col-actions');
            for (var i = 0; i < headers.length; i++) {
                var th = document.createElement('th');
                th.className = colClasses[i];
                th.textContent = headers[i];
                tr.appendChild(th);
            }
            thead.appendChild(tr);
            table.appendChild(thead);
            var tbody = document.createElement('tbody');
            table.appendChild(tbody);
            content.appendChild(table);

            group.appendChild(header);
            group.appendChild(content);

            var container = document.querySelector('.container');
            if (!container) return group;

            var passedGroup = container.querySelector('.page-group-passed');
            if (passedGroup) {
                container.insertBefore(group, passedGroup);
            } else {
                container.appendChild(group);
            }
            return group;
        }

        function movePageRowToSkippedGroup(row) {
            var sourceGroup = row.closest('.page-group');
            if (sourceGroup) {
                var cls = sourceGroup.className.match(/page-group-(\\w+)/);
                if (cls) row.setAttribute('data-original-section', cls[1]);
            }
            row.className = row.className.replace(/\\bstatus-\\w+/g, '') + ' status-skipped';
            var skippedGroup = getOrCreateSkippedPageGroup();
            var tbody = skippedGroup.querySelector('tbody');
            if (tbody) tbody.appendChild(row);
        }

        function movePageRowToFailedGroup(row) {
            var originalSection = row.getAttribute('data-original-section') || 'failed';
            row.removeAttribute('data-original-section');
            row.className = row.className.replace(/\\bstatus-\\w+/g, '') + ' status-' + originalSection;
            var targetGroup = document.querySelector('.page-group-' + originalSection);
            if (!targetGroup) return;
            var tbody = targetGroup.querySelector('tbody');
            if (tbody) tbody.appendChild(row);
        }

        function updatePageGroupCounts() {
            var groups = document.querySelectorAll('.page-group');
            for (var i = 0; i < groups.length; i++) {
                if (groups[i].classList.contains('page-group-benchmark')) continue;
                var tbody = groups[i].querySelector('tbody');
                var count = tbody ? tbody.querySelectorAll('.page-row').length : 0;
                var countEl = groups[i].querySelector('.page-count');
                if (countEl) countEl.textContent = '(' + count + ')';
            }
        }

        function updateSummaryCards() {
            var failedGroup = document.querySelector('.page-group-failed');
            var failedCount = 0;
            if (failedGroup) {
                var tbody = failedGroup.querySelector('tbody');
                failedCount = tbody ? tbody.querySelectorAll('.page-row').length : 0;
            }

            var failedEl = document.querySelector('.summary-failed .summary-number');
            if (failedEl) failedEl.textContent = failedCount;

            var newIssuesEl = document.querySelector('.summary-new-issues .summary-number');
            if (newIssuesEl) {
                var totalViolEl = document.querySelector('.summary-failed-inspections .summary-number');
                var totalViol = totalViolEl ? (parseInt(totalViolEl.textContent, 10) || 0) : 0;
                newIssuesEl.textContent = totalViol;
            }
        }

        function updatePrStatusBanner() {
            var banner = document.querySelector('.pr-status-banner');
            if (!banner) return;

            var totalViolEl = document.querySelector('.summary-failed-inspections .summary-number');
            var totalViol = totalViolEl ? (parseInt(totalViolEl.textContent, 10) || 0) : 0;

            var newIssuesEl = document.querySelector('.summary-new-issues .summary-number');
            var activeIssues = newIssuesEl ? (parseInt(newIssuesEl.textContent, 10) || 0) : totalViol;

            var titleEl = banner.querySelector('.pr-status-title');
            var descEl = banner.querySelector('.pr-status-desc');
            var iconEl = banner.querySelector('.pr-status-icon');

            if (activeIssues === 0 && banner.classList.contains('pr-blocked')) {
                banner.classList.remove('pr-blocked');
                banner.classList.add('pr-passing');
                if (iconEl) iconEl.textContent = '\\u2713';
                if (titleEl) titleEl.textContent = 'PR Passing \\u2014 No new accessibility issues';
                if (descEl) descEl.textContent = 'This PR introduces no new accessibility issues.';
            } else if (activeIssues > 0 && banner.classList.contains('pr-passing')) {
                banner.classList.remove('pr-passing');
                banner.classList.add('pr-blocked');
                if (iconEl) iconEl.textContent = '\\u2717';
                if (titleEl) titleEl.textContent = 'PR Blocked \\u2014 ' + activeIssues + ' new accessibility issue' + (activeIssues !== 1 ? 's' : '') + ' found';
                if (descEl) descEl.textContent = 'This PR introduced new accessibility issues. Pre-existing issues are non-blocking.';
            }
        }

        function hideEmptyPageGroups() {
            var groups = document.querySelectorAll('.page-group');
            for (var i = 0; i < groups.length; i++) {
                var tbody = groups[i].querySelector('tbody');
                var count = tbody ? tbody.querySelectorAll('.page-row').length : 0;
                groups[i].style.display = count === 0 ? 'none' : '';
            }
        }

        function getOrCreateSkippedAuditsGroup(modalBody) {
            var existing = modalBody.querySelector('.audits-group-muted');
            if (existing) return existing;

            var group = document.createElement('div');
            group.className = 'audits-group audits-group-muted';

            var header = document.createElement('div');
            header.className = 'audits-group-header collapsible';
            header.setAttribute('onclick', 'toggleAuditsGroup(this)');

            var titleDiv = document.createElement('div');
            titleDiv.className = 'audits-group-title';

            var iconSpan = document.createElement('span');
            iconSpan.className = 'audits-group-icon';
            var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
            svg.setAttribute('fill', 'none');
            svg.setAttribute('stroke', 'currentColor');
            svg.setAttribute('viewBox', '0 0 24 24');
            svg.setAttribute('width', '20');
            svg.setAttribute('height', '20');
            var path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            path.setAttribute('stroke-linecap', 'round');
            path.setAttribute('stroke-linejoin', 'round');
            path.setAttribute('stroke-width', '2');
            path.setAttribute('d', 'M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z');
            svg.appendChild(path);
            iconSpan.appendChild(svg);

            var h3 = document.createElement('h3');
            h3.textContent = 'Skipped Inspections';

            var countSpan = document.createElement('span');
            countSpan.className = 'audits-group-count';
            countSpan.textContent = '(0)';

            titleDiv.appendChild(iconSpan);
            titleDiv.appendChild(h3);
            titleDiv.appendChild(countSpan);

            var chevron = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
            chevron.setAttribute('class', 'audits-group-chevron');
            chevron.setAttribute('fill', 'none');
            chevron.setAttribute('stroke', 'currentColor');
            chevron.setAttribute('viewBox', '0 0 24 24');
            chevron.setAttribute('width', '20');
            chevron.setAttribute('height', '20');
            var chevronPath = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            chevronPath.setAttribute('stroke-linecap', 'round');
            chevronPath.setAttribute('stroke-linejoin', 'round');
            chevronPath.setAttribute('stroke-width', '2');
            chevronPath.setAttribute('d', 'M19 9l-7 7-7-7');
            chevron.appendChild(chevronPath);

            header.appendChild(titleDiv);
            header.appendChild(chevron);

            var content = document.createElement('div');
            content.className = 'audits-group-content';
            var list = document.createElement('div');
            list.className = 'audits-group-list';
            content.appendChild(list);

            group.appendChild(header);
            group.appendChild(content);

            modalBody.appendChild(group);
            return group;
        }

        function reconcileInspectionGroups() {
            var modals = document.querySelectorAll('.modal-overlay');
            for (var m = 0; m < modals.length; m++) {
                var modalBody = modals[m].querySelector('.modal-body');
                if (!modalBody) continue;

                var nonSkippedGroups = modalBody.querySelectorAll('.audits-group:not(.audits-group-muted):not(.audits-group-success)');
                for (var g = 0; g < nonSkippedGroups.length; g++) {
                    var list = nonSkippedGroups[g].querySelector('.audits-group-list');
                    if (!list) continue;
                    var items = list.querySelectorAll('.audits-group-item');
                    for (var i = items.length - 1; i >= 0; i--) {
                        var countEl = items[i].querySelector('.audits-group-item-failed-inspections');
                        if (!countEl) continue;
                        var match = (countEl.textContent || '').match(/(\\d+)/);
                        var count = match ? parseInt(match[1], 10) : 0;
                        if (count === 0) {
                            var sourceGroup = items[i].closest('.audits-group');
                            if (sourceGroup) {
                                var cls = sourceGroup.className.match(/audits-group-(\\w+)/);
                                if (cls && cls[1] !== 'item' && cls[1] !== 'muted') {
                                    items[i].setAttribute('data-original-audits-group', cls[1]);
                                }
                            }
                            var skippedGroup = getOrCreateSkippedAuditsGroup(modalBody);
                            var skippedList = skippedGroup.querySelector('.audits-group-list');
                            if (skippedList) skippedList.appendChild(items[i]);
                        }
                    }
                }

                var skippedGroup = modalBody.querySelector('.audits-group-muted');
                if (skippedGroup) {
                    var skippedList = skippedGroup.querySelector('.audits-group-list');
                    if (skippedList) {
                        var skippedItems = skippedList.querySelectorAll('.audits-group-item[data-original-audits-group]');
                        for (var j = skippedItems.length - 1; j >= 0; j--) {
                            var countEl2 = skippedItems[j].querySelector('.audits-group-item-failed-inspections');
                            if (!countEl2) continue;
                            var match2 = (countEl2.textContent || '').match(/(\\d+)/);
                            var count2 = match2 ? parseInt(match2[1], 10) : 0;
                            if (count2 > 0) {
                                var origClass = skippedItems[j].getAttribute('data-original-audits-group');
                                skippedItems[j].removeAttribute('data-original-audits-group');
                                if (origClass) {
                                    var targetGroup = modalBody.querySelector('.audits-group-' + origClass);
                                    if (targetGroup) {
                                        var targetList = targetGroup.querySelector('.audits-group-list');
                                        if (targetList) targetList.appendChild(skippedItems[j]);
                                    }
                                }
                            }
                        }
                    }
                }

                var allGroups = modalBody.querySelectorAll('.audits-group');
                for (var k = 0; k < allGroups.length; k++) {
                    var grpList = allGroups[k].querySelector('.audits-group-list');
                    var itemCount = grpList ? grpList.querySelectorAll('.audits-group-item').length : 0;
                    var grpCountEl = allGroups[k].querySelector('.audits-group-count');
                    if (grpCountEl) grpCountEl.textContent = '(' + itemCount + ')';
                    allGroups[k].style.display = itemCount === 0 ? 'none' : '';
                }
            }
        }

        function reconcileAuditStatus() {
            var failedGroups = document.querySelectorAll('.page-group-failed, .page-group-warning');
            for (var g = 0; g < failedGroups.length; g++) {
                var rows = failedGroups[g].querySelectorAll('tbody .page-row');
                for (var i = rows.length - 1; i >= 0; i--) {
                    var countEl = rows[i].querySelector('.failed-inspections-count, .no-failed-inspections');
                    var count = countEl ? (parseInt(countEl.textContent, 10) || 0) : 0;
                    if (count === 0) {
                        movePageRowToSkippedGroup(rows[i]);
                    }
                }
            }

            var skippedGroup = document.querySelector('.page-group-skipped');
            if (skippedGroup) {
                var skippedRows = skippedGroup.querySelectorAll('tbody .page-row[data-original-section]');
                for (var j = skippedRows.length - 1; j >= 0; j--) {
                    var countEl2 = skippedRows[j].querySelector('.failed-inspections-count, .no-failed-inspections');
                    var count2 = countEl2 ? (parseInt(countEl2.textContent, 10) || 0) : 0;
                    if (count2 > 0) {
                        movePageRowToFailedGroup(skippedRows[j]);
                    }
                }
            }

            updatePageGroupCounts();
            updateSummaryCards();
            updatePrStatusBanner();
            hideEmptyPageGroups();
            reconcileInspectionGroups();
        }
`;
