import { escapeHtml } from '../../../components';
import type { PageInspectionResult, UrlGroupedResult } from '../../../types';
import { InspectionStatus } from '../../../types';
import { getStatusGroupConfig } from '../components/icons';
import {
  MODAL_ITEM_NO_DETAILS,
  MODAL_NO_DETAILS,
} from '../constants/report-strings';

export const groupedModalTemplate = (group: UrlGroupedResult): string => {
  const auditsWithContent = group.audits.filter((a) => a.reportContent);

  const failedAudits = auditsWithContent.filter(
    (a) => a.status === InspectionStatus.FAILED,
  );
  const warningAudits = auditsWithContent.filter(
    (a) => a.status === InspectionStatus.WARNING,
  );
  const errorAudits = auditsWithContent.filter(
    (a) => a.status === InspectionStatus.ERROR,
  );
  const skippedAudits = auditsWithContent.filter(
    (a) => a.status === InspectionStatus.SKIPPED,
  );
  const passedAudits = auditsWithContent.filter(
    (a) => a.status === InspectionStatus.PASSED,
  );

  const sections: string[] = [];

  if (failedAudits.length > 0) {
    sections.push(
      auditsGroupTemplate(
        failedAudits,
        InspectionStatus.FAILED,
        false,
        group.pageUrl,
      ),
    );
  }
  if (warningAudits.length > 0) {
    sections.push(
      auditsGroupTemplate(
        warningAudits,
        InspectionStatus.WARNING,
        sections.length > 0,
        group.pageUrl,
      ),
    );
  }
  if (errorAudits.length > 0) {
    sections.push(
      auditsGroupTemplate(
        errorAudits,
        InspectionStatus.ERROR,
        sections.length > 0,
        group.pageUrl,
      ),
    );
  }
  if (skippedAudits.length > 0) {
    sections.push(
      auditsGroupTemplate(
        skippedAudits,
        InspectionStatus.SKIPPED,
        sections.length > 0,
        group.pageUrl,
      ),
    );
  }
  if (passedAudits.length > 0) {
    sections.push(
      auditsGroupTemplate(
        passedAudits,
        InspectionStatus.PASSED,
        sections.length > 0,
        group.pageUrl,
      ),
    );
  }

  const auditSections = sections.join('\n');

  return `
    <div id="${
      group.modalId
    }" class="modal-overlay" onclick="closeModalOnOverlay(event, '${
    group.modalId
  }')">
        <div class="modal-container">
            <div class="modal-header">
                <div class="modal-title">
                    <h2>${escapeHtml(group.pageName)}</h2>
                    <span class="modal-status status-${group.status}">${
    group.status
  }</span>
                    <span class="modal-audit-count">${
                      group.audits.length
                    } audit${group.audits.length !== 1 ? 's' : ''}</span>
                </div>
                <button class="modal-close" onclick="closeModal('${
                  group.modalId
                }')" aria-label="Close modal">
                    <svg fill="none" stroke="currentColor" viewBox="0 0 24 24" width="24" height="24">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12" />
                    </svg>
                </button>
            </div>
            <div class="modal-body">
                <div class="modal-url-info">
                    <span class="modal-url-label">URL:</span>
                    <a href="${escapeHtml(
                      group.pageUrl,
                    )}" class="modal-url-link" target="_blank" rel="noopener noreferrer">
                        ${escapeHtml(group.pageUrl)}
                    </a>
                </div>
                ${
                  auditSections ||
                  `<p class="no-details">${MODAL_NO_DETAILS}</p>`
                }
            </div>
        </div>
    </div>
  `;
};

export const auditsGroupTemplate = (
  audits: PageInspectionResult[],
  status: InspectionStatus,
  hasDivider: boolean,
  pageUrl?: string,
): string => {
  const config = getStatusGroupConfig(status);
  const isCollapsed = config.collapsedByDefault;
  const headerExpandedClass = isCollapsed ? '' : 'expanded';
  const contentCollapsedClass = isCollapsed ? 'collapsed' : '';

  const itemsList = audits
    .map(
      (audit) => `
      <div class="audits-group-item" data-inspection-id="${escapeHtml(
        audit.inspectionId || '',
      )}" data-page-url="${escapeHtml(
        pageUrl || '',
      )}" data-container-selector="${escapeHtml(
        audit.containerSelector || '',
      )}">
        <div class="audits-group-item-header collapsible" onclick="toggleAuditsGroupItem(this)">
          <span class="audits-group-item-icon">${config.icon}</span>
          <div class="audits-group-item-info">
            <span class="audits-group-item-name">${escapeHtml(
              audit.inspectionName || 'Unknown Inspection',
            )}</span>
          </div>
          <span class="audits-group-item-failed-inspections">${
            audit.failedInspectionCount
          } failed inspection${
        audit.failedInspectionCount !== 1 ? 's' : ''
      }</span>
          <span class="audits-group-item-time">${(
            audit.executionTime / 1000
          ).toFixed(1)}s</span>
          <svg class="audits-group-item-chevron" fill="none" stroke="currentColor" viewBox="0 0 24 24" width="16" height="16">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7" />
          </svg>
        </div>
        <div class="audits-group-item-content collapsed">
          ${
            audit.reportContent ||
            `<p class="no-details">${MODAL_ITEM_NO_DETAILS}</p>`
          }
        </div>
      </div>
    `,
    )
    .join('\n');

  return `
    <div class="audits-group audits-group-${config.color} ${
    hasDivider ? 'audits-group-divider' : ''
  }">
      <div class="audits-group-header collapsible ${headerExpandedClass}" onclick="toggleAuditsGroup(this)">
        <div class="audits-group-title">
          <span class="audits-group-icon">${config.icon}</span>
          <h3>${config.title}</h3>
          <span class="audits-group-count">(${audits.length})</span>
        </div>
        <svg class="audits-group-chevron" fill="none" stroke="currentColor" viewBox="0 0 24 24" width="20" height="20">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7" />
        </svg>
      </div>
      <div class="audits-group-content ${contentCollapsedClass}">
        <div class="audits-group-list">
          ${itemsList}
        </div>
      </div>
    </div>
  `;
};
