import type { ElementHandle, Frame, Page } from '@playwright/test';

import {
  GITHUB_CHECK_ALWAYS_PASS,
  TREAT_FAILURES_AS_WARNINGS,
} from '../constants';
import type {
  BaseFailedInspection,
  FailedInspectionsRenderResult,
} from '../utils/html-report/components/types';
import type { ScreenshotOptions } from './screenshot';

export interface BaseExecutionContext {
  page: Page | Frame;
  container: ElementHandle<Element>;
  options: Record<string, unknown>;
  /** Screenshot options including iframe offset if needed */
  screenshotOptions?: ScreenshotOptions;
}

export enum InspectionStatus {
  PASSED = 'passed',
  FAILED = 'failed',
  WARNING = 'warning',
  ERROR = 'error',
  SKIPPED = 'skipped',
}

export interface FailedInspection {
  message: string;
  elementSelector?: string;
  elementAttributes?: Record<string, string>;
  /** Block level: FAILED = blocks CI, WARNING = passes CI. Defaults to WARNING. */
  blockLevel?: InspectionStatus;
  /** Optional before/after screenshots for visual inspections (e.g., focus ring). */
  images?: {
    before?: string;
    after?: string;
  };
}

export interface InspectionResult {
  status: InspectionStatus;
  message?: string;
  details?: Record<string, unknown>;
  failedInspections?: FailedInspection[];
  stats?: {
    totalElements: number;
    failedElements: number;
    coverage: number;
  };
}

export interface Inspection<
  TInspectionId extends string,
  TInspectionContext extends BaseExecutionContext,
  TInspectionResult extends InspectionResult,
  TFailedInspection extends BaseFailedInspection = BaseFailedInspection,
> {
  id: TInspectionId;
  name: string;
  description: string;
  execute: (context: TInspectionContext) => Promise<TInspectionResult>;
  reportRenderer?: (
    result: TInspectionResult,
  ) => FailedInspectionsRenderResult<TFailedInspection>;
}

/** Inspection result for a single page in a multi-page scan */
export interface PageInspectionResult extends InspectionResult {
  pageUrl: string;
  pageName: string;
  storyId?: string;
  componentName?: string;
  containerSelector?: string;
  failedInspectionCount: number;
  executionTime: number;
  reportPath?: string;
  reportContent?: string;
  /** Report content generated from all failed inspections (before filtering). */
  unfilteredReportContent?: string;
  auditId?: string;
  auditName?: string;
  inspectionId?: string;
  inspectionName?: string;
  /** Name of the package this result belongs to */
  packageName?: string;
}

export interface MultiPageSummary {
  totalPages: number;
  passedPages: number;
  failedPages: number;
  errorPages: number;
  skippedPages: number;
  totalFailedInspections: number;
  totalExecutionTime: number;
}

/** Returns true if status should pass CI (not a blocking failure) */
export const isPassingStatus = (status: InspectionStatus): boolean => {
  // Always pass when GitHub check enforcement is disabled
  if (GITHUB_CHECK_ALWAYS_PASS) {
    return true;
  }

  // Treat failures as warnings (non-blocking)
  if (TREAT_FAILURES_AS_WARNINGS && status === InspectionStatus.FAILED) {
    return true;
  }

  // Normal logic: only FAILED and ERROR block CI
  return (
    status !== InspectionStatus.FAILED && status !== InspectionStatus.ERROR
  );
};

/** Determine status from failed inspections based on block level */
export const getStatusFromFailedInspections = (
  failedInspections: FailedInspection[],
): InspectionStatus => {
  if (failedInspections.length === 0) {
    return InspectionStatus.PASSED;
  }
  const hasBlocker = failedInspections.some(
    (v) => v.blockLevel === InspectionStatus.FAILED,
  );
  return hasBlocker ? InspectionStatus.FAILED : InspectionStatus.WARNING;
};
