// Sled infrastructure constants
export const SLED_REPORTS_BASE_URL = 'https://sled-reports.com';

// Logging prefixes
export const LOG_PREFIX = '[♿️ a11y-audit-plugin]';
export const AXE_LOG_PREFIX = '[AXE_CHECKER]';

// When true: GitHub checks always pass regardless of failed inspections.
// Dashboard still shows TRUE results for internal visibility.
// Set to `false` once team is ready to enforce accessibility compliance.
export const GITHUB_CHECK_ALWAYS_PASS = true;

// When true: Test assertions pass even when failed inspections are found
// (only affects isPassingStatus, not GitHub reporting)
export const TREAT_FAILURES_AS_WARNINGS = true;

// When true: Failed-inspection-state flow is active — failed inspection states are fetched
// from service and filtering is applied in CI, plus benchmark initialization
// and skip/unskip buttons in HTML reports. Set to `true` to enable.
export const ENABLE_FAILED_INSPECTION_STATE_FLOW = false;

// When true: "Fix with AI" buttons appear in HTML reports, allowing users
// to trigger BCA tasks that auto-fix accessibility failed inspections via draft PRs.
export const ENABLE_FIX_WITH_AI = false;

// Default benchmark duration in days for new benchmarks
export const DEFAULT_BENCHMARK_DURATION_DAYS = 90;

// Report file constants
export const DASHBOARD_REPORT_FILENAME = 'ELEVEN-a11y-audit-report.html';

// Sentinel prefix used to encode upload errors in the dashboardUrl field
// when communicating with a11y-ai-audit-tools-service. The service decodes
// this prefix to log the error and create a neutral GitHub Check.
export const UPLOAD_ERROR_PREFIX = 'error://';
