import type { MultiPageReportData } from '../../../types';
import {
  FILTER_TAB_ALL,
  FILTER_TAB_FAILED,
  FILTER_TAB_PASSED,
  FILTER_TAB_PRE_EXISTING,
  FILTER_TAB_PRE_EXISTING_TOOLTIP,
} from '../constants/report-strings';

interface BannerCounts {
  failed: number;
  preExisting: number;
  passed: number;
  total: number;
}

const prStatus = (
  summary: MultiPageReportData['summary'],
  metadata: MultiPageReportData['metadata'],
): string => {
  const newCount =
    metadata.newIssuesCount ?? summary.totalFailedInspections ?? 0;
  const hasBenchmark = !!metadata.benchmarkMetadata;
  const blocked = newCount > 0;

  if (blocked) {
    return `
      <div class="summary-status">
        <span class="summary-badge summary-badge-blocked">PR Blocked</span>
        <div class="summary-text">
          <div class="summary-title">New violations are blocking this PR from merging</div>
          <div class="summary-subtitle">Resolve new violations to unblock your merge${
            hasBenchmark ? ' — pre-existing issues won\u2019t block' : ''
          }</div>
        </div>
      </div>`;
  }

  return `
      <div class="summary-status">
        <span class="summary-badge summary-badge-passing">PR Passing</span>
        <div class="summary-text">
          <div class="summary-title">No new accessibility issues</div>
          <div class="summary-subtitle">${
            hasBenchmark
              ? 'Pre-existing issues were found — they do not block this PR.'
              : 'This PR introduces no new accessibility issues.'
          }</div>
        </div>
      </div>`;
};

export const summaryBannerTemplate = (
  summary: MultiPageReportData['summary'],
  metadata: MultiPageReportData['metadata'],
  counts: BannerCounts,
): string => {
  const hasBenchmark = !!metadata.benchmarkMetadata;
  const preExistingTab = hasBenchmark
    ? `<button class="filter-tab filter-tab--pre-existing" data-filter="pre-existing" type="button" aria-pressed="false" aria-label="${FILTER_TAB_PRE_EXISTING}. ${FILTER_TAB_PRE_EXISTING_TOOLTIP}">
         <span class="count" data-count-pre-existing>${counts.preExisting}</span>
         <span class="label">${FILTER_TAB_PRE_EXISTING}<span class="filter-tab-info" aria-hidden="true" data-tooltip="${FILTER_TAB_PRE_EXISTING_TOOLTIP}"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="16" x2="12" y2="12"></line><line x1="12" y1="8" x2="12.01" y2="8"></line></svg></span></span>
       </button>`
    : '';

  return `
    <div class="summary-banner" id="summaryBanner">
      <div class="summary-top">
        ${prStatus(summary, metadata)}
        <div class="summary-filters" role="group" aria-label="Report filters">
          <button class="filter-tab filter-tab--failed active" data-filter="failed" type="button" aria-pressed="true">
            <span class="count" data-count-failed>${counts.failed}</span>
            <span class="label">${FILTER_TAB_FAILED}</span>
          </button>
          ${preExistingTab}
          <button class="filter-tab filter-tab--passed" data-filter="passed" type="button" aria-pressed="false">
            <span class="count" data-count-passed>${counts.passed}</span>
            <span class="label">${FILTER_TAB_PASSED}</span>
          </button>
          <button class="filter-tab filter-tab--all" data-filter="all" type="button" aria-pressed="false">
            <span class="count" data-count-all>${counts.total}</span>
            <span class="label">${FILTER_TAB_ALL}</span>
          </button>
        </div>
      </div>
    </div>`;
};
