export const FixWithAiHtmlPreview = ({
  data,
}: {
  data: MultiPageReportData;
}) => {
  const html = useMemo(() => {
    const raw = multiPageReportTemplate(data);
    const filled = fillTemplate(raw, {
      scripts: scriptFunctions,
      styles: allReportStyles,
    });
    const modalHtml = fixWithAiModalTemplate();
    const withModal = filled.replace('</body>', modalHtml + '</body>');
    return withModal.replace(
      '</head>',
      FIX_WITH_AI_STORYBOOK_SCRIPTS + '</head>',
    );
  }, [data]);

  return (
    <iframe
      srcDoc={html}
      style={{ border: 'none', height: '100vh', width: '100%' }}
      title="Fix with AI Report Preview"
    />
  );
};

