const failedInspectionCard = (opts: {
  id: string;
  title: string;
  selector: string;
  severity: string;
  htmlSnippet?: string;
  checkItems?: string[];
  checkLabel?: string;
  helpUrl?: string;
  tags?: string[];
  elementCount?: number;
}) => {
  const countBadge = opts.elementCount
    ? `<span class="element-count-badge">${opts.elementCount}</span>`
    : '';

  const htmlDetail = opts.htmlSnippet
    ? `<div class="failed-inspection-detail failed-inspection-detail-html">
          <div class="detail-label">Element HTML</div>
          <pre><code>${opts.htmlSnippet}</code></pre>
        </div>`
    : '';

  const checks =
    opts.checkItems && opts.checkItems.length > 0
      ? `<div class="failed-inspection-check-group">
      <span class="failed-inspection-check-label">${
        opts.checkLabel || 'Fix any of'
      }</span>
      <ul class="failed-inspection-check-list">
        ${opts.checkItems
          .map((item) => `<li class="check-failed">${item}</li>`)
          .join('')}
      </ul>
    </div>`
      : '';

  const helpLink = opts.helpUrl
    ? `<a href="${opts.helpUrl}" target="_blank" rel="noopener noreferrer" class="failed-inspection-help-link">Learn more about this rule \u2192</a>`
    : '';

  const tagsHtml =
    opts.tags && opts.tags.length > 0
      ? `<div class="failed-inspection-tags">${opts.tags
          .map((t) => `<span class="failed-inspection-tag">${t}</span>`)
          .join('')}</div>`
      : '';

  return `
  <div class="element-card failed-inspection-card" data-failed-inspection-id="${
    opts.id
  }">
    <div class="element-header" tabindex="0" role="button" aria-expanded="false" onclick="toggleElement(this)" onkeydown="handleElementKeydown(event, this)">
      <div class="element-header-content">
        <div class="failed-inspection-title">${opts.title}${countBadge}</div>
        <div class="element-selector">${opts.selector}</div>
      </div>
      <div class="element-actions">
        <span class="severity-badge severity-${
          opts.severity
        }">${opts.severity.toUpperCase()}</span>
        <svg class="element-chevron" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/></svg>
      </div>
    </div>
    <div class="element-details">
      ${htmlDetail}
      ${checks}
      ${helpLink}
      ${tagsHtml}
    </div>
  </div>`;
};

