export const buildBenchmarkData = (opts: {
  includeNewIssues: boolean;
}): MultiPageReportData => {
  const base = buildFullDashboardData({
    commitSha: 'f4b802807772d3beae9c8cb66b09642c81a74399',
    prNumber: 8000,
    repository: 'wix-private/accessibility',
  });

  // Extract benchmark (WARNING) audits from FailingTest into a separate section
  const failingTestPage = base.pages.find((p) => p.pageName === 'FailingTest');
  const warningAudits =
    failingTestPage?.audits.filter(
      (a) => a.status === InspectionStatus.WARNING,
    ) ?? [];
  const benchmarkPages =
    failingTestPage && warningAudits.length > 0
      ? [
          {
            ...failingTestPage,
            audits: warningAudits,
            modalId: 'benchmark-modal-0',
            status: InspectionStatus.WARNING,
            totalFailedInspectionsCount: warningAudits.reduce(
              (s, a) => s + a.failedInspectionCount,
              0,
            ),
          },
        ]
      : undefined;

  // In the main pages, replace FailingTest with a version that has benchmark
  // failed inspections removed (they moved to benchmarkPages)
  const pages = base.pages.map((p) =>
    p.pageName === 'FailingTest'
      ? {
          ...p,
          audits: p.audits.filter((a) => a.status !== InspectionStatus.WARNING),
          status: InspectionStatus.PASSED,
          totalFailedInspectionsCount: 0,
        }
      : p,
  );

  // For the "blocked" scenario, add a page with new failed inspections
  if (opts.includeNewIssues) {
    pages.push(newFailingPage);
  }

  // Derive counts from actual data instead of hardcoding
  const benchmarkIssuesCount =
    benchmarkPages?.reduce(
      (sum, p) =>
        sum + p.audits.reduce((s, a) => s + a.failedInspectionCount, 0),
      0,
    ) ?? 0;
  const newIssuesCount = pages
    .filter((p) => p.status === InspectionStatus.FAILED)
    .reduce((sum, p) => sum + p.totalFailedInspectionsCount, 0);

  return {
    benchmarkPages,
    metadata: {
      auditContext: base.metadata.auditContext,
      benchmarkIssuesCount,
      benchmarkMetadata: {
        ...defaultBenchmarkMetadata,
        originalIssueCount: benchmarkIssuesCount,
      },
      newIssuesCount,
      timestamp: new Date().toLocaleString(),
    },
    pages,
    summary: {
      errorPages: pages.filter((p) => p.status === InspectionStatus.ERROR)
        .length,
      failedPages: pages.filter((p) => p.status === InspectionStatus.FAILED)
        .length,
      passedPages: pages.filter((p) => p.status === InspectionStatus.PASSED)
        .length,
      skippedPages: pages.filter((p) => p.status === InspectionStatus.SKIPPED)
        .length,
      totalExecutionTime: pages.reduce(
        (sum, p) => sum + p.totalExecutionTime,
        0,
      ),
      totalFailedInspections: newIssuesCount,
      totalPages: pages.length,
    },
  };
};

