/** DOM card operations: lookup, apply skip/benchmark, remove skip/benchmark. */
export const domScripts = `
        function getRuleId(card, groupItem) {
            return card.getAttribute('data-failed-inspection-id') || groupItem.getAttribute('data-inspection-id') || '';
        }

        function findCardForFailedInspection(ruleId, elementSelector, pageUrl, containerSelector) {
            var items = document.querySelectorAll('.audits-group-item[data-inspection-id][data-page-url]');
            for (var i = 0; i < items.length; i++) {
                var item = items[i];
                if (item.getAttribute('data-page-url') !== pageUrl) continue;
                var csel = item.getAttribute('data-container-selector') || '';
                if (containerSelector != null && csel !== containerSelector) continue;

                var content = item.querySelector('.audits-group-item-content');
                if (!content) continue;

                var cards = content.querySelectorAll('.failed-inspection-card, .failed-inspection-item');
                for (var j = 0; j < cards.length; j++) {
                    var card = cards[j];
                    if (getRuleId(card, item) !== ruleId) continue;
                    var selectorEl = card.querySelector('.element-selector, .affected-element-selector');
                    if (!selectorEl) continue;
                    var sel = (selectorEl.textContent || '').trim();
                    if (sel === elementSelector) return card;
                }
            }
            return null;
        }

        function applySkipToCard(card, skipType, reason) {
            if (card.classList.contains('failed-inspection-skipped')) return;
            card.classList.add('failed-inspection-skipped');

            var actions = card.querySelector('.element-actions');
            if (!actions) {
                var headerEl = card.querySelector('.element-header');
                if (headerEl) {
                    actions = document.createElement('div');
                    actions.className = 'element-actions';
                    headerEl.appendChild(actions);
                }
            }

            if (actions) {
                var badge = document.createElement('span');
                badge.className = 'skipped-badge';
                badge.textContent = 'SKIPPED';
                actions.insertBefore(badge, actions.firstChild);
            }

            if (skipType || reason) {
                if (skipType) {
                    card.setAttribute('data-skip-type', skipType);
                }
                if (reason) {
                    card.setAttribute('data-skip-reason', reason);
                }

                var metaDiv = document.createElement('div');
                metaDiv.className = 'skip-metadata';

                if (skipType) {
                    var typeLabel = document.createElement('div');
                    typeLabel.className = 'skip-type-label';
                    var typeText = (skipType === 'SKIPPED_PR' || skipType === 'PR_SCOPED') ? 'Skipped for this PR' : 'Skipped indefinitely';
                    typeLabel.textContent = typeText;
                    metaDiv.appendChild(typeLabel);
                }

                if (reason) {
                    var reasonEl = document.createElement('div');
                    reasonEl.className = 'skip-reason-text';
                    reasonEl.textContent = reason;
                    metaDiv.appendChild(reasonEl);
                }

                var detailsContainer = card.querySelector('.element-details') || card;
                detailsContainer.appendChild(metaDiv);
            }

            var skipBtn = card.querySelector('.skip-failed-inspection-btn');
            if (skipBtn) skipBtn.remove();

            var groupItem = card.closest('.audits-group-item[data-inspection-id][data-page-url]');
            if (!groupItem) return;
            var ruleId = getRuleId(card, groupItem);
            var pageUrl = groupItem.getAttribute('data-page-url');
            var containerSelector = groupItem.getAttribute('data-container-selector') || '';
            var selectorEl = card.querySelector('.element-selector, .affected-element-selector');
            var elSelector = selectorEl ? (selectorEl.textContent || '').trim() : '';

            var btnContainer = card.querySelector('.element-details') || card;
            if (elSelector) {
                btnContainer.appendChild(createUnskipButton(ruleId, elSelector, pageUrl, containerSelector));
            }

            var originalGroup = card.closest('.failed-inspection-group[data-group-id]');
            if (originalGroup) {
                var groupId = originalGroup.getAttribute('data-group-id');
                if (groupId) {
                    card.setAttribute('data-original-group-id', groupId);
                }
            }

            updateFailedInspectionCounts(-1);
            updateItemFailedInspectionCount(groupItem, -1);
            updateFailedInspectionGroupCount(originalGroup, -1);
            updatePageRowSkippedCount(groupItem, +1);
            if (!card.closest('[id^="benchmark-modal"]')) {
                updateNewIssuesCount(-1);
            }

            var groupContent = groupItem.querySelector('.audits-group-item-content');
            if (!groupContent) return;
            var skippedContainer = getOrCreateSkippedContainer(groupContent);
            var list = skippedContainer.querySelector('.skipped-failed-inspections-list');
            if (list) list.appendChild(card);
            updateSkippedCount(skippedContainer);
        }

        function applyBenchmarkToCard(card) {
            if (card.classList.contains('failed-inspection-benchmarked')) return;

            // Cards inside the benchmark section are already pre-categorised --
            // don't rearrange them or touch counts.
            if (card.closest('[id^="benchmark-modal"]')) return;

            card.classList.add('failed-inspection-benchmarked');

            var actions = card.querySelector('.element-actions');
            if (!actions) {
                var headerEl = card.querySelector('.element-header');
                if (headerEl) {
                    actions = document.createElement('div');
                    actions.className = 'element-actions';
                    headerEl.appendChild(actions);
                }
            }

            if (actions) {
                var badge = document.createElement('span');
                badge.className = 'benchmark-badge';
                badge.textContent = 'Non-blocking';
                actions.insertBefore(badge, actions.firstChild);
            }

            var skipBtn = card.querySelector('.skip-failed-inspection-btn');
            if (skipBtn) skipBtn.remove();

            var groupItem = card.closest('.audits-group-item[data-inspection-id][data-page-url]');
            if (!groupItem) return;
            var ruleId = getRuleId(card, groupItem);
            var pageUrl = groupItem.getAttribute('data-page-url');
            var containerSelector = groupItem.getAttribute('data-container-selector') || '';
            var selectorEl = card.querySelector('.element-selector, .affected-element-selector');
            var elSelector = selectorEl ? (selectorEl.textContent || '').trim() : '';

            var btnContainer = card.querySelector('.element-details') || card;
            if (elSelector) {
                btnContainer.appendChild(createSkipButton(ruleId, elSelector, pageUrl, containerSelector));
            }

            var originalGroup = card.closest('.failed-inspection-group[data-group-id]');
            if (originalGroup) {
                var groupId = originalGroup.getAttribute('data-group-id');
                if (groupId) {
                    card.setAttribute('data-original-group-id', groupId);
                }
            }

            updateFailedInspectionCounts(-1);
            updateItemFailedInspectionCount(groupItem, -1);
            updateFailedInspectionGroupCount(originalGroup, -1);

            var groupContent = groupItem.querySelector('.audits-group-item-content');
            if (!groupContent) return;
            var benchmarkedContainer = getOrCreateBenchmarkedContainer(groupContent);
            var list = benchmarkedContainer.querySelector('.benchmarked-failed-inspections-list');
            if (list) list.appendChild(card);
            updateBenchmarkedCount(benchmarkedContainer);
        }

        function removeBenchmarkFromCard(card) {
            card.classList.remove('failed-inspection-benchmarked');

            var badge = card.querySelector('.benchmark-badge');
            if (badge) badge.remove();

            var groupItem = card.closest('.audits-group-item[data-inspection-id][data-page-url]');
            if (!groupItem) return;

            var originalGroupId = card.getAttribute('data-original-group-id');

            updateFailedInspectionCounts(+1);
            updateItemFailedInspectionCount(groupItem, +1);

            var groupContent = groupItem.querySelector('.audits-group-item-content');
            if (!groupContent) return;

            if (originalGroupId) {
                var targetGroup = groupContent.querySelector('.failed-inspection-group[data-group-id="' + originalGroupId + '"]');
                if (targetGroup) {
                    updateFailedInspectionGroupCount(targetGroup, +1);
                }
            }

            var benchmarkedContainer = groupContent.querySelector('.benchmarked-failed-inspections-container');

            function resolveTargetContainer() {
                if (originalGroupId) {
                    var selector = '.failed-inspection-group[data-group-id="' + originalGroupId + '"] > .failed-inspection-group-items';
                    var originalGroupItems = groupContent.querySelector(selector);
                    if (originalGroupItems && !originalGroupItems.closest('.benchmarked-failed-inspections-container')) {
                        return originalGroupItems;
                    }
                }
                var containers = groupContent.querySelectorAll('.failed-inspection-group-items');
                for (var i = 0; i < containers.length; i++) {
                    if (!containers[i].closest('.benchmarked-failed-inspections-container') &&
                        !containers[i].closest('.skipped-failed-inspections-container')) {
                        return containers[i];
                    }
                }
                return null;
            }

            var targetContainer = resolveTargetContainer();

            if (originalGroupId) {
                card.removeAttribute('data-original-group-id');
            }

            if (targetContainer) {
                targetContainer.appendChild(card);
            } else if (benchmarkedContainer) {
                groupContent.insertBefore(card, benchmarkedContainer);
            }

            if (benchmarkedContainer) {
                updateBenchmarkedCount(benchmarkedContainer);
            }

            var ruleId = getRuleId(card, groupItem);
            var pageUrl = groupItem.getAttribute('data-page-url');
            var containerSelector = groupItem.getAttribute('data-container-selector') || '';
            var selectorEl = card.querySelector('.element-selector, .affected-element-selector');
            var elSelector = selectorEl ? (selectorEl.textContent || '').trim() : '';

            var btnContainer = card.querySelector('.element-details') || card;
            if (elSelector && !card.querySelector('.skip-failed-inspection-btn')) {
                btnContainer.appendChild(createSkipButton(ruleId, elSelector, pageUrl, containerSelector));
            }
        }

        function removeSkipFromCard(card) {
            card.classList.remove('failed-inspection-skipped');

            var badge = card.querySelector('.skipped-badge');
            if (badge) badge.remove();

            var skipMeta = card.querySelector('.skip-metadata');
            if (skipMeta) {
                skipMeta.remove();
            }
            card.removeAttribute('data-skip-type');
            card.removeAttribute('data-skip-reason');

            var unskipBtn = card.querySelector('.unskip-failed-inspection-btn');
            if (unskipBtn) unskipBtn.remove();

            var groupItem = card.closest('.audits-group-item[data-inspection-id][data-page-url]');
            if (!groupItem) return;
            var ruleId = getRuleId(card, groupItem);
            var pageUrl = groupItem.getAttribute('data-page-url');
            var containerSelector = groupItem.getAttribute('data-container-selector') || '';
            var selectorEl = card.querySelector('.element-selector, .affected-element-selector');
            var elSelector = selectorEl ? (selectorEl.textContent || '').trim() : '';

            var originalGroupId = card.getAttribute('data-original-group-id');

            updateFailedInspectionCounts(+1);
            updateItemFailedInspectionCount(groupItem, +1);
            updatePageRowSkippedCount(groupItem, -1);
            if (!card.closest('[id^="benchmark-modal"]')) {
                updateNewIssuesCount(+1);
            }

            var groupContent = groupItem.querySelector('.audits-group-item-content');
            if (!groupContent) return;

            if (originalGroupId) {
                var targetGroup = groupContent.querySelector('.failed-inspection-group[data-group-id="' + originalGroupId + '"]');
                if (targetGroup) {
                    updateFailedInspectionGroupCount(targetGroup, +1);
                }
            }

            var skippedContainer = groupContent.querySelector('.skipped-failed-inspections-container');

            function resolveTargetContainer() {
                if (originalGroupId) {
                    var selector = '.failed-inspection-group[data-group-id="' + originalGroupId + '"] > .failed-inspection-group-items';
                    var originalGroupItems = groupContent.querySelector(selector);
                    if (originalGroupItems && !originalGroupItems.closest('.skipped-failed-inspections-container')) {
                        return originalGroupItems;
                    }
                }
                var containers = groupContent.querySelectorAll('.failed-inspection-group-items');
                for (var i = 0; i < containers.length; i++) {
                    if (!containers[i].closest('.skipped-failed-inspections-container') &&
                        !containers[i].closest('.benchmarked-failed-inspections-container')) {
                        return containers[i];
                    }
                }
                return null;
            }

            var targetContainer = resolveTargetContainer();

            if (originalGroupId) {
                card.removeAttribute('data-original-group-id');
            }

            if (targetContainer) {
                targetContainer.appendChild(card);
            } else if (skippedContainer) {
                groupContent.insertBefore(card, skippedContainer);
            }

            if (skippedContainer) {
                updateSkippedCount(skippedContainer);
            }

            var btnContainer = card.querySelector('.element-details') || card;
            if (elSelector) {
                btnContainer.appendChild(createSkipButton(ruleId, elSelector, pageUrl, containerSelector));
            }
        }

        function removeSkipLoading() {
            document.body.removeAttribute('data-skip-loading');
        }
`;
