/**
 * Read the @wix/web-bi-logger UMD bundle so it can be inlined as a <script>
 * block inside generated HTML reports.
 *
 * This module is only ever called at runtime from Node.js (report generation).
 * Storybook's webpack may still traverse the import graph and reach this file,
 * so we use `__non_webpack_require__` to prevent webpack from trying to bundle
 * the Node-only `fs` / `path` modules.
 */

/* eslint-disable no-var */
declare var __non_webpack_require__: NodeRequire | undefined;
/* eslint-enable no-var */

const WEB_BI_LOGGER_UNAVAILABLE = '/* web-bi-logger bundle not available */';

/**
 * Returns a require function that webpack will not attempt to statically
 * resolve. In a webpack build, `__non_webpack_require__` is a built-in global
 * that maps to Node's native require. Outside webpack, regular `require` is
 * used directly via the global `module` object.
 */
function getNodeRequire(): NodeRequire {
  // __non_webpack_require__ is injected by webpack and bypasses module bundling
  if (typeof __non_webpack_require__ !== 'undefined') {
    return __non_webpack_require__;
  }

  // `module.require` is not always available in compiled/ESM-ish runtimes.
  try {
    return Function('return require')() as NodeRequire;
  } catch {
    const nodeModule = Function(
      'return require("module")',
    )() as typeof import('module');
    return nodeModule.createRequire(process.cwd());
  }
}

function resolveWebBiLoggerBundlePath(
  fs: typeof import('fs'),
  path: typeof import('path'),
  nodeRequire: NodeRequire,
): string {
  const candidates: string[] = [];

  try {
    candidates.push(
      path.resolve(
        path.dirname(nodeRequire.resolve('@wix/web-bi-logger/package.json')),
        'dist',
        'statics',
        'app.bundle.min.js',
      ),
    );
  } catch {
    // Fall through to filesystem-based candidates below.
  }

  candidates.push(
    path.resolve(
      process.cwd(),
      'node_modules',
      '@wix',
      'web-bi-logger',
      'dist',
      'statics',
      'app.bundle.min.js',
    ),
  );

  if (typeof __dirname !== 'undefined') {
    candidates.push(
      path.resolve(
        __dirname,
        '..',
        '..',
        '..',
        '..',
        '..',
        '..',
        'node_modules',
        '@wix',
        'web-bi-logger',
        'dist',
        'statics',
        'app.bundle.min.js',
      ),
    );
  }

  const existingCandidate = candidates.find((candidate) =>
    fs.existsSync(candidate),
  );

  if (!existingCandidate) {
    throw new Error('Could not resolve @wix/web-bi-logger UMD bundle');
  }

  return existingCandidate;
}

let _cached: string | undefined;

export function getWebBiLoggerBundle(): string {
  if (_cached && _cached !== WEB_BI_LOGGER_UNAVAILABLE) {
    return _cached;
  }

  try {
    const nodeRequire = getNodeRequire();
    const fs: typeof import('fs') = nodeRequire('fs');
    const path: typeof import('path') = nodeRequire('path');
    const bundlePath = resolveWebBiLoggerBundlePath(fs, path, nodeRequire);

    _cached = fs.readFileSync(bundlePath, 'utf-8');
  } catch {
    // BI is non-blocking — if the bundle can't be loaded (e.g. in test
    // environments), the report still works, just without analytics.
    _cached = WEB_BI_LOGGER_UNAVAILABLE;
  }

  return _cached!;
}
