export const scriptFunctions = `
        function toggleElement(header) {
            const details = header.nextElementSibling;
            const isActive = header.classList.contains('active');

            if (isActive) {
                header.classList.remove('active');
                details.classList.remove('active');
                header.setAttribute('aria-expanded', 'false');
            } else {
                header.classList.add('active');
                details.classList.add('active');
                header.setAttribute('aria-expanded', 'true');
            }

            // BI: element expand/collapse
            try {
                if (typeof biElementExpandCollapse === 'function') {
                    var auditName = _biGetAuditNameFromElement(header);
                    var inspectionType = _biGetInspectionTypeFromElement(header);
                    var groupCtx = _biGetFailedInspectionGroupContext(header);
                    var elHeader = header.querySelector('.element-header-content');
                    var elementType = elHeader ? elHeader.textContent.trim().substring(0, 50) : '';
                    var card = header.closest('[data-failed-inspection-id]');
                    var elementId = card ? card.getAttribute('data-failed-inspection-id') : '';
                    biElementExpandCollapse(
                        isActive ? 'collapse' : 'expand',
                        auditName, groupCtx.ruleType || '', groupCtx.severity || '',
                        inspectionType, '', elementType, elementId || ''
                    );
                }
            } catch(e) {}
        }

        function toggleAffectedElement(header) {
            const details = header.nextElementSibling;
            const isActive = header.classList.contains('active');

            if (isActive) {
                header.classList.remove('active');
                details.classList.remove('active');
                header.setAttribute('aria-expanded', 'false');
            } else {
                header.classList.add('active');
                details.classList.add('active');
                header.setAttribute('aria-expanded', 'true');
            }

            // BI: element expand/collapse
            try {
                if (typeof biElementExpandCollapse === 'function') {
                    var auditName = _biGetAuditNameFromElement(header);
                    var inspectionType = _biGetInspectionTypeFromElement(header);
                    var groupCtx = _biGetFailedInspectionGroupContext(header);
                    var elHeader = header.querySelector('.element-header-content');
                    var elementType = elHeader ? elHeader.textContent.trim().substring(0, 50) : '';
                    var card = header.closest('[data-failed-inspection-id]');
                    var elementId = card ? card.getAttribute('data-failed-inspection-id') : '';
                    biElementExpandCollapse(
                        isActive ? 'collapse' : 'expand',
                        auditName, groupCtx.ruleType || '', groupCtx.severity || '',
                        inspectionType, '', elementType, elementId || ''
                    );
                }
            } catch(e) {}
        }

        function handleElementKeydown(event, header) {
            if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                if (header.classList.contains('affected-element-header')) {
                    toggleAffectedElement(header);
                } else {
                    toggleElement(header);
                }
            }
        }

        function toggleFailedInspectionGroup(titleElement) {
            const group = titleElement.closest('.failed-inspection-group-collapsible');
            if (!group) return;

            const items = group.querySelector('.failed-inspection-group-items');
            if (!items) return;

            const isCollapsed = items.classList.contains('collapsed');

            if (isCollapsed) {
                items.classList.remove('collapsed');
                group.classList.add('expanded');
            } else {
                items.classList.add('collapsed');
                group.classList.remove('expanded');
            }

            // BI: rule expand/collapse
            try {
                if (typeof biRuleExpandCollapse === 'function') {
                    var auditName = _biGetAuditNameFromElement(titleElement);
                    var inspectionType = _biGetInspectionTypeFromElement(titleElement);
                    var groupCtx = _biGetFailedInspectionGroupContext(titleElement);
                    biRuleExpandCollapse(
                        isCollapsed ? 'expand' : 'collapse',
                        auditName,
                        groupCtx.ruleType || '',
                        groupCtx.severity || '',
                        inspectionType,
                        '',
                        groupCtx.elementsCount || 0,
                        groupCtx.passedElementsCount || 0,
                        groupCtx.failedElementsCount || 0
                    );
                }
            } catch(e) {}
        }

        function showCopyToast(message) {
            var existing = document.querySelector('.copy-toast');
            if (existing) existing.remove();
            var toast = document.createElement('div');
            toast.className = 'copy-toast';
            toast.textContent = message || 'Selector copied to clipboard';
            document.body.appendChild(toast);
            requestAnimationFrame(function() {
                toast.classList.add('visible');
            });
            setTimeout(function() {
                toast.classList.remove('visible');
                setTimeout(function() { toast.remove(); }, 300);
            }, 2000);
        }

        function copySelectorToClipboard(button) {
            var selector = button.getAttribute('data-selector');
            function onCopied() {
                showCopyToast('Selector copied to clipboard');
            }
            function fallbackCopy() {
                var textarea = document.createElement('textarea');
                textarea.value = selector;
                textarea.style.position = 'fixed';
                textarea.style.opacity = '0';
                document.body.appendChild(textarea);
                textarea.select();
                document.execCommand('copy');
                document.body.removeChild(textarea);
                onCopied();
            }
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(selector).then(onCopied).catch(fallbackCopy);
            } else {
                fallbackCopy();
            }
        }

        document.addEventListener('DOMContentLoaded', function() {
            const rows = document.querySelectorAll('.inspection-row[data-href]');
            rows.forEach(row => {
                row.addEventListener('click', function() {
                    const href = this.getAttribute('data-href');
                    if (href) {
                        window.location.href = href;
                    }
                });
            });
        });
`;
