import type { OneOfAuditId, OneOfInspectionId } from '../registry';

/**
 * Configuration interface for individual a11y test config files (*.a11y.ts).
 * Users export this from their config files to define test parameters.
 */
export interface A11yTestConfig {
  /** URL to navigate to for the test */
  url: string;
  /** Optional user email in case the URL requires authentication */
  user?: string;
  /** CSS selector for the container element to test */
  containerSelector: string;
}

/**
 * Configuration for automatic artifact override URL construction.
 * When provided, the plugin will automatically detect the buildId and construct
 * the override URL for sled testing.
 *
 * Example constructed URLs:
 * - Local: `https://sled.wix.dev/editor-elements-library/local-darwin-IL-M426RJK390-of-yohais~wixui`
 * - Remote: `https://sled.wix.dev/editor-elements-library/editor-elements-library-3a3aa~wixui`
 * - Falcon CI: `https://sled.wix.dev/editor-elements-library/fd5ddb4abf79c58b026b45ba48b29f2d~wixui`
 */
export interface ArtifactOverrideConfig {
  /** The sled artifact ID (e.g., 'editor-elements-library') */
  artifactId: string;
  /** The CI package name for fingerprint lookup (e.g., '@wix/editor-elements-virtual-deployable') */
  ciPackageName: string;
  /** Optional namespace suffix for the URL (e.g., 'wixui'). Defaults to undefined (no namespace) */
  namespace?: string;
  /** Optional custom environment variable name for direct override URL */
  overrideUrlEnvVar?: string;
}

/**
 * Plugin parameters passed to createA11yAuditPlugin in playwright.config.ts.
 */
export interface A11yAuditPluginParams {
  /** Paths to package test directories to scan for *.a11y.ts config files.
   *  Each entry is a path relative to the monorepo root pointing to where a package's
   *  a11y test configs live (e.g., 'packages/my-component/sled/e2e').
   *  The package name is derived from the path segment after 'packages/'
   *  (e.g., 'packages/my-component/sled/e2e' → 'my-component').
   *  In the dashboard, results are grouped by package name.
   *
   *  @example
   *  // Single package
   *  packageTestsPaths: ['packages/package1/sled/e2e']
   *
   *  // Multiple packages in a monorepo (playwright.config.ts at repo root)
   *  packageTestsPaths: [
   *    'packages/package1/sled/e2e',
   *    'packages/package2/sled/e2e',
   *  ]
   */
  packageTestsPaths?: string[];
  // TODO: Remove `testsPath` param and its backward-compat handling once all consumers have migrated to `packageTestsPaths`.
  /** @deprecated Use `packageTestsPaths` instead. Internally converted to a single-entry `packageTestsPaths` array. */
  testsPath?: string;
  /** Optional path for generated test files (defaults to '.cli-generated/a11y-tests') */
  generatedTestsPath?: string;
  /** Optional list of inspection IDs to run */
  enabledInspections?: OneOfInspectionId[];
  /** Optional waitUntil option for page.goto() */
  waitUntil?: 'load' | 'domcontentloaded' | 'networkidle' | 'commit';
  /** Optional artifact override configuration for automatic override URL construction. */
  artifactOverride?: ArtifactOverrideConfig;
}

export const DEFAULT_AUDIT_ID: OneOfAuditId = 'core-audits';

/** Title displayed in report headers */
export const REPORT_TITLE = 'Ensuring your components are accessible';

export const DEFAULT_INSPECTION_IDS: OneOfInspectionId[] = [
  'axe',
  'button-operability',
  'checkbox-operability',
  'link-operability',
  'radio-operability',
  'dropdown-operability',
  'modal-operability',
];

export const DEFAULT_A11Y_AUDIT_PLUGIN_PARAMS: Partial<A11yAuditPluginParams> =
  {
    enabledInspections: DEFAULT_INSPECTION_IDS,
  };
