import { escapeHtml } from '../../../components';
import {
  SIDEBAR_ARIA_LABEL,
  SIDEBAR_TITLE_PREFIX,
} from '../constants/report-strings';
import type {
  ComponentNode,
  PackageNode,
} from '../utils/aggregate-rule-groups';

const renderComponentItem = (comp: ComponentNode): string => {
  const isFailed = comp.status === 'failed';
  const isPreExisting = comp.status === 'pre-existing';
  const isPassed = comp.status === 'passed';
  const iconClass = isFailed
    ? 'failed'
    : isPreExisting
    ? 'pre-existing-icon'
    : 'passed-icon';

  const hasNew = isFailed ? '1' : '0';
  const hasPreExisting = isPreExisting ? '1' : '0';

  return `
        <div class="comp-tree-item${isPassed ? ' passed-comp' : ''}"
             role="button"
             tabindex="0"
             data-pkg="${escapeHtml(comp.packageName)}"
             data-component="${escapeHtml(comp.pageName)}"
             data-status="${comp.status}"
             data-has-new="${hasNew}"
             data-has-pre-existing="${hasPreExisting}"
             aria-label="Drill into ${escapeHtml(comp.pageName)}">
          <span class="comp-tree-icon ${iconClass}" aria-hidden="true">&#9679;</span>
          <div class="comp-tree-info">
            <div class="comp-tree-name" title="${escapeHtml(
              comp.pageName,
            )}">${escapeHtml(comp.pageName)}</div>
          </div>
        </div>`;
};

const pkgBadge = (pkg: PackageNode): { className: string; text: string } => {
  if (pkg.failedComponentCount > 0) {
    return { className: 'has-new', text: String(pkg.failedComponentCount) };
  }
  if (pkg.preExistingComponentCount > 0) {
    return {
      className: 'pre-existing-only',
      text: String(pkg.preExistingComponentCount),
    };
  }
  return {
    className: 'passed-only',
    text: String(pkg.passedComponentCount),
  };
};

const renderPackageNode = (pkg: PackageNode): string => {
  const { className: badgeClass, text: badgeText } = pkgBadge(pkg);
  const children = pkg.components.map(renderComponentItem).join('');
  const pkgEsc = escapeHtml(pkg.packageName);

  return `
    <div class="pkg-tree-node"
         data-pkg="${pkgEsc}"
         data-failed="${pkg.failedComponentCount}"
         data-pre-existing="${pkg.preExistingComponentCount}"
         data-passed="${pkg.passedComponentCount}">
      <div class="pkg-tree-header"
           role="button"
           tabindex="0"
           aria-expanded="false"
           onkeydown="handlePkgNodeKey(event, this)">
        <span class="pkg-tree-chevron"
              role="button"
              tabindex="0"
              aria-label="Toggle ${pkgEsc} contents"
              onclick="togglePkgNode(event, this)"
              onkeydown="handlePkgChevronKey(event, this)">&#9654;</span>
        <span class="pkg-tree-icon" aria-hidden="true"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M16.5 9.4 7.55 4.24"></path><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path><polyline points="3.27 6.96 12 12.01 20.73 6.96"></polyline><line x1="12" y1="22.08" x2="12" y2="12"></line></svg></span>
        <span class="pkg-tree-name">${pkgEsc}</span>
        <span class="pkg-tree-badge ${badgeClass}">${badgeText}</span>
      </div>
      <div class="pkg-tree-children">
        ${children}
      </div>
    </div>`;
};

export const sidebarTemplate = (packages: PackageNode[]): string => {
  const totalComponents = packages.reduce(
    (sum, p) => sum + p.components.length,
    0,
  );
  const totalPackages = packages.length;

  const nodes = packages.map(renderPackageNode).join('');

  return `
    <aside class="sidebar" aria-label="${SIDEBAR_ARIA_LABEL}">
      <div class="sidebar-title" id="sidebarTitle">${SIDEBAR_TITLE_PREFIX} (${totalComponents}) Packages (${totalPackages})</div>
      <div class="rule-groups" role="tree">
        ${nodes || '<div class="sidebar-empty">No packages</div>'}
      </div>
    </aside>`;
};
