import { escapeHtml } from '../../../components';
import type {
  ComponentNode,
  PackageNode,
  PassedComponent,
  RuleGroup,
  RuleGroupInstance,
} from '../utils/aggregate-rule-groups';

const renderInstance = (
  rg: RuleGroup,
  inst: RuleGroupInstance,
  idx: number,
): string => {
  const selectorEsc = escapeHtml(inst.selector);
  const copyIcon = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>`;
  const htmlBlock = inst.elementHtml
    ? `<div class="info-column">
         <div class="info-column-title">HTML element</div>
         <div class="info-html-wrap">
           <pre class="info-html-block">${escapeHtml(inst.elementHtml)}</pre>
           <button class="btn-copy-html"
                   type="button"
                   title="Copy HTML"
                   aria-label="Copy HTML"
                   data-copy="${escapeHtml(inst.elementHtml)}"
                   onclick="copyInstanceSelector(this)">${copyIcon}</button>
         </div>
       </div>`
    : '';
  const expandIcon = `<svg class="expand-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="15 3 21 3 21 9"/><polyline points="9 21 3 21 3 15"/><line x1="21" y1="3" x2="14" y2="10"/><line x1="3" y1="21" x2="10" y2="14"/></svg>`;
  const imageFor = (url: string | undefined, label: string): string =>
    url
      ? `<div class="image-container">
           <div class="image-label">${label}</div>
           <img class="comparison-image"
                src="${escapeHtml(url)}"
                alt="${label} screenshot"
                loading="lazy"
                role="button"
                tabindex="0"
                title="Click to expand"
                onclick="handleScreenshotClick(event, this)"
                onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();handleScreenshotClick(event, this);}" />
           <button class="screenshot-expand-btn"
                   type="button"
                   aria-label="Expand ${label} screenshot"
                   title="Expand"
                   data-screenshot-src="${escapeHtml(url)}"
                   data-screenshot-alt="${label} screenshot"
                   onclick="handleScreenshotClick(event, this)">${expandIcon}</button>
         </div>`
      : '';
  const screenshotBody =
    inst.images && (inst.images.before || inst.images.after)
      ? `<div class="image-comparison">
           ${imageFor(inst.images.before, 'Before')}
           ${imageFor(inst.images.after, 'After')}
         </div>`
      : `<div class="info-screenshot"
              role="button"
              tabindex="0"
              aria-label="Expand element screenshot"
              title="Expand"
              onclick="handleScreenshotClick(event, this)"
              onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();handleScreenshotClick(event, this);}">
           <span class="info-screenshot-empty">No screenshot available</span>
           <span class="screenshot-expand-btn" aria-hidden="true">${expandIcon}</span>
         </div>`;
  const imagesBlock = `<div class="info-column">
         <div class="info-column-title">Screenshot</div>
         ${screenshotBody}
       </div>`;

  const ruleIdEsc = escapeHtml(rg.id);
  const pageUrlEsc = escapeHtml(inst.pageUrl);
  const containerEsc = escapeHtml(inst.containerSelector);

  return `
    <div class="fi-instance"
         data-key="${escapeHtml(inst.key)}"
         data-package="${escapeHtml(inst.packageName)}"
         data-rule-id="${ruleIdEsc}"
         data-page-url="${pageUrlEsc}"
         data-container-selector="${containerEsc}"
         data-element-selector="${selectorEsc}">
      <div class="instance-row-1">
        <span class="instance-num">${idx + 1}</span>
        <div class="instance-code-chip">
          <code class="instance-code">${selectorEsc}</code>
          <button class="btn-copy-selector"
                  type="button"
                  title="Copy selector"
                  aria-label="Copy selector"
                  data-copy="${selectorEsc}"
                  onclick="copyInstanceSelector(this)">${copyIcon}</button>
        </div>
      </div>
      <div class="instance-row-2">
        <button class="instance-more-info-toggle"
                type="button"
                aria-expanded="false"
                onclick="toggleInstanceMoreInfo(this)">
          <span class="toggle-chevron">&#9654;</span> More info
        </button>
        <div class="instance-actions">
          <button class="btn-instance-fix"
                  type="button"
                  data-action="fix-with-ai"
                  onclick="handleInstanceAction(event, this, 'fix')">FIX WITH AI</button>
          <button class="btn-instance-skip"
                  type="button"
                  data-action="skip"
                  onclick="handleInstanceAction(event, this, 'skip')">IGNORE</button>
        </div>
      </div>
      <div class="instance-more-info">
        <div class="instance-more-info-body">
          ${imagesBlock}
          ${htmlBlock}
        </div>
      </div>
    </div>`;
};

export const failedInspectionCardTemplate = (
  rg: RuleGroup,
  instances: RuleGroupInstance[] = rg.instances,
  context?: { packageName: string; componentName: string },
): string => {
  const instanceCount = instances.length;
  const newCount = instances.filter((i) => i.status === 'new').length;
  const preExistingCount = instanceCount - newCount;
  const sev = rg.highestSeverity;

  const statusTag = '';

  const instancesHtml = instances
    .map((inst, idx) => renderInstance(rg, inst, idx))
    .join('');

  const uniqueFailureSummaries = Array.from(
    new Set(
      instances
        .map((i) => (i.failureSummary || '').trim())
        .filter((s) => s.length > 0),
    ),
  );
  const failureSummaryLines = uniqueFailureSummaries
    .flatMap((s) => s.split('\n').map((line) => line.trim()))
    .filter(
      (line) =>
        line.length > 0 && !/^fix any of( the following)?:?$/i.test(line),
    );
  const fixItems = [...failureSummaryLines, ...rg.fixOptions];
  const formatFixItem = (opt: string): string => {
    const escaped = escapeHtml(opt);
    return escaped
      .replace(/(&lt;\/?[a-zA-Z][a-zA-Z0-9-]*&gt;)/g, '<code>$1</code>')
      .replace(/([a-zA-Z-]+=&quot;[^&]*?&quot;)/g, '<code>$1</code>')
      .replace(/\b((?:aria|data)-[a-zA-Z-]+)\b/g, '<code>$1</code>')
      .replace(/`([^`]+)`/g, '<code>$1</code>');
  };
  const fixOptionsHtml =
    fixItems.length > 0
      ? `<div class="card-fix-options">
           <div class="card-fix-options-heading">How to fix:</div>
           <ul>${fixItems
             .map((opt) => `<li>${formatFixItem(opt)}</li>`)
             .join('')}</ul>
         </div>`
      : '';

  const wcagLink = '';

  const learnMore = rg.helpUrl
    ? `<a class="card-learn-more"
          href="${escapeHtml(rg.helpUrl)}"
          target="_blank"
          rel="noopener noreferrer">Learn about this rule &#8599;</a>`
    : '';

  const packagesAttr = context
    ? context.packageName
    : rg.packages.map((p) => p).join('|');
  const instancesCountLabel = `${instanceCount} element${
    instanceCount !== 1 ? 's' : ''
  } to fix`;
  const contextAttrs = context
    ? ` data-pkg="${escapeHtml(
        context.packageName,
      )}" data-component="${escapeHtml(context.componentName)}"`
    : '';

  return `
    <div class="fi-card v-collapsed"
         data-rg="${escapeHtml(rg.id)}"
         data-severity="${sev}"
         data-has-new="${newCount > 0 ? '1' : '0'}"
         data-has-pre-existing="${preExistingCount > 0 ? '1' : '0'}"
         data-packages="${escapeHtml(packagesAttr)}"${contextAttrs}
         aria-expanded="false">
      <div class="card-top-row" role="button" tabindex="0" onclick="toggleFailedInspectionCard(event, this)" onkeydown="handleFailedInspectionCardKey(event, this)">
        <div class="card-top-left">
          <span class="severity-badge ${sev}">
            ${sev.toUpperCase()}
          </span>
          <span class="instances-count">${instancesCountLabel}</span>
          ${statusTag}
          ${wcagLink}
        </div>
        <span class="card-chevron" aria-hidden="true">&#9662;</span>
      </div>
      <div class="card-rule-name">${escapeHtml(rg.description)}</div>
      ${fixOptionsHtml}
      <div class="fi-instances">${instancesHtml}</div>
      <div class="card-footer">
        ${learnMore}
      </div>
    </div>`;
};

export const passedCardTemplate = (pc: PassedComponent): string => `
    <div class="passed-card"
         role="button"
         tabindex="0"
         aria-label="Show ${escapeHtml(pc.pageName)} in ${escapeHtml(
  pc.packageName,
)}"
         data-pc-name="${escapeHtml(pc.pageName)}"
         data-package="${escapeHtml(pc.packageName)}">
      <span class="passed-icon" aria-hidden="true">&#10003;</span>
      <div class="passed-info">
        <div class="passed-name">${escapeHtml(pc.pageName)}</div>
      </div>
      <span class="passed-pkg">${escapeHtml(pc.packageName)}</span>
    </div>`;

export const celebrationTemplate = (): string => `
    <div class="celebration" id="celebration">
      <div class="celebration-icon" aria-hidden="true">&#127881;</div>
      <h2>All New Failed Inspections Resolved!</h2>
      <p>Every new accessibility failed inspection has been addressed. Great work!</p>
    </div>`;

const componentSectionTemplate = (
  pkgName: string,
  comp: ComponentNode,
): string => {
  if (comp.rules.length === 0) {
    return '';
  }
  const cards = comp.rules
    .map((r) =>
      failedInspectionCardTemplate(r.group, r.instances, {
        componentName: comp.pageName,
        packageName: pkgName,
      }),
    )
    .join('');
  const urlLink = comp.pageUrl
    ? `<a class="fi-component-url"
          href="${escapeHtml(comp.pageUrl)}"
          target="_blank"
          rel="noopener noreferrer"
          title="${escapeHtml(
            comp.pageUrl,
          )}">Test url<span class="fi-component-url-icon" aria-hidden="true">&#8599;</span></a>`
    : '';

  return `
      <section class="fi-component-section"
               data-pkg="${escapeHtml(pkgName)}"
               data-component="${escapeHtml(comp.pageName)}">
        <header class="fi-component-header">
          <span class="fi-component-name">${escapeHtml(comp.pageName)}</span>
          ${urlLink}
        </header>
        <div class="fi-component-rules">
          ${cards}
        </div>
      </section>`;
};

const packageSectionTemplate = (pkg: PackageNode): string => {
  const failedComps = pkg.components.filter((c) => c.status !== 'passed');
  if (failedComps.length === 0) {
    return '';
  }
  const sections = failedComps
    .map((c) => componentSectionTemplate(pkg.packageName, c))
    .filter(Boolean)
    .join('');
  if (!sections) {
    return '';
  }
  return `
    <div class="fi-package-section" data-pkg="${escapeHtml(pkg.packageName)}">
      ${sections}
    </div>`;
};

export const failedInspectionsListTemplate = (
  packages: PackageNode[],
  passed: PassedComponent[],
): string => {
  const sections = packages
    .map(packageSectionTemplate)
    .filter(Boolean)
    .join('');
  const passedCards = passed.map(passedCardTemplate).join('');
  return `
    <div id="failedInspectionsList" class="fi-list" aria-live="polite">
      ${sections}
    </div>
    <div id="passedList" class="passed-list is-hidden">
      ${passedCards}
    </div>
    ${celebrationTemplate()}`;
};
