import React from 'react';

import {
  ALL_SKIPPED_STORYBOOK_SCRIPTS,
  buildAllAxeIssuesData,
  buildFailedAuditWithSkipData,
  buildMultiPackageData,
  FAILED_INSPECTION_STATE_STORYBOOK_SCRIPTS,
  FailedInspectionStateHtmlPreview,
  HtmlReportPreview,
  THREE_SKIPPED_STORYBOOK_SCRIPTS,
} from './helpers';

export default {
  title: 'Audit Report / Functionality',
};

export const AllAxeIssues = () => {
  const data = buildAllAxeIssuesData();
  return <HtmlReportPreview data={data} />;
};
AllAxeIssues.storyName = 'All AXE Issues (Categorization Catalog)';

export const MultiPackageFailedInspections = () => {
  const data = buildMultiPackageData();
  // Use FailedInspectionStateHtmlPreview so that the failed-inspection-state
  // scripts (openSkipModal / openFixAiModal / etc.) and their mock fetch
  // interceptors are injected — otherwise the IGNORE / FIX WITH AI buttons
  // have no handler to call.
  return (
    <FailedInspectionStateHtmlPreview
      data={data}
      mockScripts={FAILED_INSPECTION_STATE_STORYBOOK_SCRIPTS}
    />
  );
};
MultiPackageFailedInspections.storyName = 'Multi-Package Failed Inspections';

export const SkipLastFailedInspection = () => {
  const data = buildFailedAuditWithSkipData();
  return (
    <FailedInspectionStateHtmlPreview
      data={data}
      mockScripts={THREE_SKIPPED_STORYBOOK_SCRIPTS}
    />
  );
};
SkipLastFailedInspection.storyName =
  'Skip Last Failed Inspection — Move to Skipped';

export const SkipAllFailedInspections = () => {
  const data = buildFailedAuditWithSkipData();
  return (
    <FailedInspectionStateHtmlPreview
      data={data}
      mockScripts={ALL_SKIPPED_STORYBOOK_SCRIPTS}
    />
  );
};
SkipAllFailedInspections.storyName = 'Skip All Failed Inspections';
