import { FailedInspection, InspectionStatus } from '../../../../../types';
import type {
  MultiPageReportData,
  PageInspectionResult,
  UrlGroupedResult,
} from '../../../types';

export type ImpactLevel =
  | 'critical'
  | 'serious'
  | 'moderate'
  | 'minor'
  | 'none';
export type RuleGroupStatus = 'new' | 'pre-existing';

export interface RuleGroupInstance {
  key: string;
  pageName: string;
  pageUrl: string;
  containerSelector: string;
  packageName: string;
  selector: string;
  elementHtml: string;
  failureSummary: string;
  severity: Exclude<ImpactLevel, 'none'>;
  status: RuleGroupStatus;
  images?: {
    before?: string;
    after?: string;
  };
}

export interface RuleGroup {
  id: string;
  description: string;
  help: string;
  helpUrl: string;
  wcagTag: string;
  highestSeverity: Exclude<ImpactLevel, 'none'>;
  fixOptions: string[];
  instances: RuleGroupInstance[];
  packages: string[];
}

export interface PassedComponent {
  pageName: string;
  packageName: string;
  auditName: string;
}

const IMPACT_RANK: Record<ImpactLevel, number> = {
  critical: 4,
  minor: 1,
  moderate: 2,
  none: 0,
  serious: 3,
};

type NamedImpact = Exclude<ImpactLevel, 'none'>;

const isImpact = (v: unknown): v is NamedImpact =>
  v === 'critical' || v === 'serious' || v === 'moderate' || v === 'minor';

const pickStronger = (
  a: Exclude<ImpactLevel, 'none'>,
  b: ImpactLevel,
): Exclude<ImpactLevel, 'none'> => {
  const bNonNone = b === 'none' ? a : (b as Exclude<ImpactLevel, 'none'>);
  return IMPACT_RANK[a] >= IMPACT_RANK[bNonNone] ? a : bNonNone;
};

const firstWcagTag = (tags: string[] | undefined): string => {
  if (!Array.isArray(tags)) {
    return '';
  }
  const wcag = tags.find((t) => typeof t === 'string' && t.startsWith('wcag'));
  return wcag ? wcag.toUpperCase() : '';
};

interface AxeNodeLike {
  selector?: string;
  html?: string;
  failureSummary?: string;
  any?: { message?: string }[];
}

interface AxeFailedInspectionLike {
  id?: string;
  impact?: unknown;
  description?: string;
  help?: string;
  helpUrl?: string;
  tags?: string[];
  nodes?: AxeNodeLike[];
  fixOptions?: string[];
}

const extractAxeFailedInspections = (
  audit: PageInspectionResult,
): AxeFailedInspectionLike[] => {
  const details = audit.details as { failedInspections?: unknown } | undefined;
  if (!details || !Array.isArray(details.failedInspections)) {
    return [];
  }
  return details.failedInspections.filter(
    (fi): fi is AxeFailedInspectionLike =>
      !!fi &&
      typeof fi === 'object' &&
      Array.isArray((fi as AxeFailedInspectionLike).nodes),
  );
};

const severityFromBlockLevel = (
  blockLevel: InspectionStatus | undefined,
): NamedImpact => {
  if (blockLevel === InspectionStatus.FAILED) {
    return 'serious';
  }
  if (blockLevel === InspectionStatus.WARNING) {
    return 'minor';
  }
  return 'moderate';
};

const instanceKey = (
  ruleId: string,
  pageName: string,
  selector: string,
  idx: number,
): string => `${ruleId}::${pageName}::${idx}::${selector}`;

export const aggregateRuleGroups = (
  data: MultiPageReportData,
): { ruleGroups: RuleGroup[]; passed: PassedComponent[] } => {
  const groupMap = new Map<string, RuleGroup>();

  const ingestAxeAudit = (
    failures: AxeFailedInspectionLike[],
    audit: PageInspectionResult,
    page: UrlGroupedResult,
    status: RuleGroupStatus,
  ): void => {
    failures.forEach((fi) => {
      const ruleId = fi.id || 'unknown-rule';
      const impact: NamedImpact = isImpact(fi.impact) ? fi.impact : 'moderate';

      const existing = groupMap.get(ruleId);
      let group: RuleGroup;
      if (existing) {
        group = existing;
      } else {
        const fallbackFix =
          Array.isArray(fi.nodes) && fi.nodes[0]?.any
            ? fi.nodes[0].any
                .map((c) => c.message)
                .filter((m): m is string => typeof m === 'string')
            : [];
        group = {
          description: fi.help || fi.description || ruleId,
          fixOptions:
            Array.isArray(fi.fixOptions) && fi.fixOptions.length > 0
              ? fi.fixOptions
              : fallbackFix,
          help: fi.help || ruleId,
          helpUrl: fi.helpUrl || '',
          highestSeverity: impact,
          id: ruleId,
          instances: [],
          packages: [],
          wcagTag: firstWcagTag(fi.tags),
        };
        groupMap.set(ruleId, group);
      }

      group.highestSeverity = pickStronger(group.highestSeverity, impact);

      const pkgName = page.packageName || audit.packageName || 'Unpackaged';
      if (!group.packages.includes(pkgName)) {
        group.packages.push(pkgName);
      }

      const nodes = Array.isArray(fi.nodes) ? fi.nodes : [];
      nodes.forEach((node, idx) => {
        const selector = node.selector || '';
        group.instances.push({
          containerSelector: audit.containerSelector || '',
          elementHtml: node.html || '',
          failureSummary: node.failureSummary || '',
          key: instanceKey(ruleId, page.pageName, selector, idx),
          packageName: pkgName,
          pageName: page.pageName,
          pageUrl: page.pageUrl,
          selector,
          severity: impact,
          status,
        });
      });
    });
  };

  const ingestFlatAudit = (
    audit: PageInspectionResult,
    page: UrlGroupedResult,
    status: RuleGroupStatus,
  ): void => {
    const failures = Array.isArray(audit.failedInspections)
      ? (audit.failedInspections as FailedInspection[])
      : [];
    if (failures.length === 0) {
      return;
    }

    const ruleId =
      audit.inspectionId || audit.inspectionName || 'unknown-inspection';
    const description =
      audit.inspectionName || audit.inspectionId || 'Inspection';
    const pkgName = page.packageName || audit.packageName || 'Unpackaged';

    const existing = groupMap.get(ruleId);
    const group: RuleGroup = existing ?? {
      description,
      fixOptions: [],
      help: description,
      helpUrl: '',
      highestSeverity: 'moderate',
      id: ruleId,
      instances: [],
      packages: [],
      wcagTag: '',
    };
    if (!existing) {
      groupMap.set(ruleId, group);
    }
    if (!group.packages.includes(pkgName)) {
      group.packages.push(pkgName);
    }

    failures.forEach((fi, idx) => {
      const impact = severityFromBlockLevel(fi.blockLevel);
      group.highestSeverity = pickStronger(group.highestSeverity, impact);
      const selector = fi.elementSelector || '';
      group.instances.push({
        containerSelector: audit.containerSelector || '',
        elementHtml: '',
        failureSummary: fi.message || '',
        images: fi.images,
        key: instanceKey(ruleId, page.pageName, selector, idx),
        packageName: pkgName,
        pageName: page.pageName,
        pageUrl: page.pageUrl,
        selector,
        severity: impact,
        status,
      });
    });
  };

  const ingestPage = (
    page: UrlGroupedResult,
    status: RuleGroupStatus,
  ): void => {
    page.audits.forEach((audit) => {
      const axeFailures = extractAxeFailedInspections(audit);
      if (axeFailures.length > 0) {
        ingestAxeAudit(axeFailures, audit, page, status);
      } else {
        ingestFlatAudit(audit, page, status);
      }
    });
  };

  data.pages.forEach((page) => {
    const status: RuleGroupStatus =
      page.status === 'warning' ? 'pre-existing' : 'new';
    ingestPage(page, status);
  });
  data.benchmarkPages?.forEach((page) => ingestPage(page, 'pre-existing'));

  const ruleGroups = Array.from(groupMap.values());

  const passedSet = new Map<string, PassedComponent>();
  data.pages.forEach((page) => {
    if (page.status !== 'passed') {
      return;
    }
    const pkgName = page.packageName || 'Unpackaged';
    const key = `${pkgName}::${page.pageName}`;
    if (!passedSet.has(key)) {
      passedSet.set(key, {
        auditName: page.audits[0]?.auditName || '',
        packageName: pkgName,
        pageName: page.pageName,
      });
    }
  });

  ruleGroups.sort((a, b) => {
    if (a.highestSeverity !== b.highestSeverity) {
      return IMPACT_RANK[b.highestSeverity] - IMPACT_RANK[a.highestSeverity];
    }
    return a.description.localeCompare(b.description);
  });

  return { passed: Array.from(passedSet.values()), ruleGroups };
};

export interface ComponentRuleEntry {
  group: RuleGroup;
  instances: RuleGroupInstance[];
  newCount: number;
  preExistingCount: number;
}

export interface ComponentNode {
  componentName: string;
  pageName: string;
  pageUrl: string;
  packageName: string;
  status: 'failed' | 'pre-existing' | 'passed';
  rules: ComponentRuleEntry[];
  newRuleCount: number;
  preExistingRuleCount: number;
  totalElements: number;
}

export interface PackageNode {
  packageName: string;
  components: ComponentNode[];
  failedComponentCount: number;
  preExistingComponentCount: number;
  passedComponentCount: number;
}

const friendlyComponentName = (pageName: string): string => {
  if (!pageName) {
    return 'Component';
  }
  const stripped = pageName.replace(/-a11y$/i, '');
  const firstSegment = stripped.split('-')[0] || stripped;
  return firstSegment;
};

const compKey = (pkg: string, page: string): string => `${pkg}::${page}`;

export const aggregatePackageTree = (
  data: MultiPageReportData,
  ruleGroups: RuleGroup[],
): PackageNode[] => {
  const componentMap = new Map<string, ComponentNode>();

  const ensureComponent = (
    pkgName: string,
    pageName: string,
    pageUrl: string,
    initialStatus: ComponentNode['status'],
  ): ComponentNode => {
    const key = compKey(pkgName, pageName);
    const existing = componentMap.get(key);
    if (existing) {
      return existing;
    }
    const node: ComponentNode = {
      componentName: friendlyComponentName(pageName),
      newRuleCount: 0,
      packageName: pkgName,
      pageName,
      pageUrl,
      preExistingRuleCount: 0,
      rules: [],
      status: initialStatus,
      totalElements: 0,
    };
    componentMap.set(key, node);
    return node;
  };

  const allPages = [
    ...data.pages,
    ...((data.benchmarkPages as UrlGroupedResult[] | undefined) ?? []),
  ];
  allPages.forEach((page) => {
    const pkgName = page.packageName || 'Unpackaged';
    const compStatus: ComponentNode['status'] =
      page.status === 'passed'
        ? 'passed'
        : page.status === 'warning'
        ? 'pre-existing'
        : 'failed';
    ensureComponent(pkgName, page.pageName, page.pageUrl, compStatus);
  });

  ruleGroups.forEach((rg) => {
    const byComp = new Map<string, RuleGroupInstance[]>();
    rg.instances.forEach((inst) => {
      const key = compKey(inst.packageName, inst.pageName);
      const list = byComp.get(key) ?? [];
      list.push(inst);
      byComp.set(key, list);
    });
    byComp.forEach((insts, key) => {
      const [pkgName, pageName] = key.split('::');
      const pageUrl = insts[0]?.pageUrl || '';
      const newCount = insts.filter((i) => i.status === 'new').length;
      const preExistingCount = insts.length - newCount;
      const compStatus: ComponentNode['status'] =
        newCount > 0 ? 'failed' : 'pre-existing';
      const comp = ensureComponent(pkgName, pageName, pageUrl, compStatus);
      if (comp.status === 'passed') {
        comp.status = compStatus;
      } else if (comp.status === 'pre-existing' && newCount > 0) {
        comp.status = 'failed';
      }
      comp.rules.push({
        group: rg,
        instances: insts,
        newCount,
        preExistingCount,
      });
      comp.totalElements += insts.length;
      if (newCount > 0) {
        comp.newRuleCount += 1;
      } else {
        comp.preExistingRuleCount += 1;
      }
    });
  });

  componentMap.forEach((comp) => {
    comp.rules.sort((a, b) => {
      const sa = IMPACT_RANK[a.group.highestSeverity];
      const sb = IMPACT_RANK[b.group.highestSeverity];
      if (sa !== sb) {
        return sb - sa;
      }
      return a.group.description.localeCompare(b.group.description);
    });
  });

  const packageMap = new Map<string, PackageNode>();
  componentMap.forEach((comp) => {
    const node = packageMap.get(comp.packageName) ?? {
      components: [],
      failedComponentCount: 0,
      packageName: comp.packageName,
      passedComponentCount: 0,
      preExistingComponentCount: 0,
    };
    node.components.push(comp);
    if (comp.status === 'failed') {
      node.failedComponentCount += 1;
    } else if (comp.status === 'pre-existing') {
      node.preExistingComponentCount += 1;
    } else {
      node.passedComponentCount += 1;
    }
    packageMap.set(comp.packageName, node);
  });

  const statusOrder: Record<ComponentNode['status'], number> = {
    failed: 0,
    passed: 2,
    'pre-existing': 1,
  };
  packageMap.forEach((pkg) => {
    pkg.components.sort((a, b) => {
      if (a.status !== b.status) {
        return statusOrder[a.status] - statusOrder[b.status];
      }
      if (a.totalElements !== b.totalElements) {
        return b.totalElements - a.totalElements;
      }
      return a.componentName.localeCompare(b.componentName);
    });
  });

  return Array.from(packageMap.values()).sort((a, b) => {
    const aFails = a.failedComponentCount + a.preExistingComponentCount;
    const bFails = b.failedComponentCount + b.preExistingComponentCount;
    if (aFails !== bFails) {
      return bFails - aFails;
    }
    return a.packageName.localeCompare(b.packageName);
  });
};
