import { InspectionStatus } from '../../../types';
import {
  AUDIT_GROUP_ERROR,
  AUDIT_GROUP_FAILED,
  AUDIT_GROUP_PASSED,
  AUDIT_GROUP_SKIPPED,
  AUDIT_GROUP_WARNING,
} from '../constants/report-strings';

export const getGroupIcon = (groupType: InspectionStatus): string => {
  switch (groupType) {
    case InspectionStatus.PASSED:
      return `<svg fill="none" stroke="currentColor" viewBox="0 0 24 24" width="24" height="24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
                      d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>`;
    case InspectionStatus.FAILED:
      return `<svg fill="none" stroke="currentColor" viewBox="0 0 24 24" width="24" height="24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
                      d="M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>`;
    case InspectionStatus.WARNING:
      return `<svg fill="none" stroke="currentColor" viewBox="0 0 24 24" width="24" height="24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
                      d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" />
              </svg>`;
    case InspectionStatus.ERROR:
      return `<svg fill="none" stroke="currentColor" viewBox="0 0 24 24" width="24" height="24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
                      d="M12 8v4m0 4h.01M21 12c0 4.97-4.03 9-9 9s-9-4.03-9-9 4.03-9 9-9 9 4.03 9 9z" />
              </svg>`;
    case InspectionStatus.SKIPPED:
      return `<svg fill="none" stroke="currentColor" viewBox="0 0 24 24" width="24" height="24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
                      d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>`;
  }
};

export const getStatusGroupConfig = (
  status: InspectionStatus,
): {
  icon: string;
  color: string;
  title: string;
  collapsedByDefault: boolean;
} => {
  switch (status) {
    case InspectionStatus.PASSED:
      return {
        collapsedByDefault: true,
        color: 'success',
        icon: `<svg fill="none" stroke="currentColor" viewBox="0 0 24 24" width="20" height="20">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
                d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>`,
        title: AUDIT_GROUP_PASSED,
      };
    case InspectionStatus.FAILED:
      return {
        collapsedByDefault: false,
        color: 'error',
        icon: `<svg fill="none" stroke="currentColor" viewBox="0 0 24 24" width="20" height="20">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
                d="M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>`,
        title: AUDIT_GROUP_FAILED,
      };
    case InspectionStatus.WARNING:
      return {
        collapsedByDefault: false,
        color: 'benchmark',
        icon: `<svg fill="none" stroke="currentColor" viewBox="0 0 24 24" width="20" height="20">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
                d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" />
        </svg>`,
        title: AUDIT_GROUP_WARNING,
      };
    case InspectionStatus.ERROR:
      return {
        collapsedByDefault: false,
        color: 'serious',
        icon: `<svg fill="none" stroke="currentColor" viewBox="0 0 24 24" width="20" height="20">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
                d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>`,
        title: AUDIT_GROUP_ERROR,
      };
    case InspectionStatus.SKIPPED:
      return {
        collapsedByDefault: true,
        color: 'muted',
        icon: `<svg fill="none" stroke="currentColor" viewBox="0 0 24 24" width="20" height="20">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
                d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>`,
        title: AUDIT_GROUP_SKIPPED,
      };
  }
};
