/** Failed inspection count updates: total, per-group, per-item, and analysis summary. */
export const countUpdateScripts = `
        function updateFailedInspectionCounts(delta) {
            var totalEl = document.querySelector('.summary-failed-inspections .summary-number');
            if (totalEl) {
                var current = parseInt(totalEl.textContent, 10) || 0;
                totalEl.textContent = Math.max(0, current + delta);
            }
        }

        function updateFailedInspectionGroupCount(failedInspectionGroup, delta) {
            if (!failedInspectionGroup) {
                console.warn('[failed-inspection-state] updateFailedInspectionGroupCount: missing failedInspectionGroup', { delta: delta });
                return;
            }

            var titleEl = failedInspectionGroup.querySelector('.failed-inspection-group-title');
            if (titleEl) {
                var textNodes = [];
                for (var i = 0; i < titleEl.childNodes.length; i++) {
                    if (titleEl.childNodes[i].nodeType === 3) {
                        textNodes.push(titleEl.childNodes[i]);
                    }
                }
                for (var i = 0; i < textNodes.length; i++) {
                    var text = textNodes[i].textContent;
                    var match = text.match(/(.*\\()(\\d+)(\\).*)/);
                    if (match) {
                        var newCount = Math.max(0, parseInt(match[2], 10) + delta);
                        textNodes[i].textContent = match[1] + newCount + match[3];
                        break;
                    }
                }
            }

            var descEl = failedInspectionGroup.querySelector('.failed-inspection-group-description');
            if (descEl) {
                var descText = descEl.textContent || '';
                var descMatch = descText.match(/^(\\d+)(\\s+rule)/);
                if (descMatch) {
                    var newDescCount = Math.max(0, parseInt(descMatch[1], 10) + delta);
                    descEl.textContent = descText.replace(/^\\d+/, newDescCount)
                        .replace(/\\brules?\\b/, newDescCount === 1 ? 'rule' : 'rules');
                }
            }

            // Hide the group when all failed inspections are skipped, show it again on unskip
            var groupCount = 0;
            if (titleEl) {
                var countMatch = (titleEl.textContent || '').match(/\\((\\d+)\\)/);
                groupCount = countMatch ? parseInt(countMatch[1], 10) : 0;
            }
            failedInspectionGroup.style.display = groupCount === 0 ? 'none' : '';
        }

        function findPageRowForGroupItem(groupItem) {
            var modal = groupItem.closest('.modal-overlay');
            if (modal && modal.id) {
                var row = document.querySelector('.page-row[data-modal-id="' + modal.id + '"]');
                if (row) return row;
            }
            var pageUrl = groupItem.getAttribute('data-page-url');
            if (!pageUrl) return null;
            var rows = document.querySelectorAll('.page-row');
            for (var i = 0; i < rows.length; i++) {
                var urlEl = rows[i].querySelector('.page-url');
                if (!urlEl || urlEl.textContent.trim() !== pageUrl) continue;
                if (rows[i].closest('.page-group-benchmark')) continue;
                return rows[i];
            }
            return null;
        }

        function updateItemFailedInspectionCount(groupItem, delta) {
            var itemCountEl = groupItem.querySelector('.audits-group-item-failed-inspections');
            if (itemCountEl) {
                var match = (itemCountEl.textContent || '').match(/(\\d+)/);
                var current = match ? parseInt(match[1], 10) : 0;
                var newCount = Math.max(0, current + delta);
                itemCountEl.setAttribute('data-active-count', newCount);
                refreshItemFailedInspectionLabel(groupItem);
            }

            var row = findPageRowForGroupItem(groupItem);
            if (row) {
                var countEl = row.querySelector('.failed-inspections-count, .no-failed-inspections');
                if (countEl) {
                    var cur = parseInt(countEl.textContent, 10) || 0;
                    var nc = Math.max(0, cur + delta);
                    countEl.textContent = nc;
                    countEl.className = nc > 0 ? 'failed-inspections-count' : 'no-failed-inspections';
                }
            }
        }

        function refreshItemFailedInspectionLabel(groupItem) {
            var itemCountEl = groupItem.querySelector('.audits-group-item-failed-inspections');
            if (!itemCountEl) return;
            var activeCount = parseInt(itemCountEl.getAttribute('data-active-count'), 10);
            if (isNaN(activeCount)) {
                var m = (itemCountEl.textContent || '').match(/(\\d+)/);
                activeCount = m ? parseInt(m[1], 10) : 0;
            }
            itemCountEl.textContent = activeCount + ' failed inspection' + (activeCount !== 1 ? 's' : '');

            var skippedList = groupItem.querySelector('.skipped-failed-inspections-list');
            var skippedCount = skippedList ? skippedList.children.length : 0;
            var skippedBadge = groupItem.querySelector('.audits-group-item-skipped');
            if (skippedCount > 0) {
                if (!skippedBadge) {
                    skippedBadge = document.createElement('span');
                    skippedBadge.className = 'audits-group-item-skipped';
                    itemCountEl.parentNode.insertBefore(skippedBadge, itemCountEl.nextSibling);
                }
                skippedBadge.textContent = skippedCount + ' skipped';
            } else if (skippedBadge) {
                skippedBadge.remove();
            }
            itemCountEl.setAttribute('data-active-count', activeCount);
        }

        function updateNewIssuesCount(delta) {
            var newCount;
            var newIssuesEl = document.querySelector('.summary-new-issues .summary-number');
            if (newIssuesEl) {
                var current = parseInt(newIssuesEl.textContent, 10) || 0;
                newCount = Math.max(0, current + delta);
                newIssuesEl.textContent = newCount;

                var labelEl = document.querySelector('.summary-new-issues .summary-label');
                if (labelEl) {
                    labelEl.textContent = newCount > 0 ? 'New Failures (Blocking)' : 'New Failures';
                }
            } else {
                // Non-benchmark layout: extract current count from banner title, then apply delta
                var titleEl2 = document.querySelector('.pr-status-title');
                if (titleEl2) {
                    var countMatch = (titleEl2.textContent || '').match(/(\\d+)/);
                    var current2 = countMatch ? parseInt(countMatch[1], 10) : 0;
                    newCount = Math.max(0, current2 + delta);
                } else {
                    newCount = 0;
                }
            }

            var titleEl = document.querySelector('.pr-status-title');
            if (!titleEl) return;
            if (newCount > 0) {
                titleEl.textContent = 'PR Blocked \\u2014 ' + newCount + ' new accessibility issue' + (newCount !== 1 ? 's' : '') + ' found';
                var banner = titleEl.closest('.pr-status-banner');
                if (banner && banner.classList.contains('pr-passing')) {
                    banner.classList.remove('pr-passing');
                    banner.classList.add('pr-blocked');
                    var iconEl = banner.querySelector('.pr-status-icon');
                    if (iconEl) iconEl.textContent = '\\u2715';
                    var descEl = banner.querySelector('.pr-status-desc');
                    if (descEl) descEl.textContent = 'This PR introduced new accessibility issues. Pre-existing issues are non-blocking.';
                }
            } else {
                titleEl.textContent = 'PR Passing \\u2014 No new accessibility issues';
                var banner = titleEl.closest('.pr-status-banner');
                if (banner) {
                    banner.classList.remove('pr-blocked');
                    banner.classList.add('pr-passing');
                    var iconEl = banner.querySelector('.pr-status-icon');
                    if (iconEl) iconEl.textContent = '\\u2713';
                }
                var descEl = banner && banner.querySelector('.pr-status-desc');
                if (descEl) {
                    var benchmarkCard = document.querySelector('.summary-benchmark .summary-number');
                    var benchmarkCount = benchmarkCard ? parseInt(benchmarkCard.textContent, 10) || 0 : 0;
                    descEl.textContent = benchmarkCount > 0
                        ? 'This PR introduces no new accessibility issues. ' + benchmarkCount + ' pre-existing issue' + (benchmarkCount !== 1 ? 's were' : ' was') + ' found — they do not block this PR.'
                        : 'This PR introduces no new accessibility issues.';
                }
            }
        }

        function updatePageRowSkippedCount(groupItem, delta) {
            var row = findPageRowForGroupItem(groupItem);
            if (row) {
                var countEl = row.querySelector('.skipped-failed-inspections-count');
                if (countEl) {
                    var cur = parseInt(countEl.textContent, 10) || 0;
                    countEl.textContent = Math.max(0, cur + delta);
                }
            }
        }

        function updateAnalysisSummary() {
            var totalEl = document.querySelector('.summary-failed-inspections .summary-number');
            if (!totalEl) return;
            var totalFailedInspections = parseInt(totalEl.textContent, 10) || 0;

            var descEl = document.querySelector('.analysis-summary-description');
            if (!descEl) return;

            var totalAuditsEl = document.querySelector('.summary-total .summary-number');
            var totalAudits = totalAuditsEl ? (parseInt(totalAuditsEl.textContent, 10) || 0) : 0;

            if (totalFailedInspections === 0) {
                descEl.textContent = 'Scanned ' + totalAudits + ' audit' + (totalAudits !== 1 ? 's' : '') + ' — no failed inspections detected.';
                return;
            }

            var strongs = descEl.querySelectorAll('strong.skip-countable');
            if (strongs.length < 2) {
                var auditsWithFailedInspections2 = 0;
                var items2 = document.querySelectorAll('.audits-group-item[data-inspection-id]');
                for (var k = 0; k < items2.length; k++) {
                    var ce = items2[k].querySelector('.audits-group-item-failed-inspections');
                    if (ce) {
                        var mm = (ce.textContent || '').match(/(\\d+)/);
                        if (mm && parseInt(mm[1], 10) > 0) auditsWithFailedInspections2++;
                    }
                }
                var auditWord = totalAudits !== 1 ? 's' : '';
                var failedInspectionWord = totalFailedInspections !== 1 ? 's' : '';
                var auditFailedInspectionWord = auditsWithFailedInspections2 !== 1 ? 's' : '';
                descEl.textContent = '';
                var t1 = document.createTextNode('Scanned ');
                var s0 = document.createElement('strong');
                s0.textContent = totalAudits;
                var t2 = document.createTextNode(' audit' + auditWord + ', found ');
                var s1 = document.createElement('strong');
                s1.className = 'skip-countable';
                s1.textContent = totalFailedInspections;
                var t3 = document.createTextNode(' failed inspection' + failedInspectionWord + ' across ');
                var s2 = document.createElement('strong');
                s2.className = 'skip-countable';
                s2.textContent = auditsWithFailedInspections2;
                var t4 = document.createTextNode(' audit' + auditFailedInspectionWord + '.');
                descEl.appendChild(t1);
                descEl.appendChild(s0);
                descEl.appendChild(t2);
                descEl.appendChild(s1);
                descEl.appendChild(t3);
                descEl.appendChild(s2);
                descEl.appendChild(t4);
                return;
            }

            strongs[0].textContent = totalFailedInspections;

            var auditsWithFailedInspections = 0;
            var items = document.querySelectorAll('.audits-group-item[data-inspection-id]');
            for (var i = 0; i < items.length; i++) {
                var countEl = items[i].querySelector('.audits-group-item-failed-inspections');
                if (countEl) {
                    var m = (countEl.textContent || '').match(/(\\d+)/);
                    if (m && parseInt(m[1], 10) > 0) auditsWithFailedInspections++;
                }
            }
            strongs[1].textContent = auditsWithFailedInspections;
        }
`;
