/** Styles specific to multi-page accessibility reports - uses CSS variables for dark mode */
export const multiPageStyles = `
    /* Analysis Summary */
    .analysis-summary {
        background: var(--color-bg-card);
        border-radius: 12px;
        padding: 24px;
        margin-bottom: 24px;
        box-shadow: 0 1px 3px var(--color-border-default);
    }

    .analysis-summary-title {
        font-size: 20px;
        font-weight: 700;
        color: var(--color-text-primary);
        margin: 0 0 12px 0;
        padding-bottom: 12px;
        border-bottom: 3px solid var(--color-brand-primary);
        display: inline-block;
    }

    .analysis-summary-description {
        font-size: 15px;
        line-height: 1.6;
        color: var(--color-text-secondary);
        margin: 0;
    }

    .analysis-summary-description strong {
        color: var(--color-text-primary);
        font-weight: 700;
    }

    .analysis-summary-timestamp {
        display: block;
        margin-top: 10px;
        font-size: 12px;
        color: var(--color-text-muted);
    }

    /* Summary Grid */
    .summary-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
        gap: 16px;
        margin-bottom: 32px;
    }
    
    .summary-card {
        background: var(--color-bg-card);
        border-radius: 12px;
        padding: 20px;
        display: flex;
        align-items: flex-start;
        gap: 16px;
        box-shadow: 0 1px 3px var(--color-border-default);
        transition: transform 0.2s, box-shadow 0.2s;
    }
    
    .summary-card:hover {
        transform: translateY(-2px);
        box-shadow: 0 4px 12px var(--shadow-md);
    }
    
    .summary-icon {
        width: 48px;
        height: 48px;
        border-radius: 12px;
        display: flex;
        align-items: center;
        justify-content: center;
        flex-shrink: 0;
    }
    
    .summary-icon svg {
        width: 24px;
        height: 24px;
    }
    
    .summary-total .summary-icon { background: var(--color-bg-info); color: var(--color-info); }
    .summary-passed .summary-icon { background: var(--color-bg-success); color: var(--color-success); }
    .summary-failed .summary-icon { background: var(--color-bg-error); color: var(--color-error); }
    .summary-warning .summary-icon { background: var(--color-bg-warning); color: var(--color-warning); }
    .summary-failed-inspections .summary-icon { background: var(--color-bg-failed-inspections); color: var(--color-failed-inspections); }
    .summary-rate .summary-icon { background: var(--color-bg-info); color: var(--color-info); }
    .summary-time .summary-icon { background: var(--color-bg-gray); color: var(--color-text-secondary); }
    
    .summary-content {
        flex: 1;
    }
    
    .summary-number {
        font-size: 28px;
        font-weight: 700;
        color: var(--color-text-primary);
        line-height: 1.2;
    }
    
    .summary-label {
        font-size: 13px;
        color: var(--color-text-muted);
        margin-top: 4px;
    }
    
    .info-code {
        background: var(--color-bg-gray);
        padding: 4px 8px;
        border-radius: 4px;
        font-family: monospace;
        font-size: 13px;
    }
    
    /* Page Groups */
    .page-group {
        background: var(--color-bg-card);
        border-radius: 12px;
        margin-bottom: 24px;
        overflow: hidden;
        box-shadow: 0 1px 3px var(--color-border-default);
    }
    
    .page-group-header {
        padding: 16px 20px;
        display: flex;
        align-items: center;
        justify-content: space-between;
        border-bottom: 1px solid var(--color-border-light);
    }
    
    .page-group-header.collapsible {
        cursor: pointer;
        user-select: none;
    }
    
    .page-group-header.collapsible:hover {
        background: var(--color-bg-muted);
    }
    
    .page-group-title {
        display: flex;
        align-items: center;
        gap: 12px;
    }
    
    .page-group-title h2 {
        margin: 0;
        font-size: 18px;
        font-weight: 600;
        color: var(--color-text-primary);
    }
    
    .group-icon {
        display: flex;
        align-items: center;
    }
    
    .page-count {
        color: var(--color-text-muted);
        font-size: 14px;
        font-weight: 400;
    }
    
    .chevron {
        width: 20px;
        height: 20px;
        color: var(--color-text-muted);
        transition: transform 0.2s;
    }
    
    .page-group-header.expanded .chevron {
        transform: rotate(180deg);
    }
    
    .page-group-content {
        max-height: none;
        overflow: visible;
        transition: max-height 0.3s ease-out;
    }
    
    .page-group-content.collapsed {
        max-height: 0;
        overflow: hidden;
    }
    
    /* Group Colors */
    .page-group-failed .page-group-header {
        background: var(--color-bg-error);
        border-left: 4px solid var(--color-error);
        color: var(--color-error);
    }

    .page-group-warning .page-group-header {
        background: var(--color-bg-warning);
        border-left: 4px solid var(--color-warning);
        color: var(--color-warning);
    }

    .page-group-error .page-group-header {
        background: var(--color-bg-serious);
        border-left: 4px solid var(--color-serious);
        color: var(--color-serious);
    }

    .page-group-passed .page-group-header {
        background: var(--color-bg-success);
        border-left: 4px solid var(--color-success);
        color: var(--color-success);
    }

    .page-group-skipped .page-group-header {
        background: var(--color-bg-gray);
        border-left: 4px solid var(--color-text-muted);
        color: var(--color-text-muted);
    }
    
    /* Pages Table */
    .pages-table {
        width: 100%;
        border-collapse: collapse;
    }
    
    .pages-table thead {
        background: var(--color-bg-muted);
    }
    
    .pages-table th {
        padding: 12px 16px;
        text-align: left;
        font-weight: 600;
        font-size: 12px;
        text-transform: uppercase;
        color: var(--color-text-muted);
        letter-spacing: 0.5px;
    }
    
    .pages-table td {
        padding: 16px;
        border-bottom: 1px solid var(--color-border-light);
        vertical-align: middle;
    }
    
    .page-row:last-child td {
        border-bottom: none;
    }
    
    .page-row:hover {
        background: var(--color-bg-muted);
    }
    
    /* Column widths */
    .col-page { width: 50%; }
    .col-component { width: 15%; }
    .col-audits { width: 12%; text-align: center; }
    .col-failed-inspections { width: 12%; text-align: center; }
    .col-skipped { width: 12%; text-align: center; }
    .col-actions { width: 18%; text-align: center; }

    .pages-table th.col-audits,
    .pages-table th.col-failed-inspections,
    .pages-table th.col-skipped,
    .pages-table th.col-actions {
        text-align: center;
    }
    
    /* Package Badge */
    .package-badge {
        display: inline-block;
        font-size: 11px;
        font-weight: 600;
        color: var(--color-brand-primary);
        background: var(--color-bg-card);
        border: 1px solid var(--color-brand-primary);
        border-radius: 4px;
        padding: 1px 6px;
        margin-bottom: 4px;
    }

    /* Page Name */
    .page-name {
        font-weight: 500;
        color: var(--color-text-primary);
        margin-bottom: 4px;
    }
    
    .page-url {
        font-size: 12px;
        color: var(--color-text-muted);
        word-break: break-all;
    }
    
    /* Component Badge */
    .component-badge {
        display: inline-block;
        padding: 4px 10px;
        background: var(--color-bg-gray);
        border-radius: 12px;
        font-size: 12px;
        color: var(--color-text-secondary);
    }
    
    /* Failed Inspections Count */
    .failed-inspections-count {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-width: 32px;
        height: 32px;
        padding: 0 10px;
        background: var(--color-bg-error);
        color: var(--color-error);
        border-radius: 16px;
        font-weight: 600;
        font-size: 14px;
    }

    [data-theme="dark"] .failed-inspections-count {
        background: rgba(248, 81, 73, 0.15);
        color: #ff7b72;
    }
    
    .no-failed-inspections {
        color: var(--color-success);
        font-weight: 500;
    }

    .skipped-failed-inspections-count {
        color: var(--color-text-muted);
        font-weight: 500;
    }

    /* Actions */
    .view-details-btn {
        display: inline-block;
        padding: 6px 14px;
        background: var(--color-brand-primary);
        color: white;
        text-decoration: none;
        border-radius: 6px;
        font-size: 13px;
        font-weight: 500;
        transition: background 0.2s;
    }
    
    .view-details-btn:hover {
        filter: brightness(0.9);
    }

    [data-theme="dark"] .view-details-btn {
        background: #21262d;
        color: #58a6ff;
        border: 1px solid #30363d;
    }

    [data-theme="dark"] .view-details-btn:hover {
        background: #30363d;
        border-color: #58a6ff;
        filter: none;
    }

    .error-message {
        color: var(--color-warning);
        font-size: 13px;
        cursor: help;
    }
    
    /* Header adjustments */
    .header-right {
        display: flex;
        align-items: center;
        gap: 12px;
    }
    
    .header-inspection {
        background: var(--color-bg-muted);
        padding: 6px 12px;
        border-radius: 6px;
        font-size: 14px;
        color: var(--color-text-primary);
        border: 1px solid var(--color-border-default);
    }
    
    /* Skip-flow loading shimmer — hides counts while skips are being fetched */
    @keyframes skip-shimmer {
        0% { opacity: 0.4; }
        50% { opacity: 0.7; }
        100% { opacity: 0.4; }
    }

    body[data-skip-loading] .summary-failed-inspections .summary-number,
    body[data-skip-loading] .failed-inspections-count,
    body[data-skip-loading] .audits-group-item-failed-inspections,
    body[data-skip-loading] .analysis-summary-description .skip-countable {
        color: transparent;
        position: relative;
    }

    body[data-skip-loading] .summary-failed-inspections .summary-number::after,
    body[data-skip-loading] .failed-inspections-count::after,
    body[data-skip-loading] .audits-group-item-failed-inspections::after,
    body[data-skip-loading] .analysis-summary-description .skip-countable::after {
        content: '';
        position: absolute;
        inset: 2px 0;
        background: var(--color-bg-muted);
        border-radius: 4px;
        animation: skip-shimmer 1.5s ease-in-out infinite;
    }

    /* Responsive */
    @media (max-width: 768px) {
        .summary-grid {
            grid-template-columns: repeat(2, 1fr);
        }
        
        .pages-table {
            display: block;
            overflow-x: auto;
        }
        
        .col-component {
            display: none;
        }
    }
`;

/** Scripts specific to multi-page reports */
export const multiPageScripts = `
    function togglePageGroup(header) {
        const content = header.nextElementSibling;
        const isCollapsed = content.classList.contains('collapsed');

        if (isCollapsed) {
            content.classList.remove('collapsed');
            header.classList.add('expanded');
        } else {
            content.classList.add('collapsed');
            header.classList.remove('expanded');
        }

        try {
            var pageGroup = header.closest('.page-group');
            var section = '';
            if (pageGroup) {
                if (pageGroup.classList.contains('page-group-failed')) section = 'failed';
                else if (pageGroup.classList.contains('page-group-passed')) section = 'passed';
                else if (pageGroup.classList.contains('page-group-warning')) section = 'warning';
                else if (pageGroup.classList.contains('page-group-error')) section = 'error';
                else if (pageGroup.classList.contains('page-group-skipped')) section = 'skipped';
            }
            if (typeof biDashboardClick === 'function') {
                biDashboardClick(isCollapsed ? 'expand' : 'collapse', '', section);
            }
        } catch(e) {}
    }

    // Auto-expand failed, warning, and error groups on load
    document.addEventListener('DOMContentLoaded', function() {
        const failedGroups = document.querySelectorAll('.page-group-failed .page-group-content, .page-group-warning .page-group-content, .page-group-error .page-group-content');
        failedGroups.forEach(function(content) {
            content.classList.remove('collapsed');
            content.previousElementSibling.classList.add('expanded');
        });

        if (typeof biDashboardView === 'function') {
            biDashboardView();
        }
    });

    /* ===== Dashboard filter logic (cards + sidebar drill-in + severity counts) ===== */
    function togglePkgNode(event, chevron) {
        if (event && event.stopPropagation) event.stopPropagation();
        var node = chevron.closest('.pkg-tree-node');
        if (!node) return;
        var isOpen = node.classList.toggle('open');
        var header = node.querySelector('.pkg-tree-header');
        if (header) header.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    }

    function handlePkgChevronKey(event, chevron) {
        if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            event.stopPropagation();
            togglePkgNode(event, chevron);
        }
    }

    function handlePkgNodeKey(event, header) {
        if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            header.click();
        }
    }

    function toggleFailedInspectionCard(event, topRow) {
        if (!topRow) return;
        if (event && event.target && (event.target.closest('button') || event.target.closest('a'))) return;
        var card = topRow.closest('.fi-card');
        if (!card) return;
        var willCollapse = !card.classList.contains('v-collapsed');
        card.classList.toggle('v-collapsed');
        card.setAttribute('aria-expanded', willCollapse ? 'false' : 'true');
    }

    function handleFailedInspectionCardKey(event, topRow) {
        if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            toggleFailedInspectionCard(event, topRow);
        }
    }

    function toggleInstanceMoreInfo(btn) {
        if (!btn) return;
        var wrap = btn.closest('.fi-instance');
        if (!wrap) return;
        var info = wrap.querySelector('.instance-more-info');
        var isOpen = btn.classList.toggle('open');
        if (info) info.classList.toggle('open', isOpen);
        btn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    }

    function openScreenshotModal(src, alt) {
        if (!src) return;
        var existing = document.getElementById('screenshot-modal');
        if (existing) existing.remove();
        var overlay = document.createElement('div');
        overlay.id = 'screenshot-modal';
        overlay.className = 'screenshot-modal';
        overlay.setAttribute('role', 'dialog');
        overlay.setAttribute('aria-modal', 'true');
        overlay.setAttribute('aria-label', alt || 'Element screenshot');
        overlay.innerHTML =
            '<button class="screenshot-modal-close" type="button" aria-label="Close">&times;</button>' +
            '<img class="screenshot-modal-img" src="' + src + '" alt="' + (alt || 'Element screenshot') + '" />';
        function close() {
            document.removeEventListener('keydown', onKey);
            overlay.remove();
        }
        function onKey(e) { if (e.key === 'Escape') close(); }
        overlay.addEventListener('click', function(e) { if (e.target === overlay) close(); });
        overlay.querySelector('.screenshot-modal-close').addEventListener('click', close);
        document.addEventListener('keydown', onKey);
        document.body.appendChild(overlay);
        overlay.querySelector('.screenshot-modal-close').focus();
    }

    function handleScreenshotClick(event, el) {
        if (event && event.stopPropagation) event.stopPropagation();
        var src = el.getAttribute('data-screenshot-src') || (el.tagName === 'IMG' ? el.src : '');
        var alt = el.getAttribute('data-screenshot-alt') || el.getAttribute('alt') || 'Element screenshot';
        if (src) { openScreenshotModal(src, alt); return; }
        // Placeholder: no image available — open modal with a generic preview
        var placeholder = 'data:image/svg+xml;utf8,' + encodeURIComponent(
            '<svg xmlns="http://www.w3.org/2000/svg" width="640" height="400">' +
            '<rect width="640" height="400" fill="#f4f4f5"/>' +
            '<text x="50%" y="50%" fill="#6b6b78" text-anchor="middle" font-family="sans-serif" font-size="18" dy=".3em">Element screenshot not available</text>' +
            '</svg>'
        );
        openScreenshotModal(placeholder, 'Element screenshot not available');
    }

    function copyInstanceSelector(btn) {
        if (!btn) return;
        var text = btn.getAttribute('data-copy') || '';
        if (!text) return;
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text).catch(function() {});
        }
        showCopyFeedback(btn);
    }

    function showCopyFeedback(btn) {
        if (!btn || btn.dataset.copying === '1') return;
        btn.dataset.copying = '1';
        btn.classList.add('is-copied');
        if (btn._copyResetTimer) clearTimeout(btn._copyResetTimer);
        btn._copyResetTimer = setTimeout(function() {
            btn.classList.remove('is-copied');
            delete btn.dataset.copying;
        }, 1400);
    }

    function handleInstanceAction(event, btn, kind) {
        if (event && event.stopPropagation) event.stopPropagation();
        var inst = btn ? btn.closest('.fi-instance') : null;
        if (!inst) return;
        var ruleId = inst.getAttribute('data-rule-id') || '';
        var selector = inst.getAttribute('data-element-selector') || '';
        var pageUrl = inst.getAttribute('data-page-url') || '';
        var containerSelector = inst.getAttribute('data-container-selector') || '';

        if (kind === 'skip') {
            if (typeof openSkipModal === 'function') {
                openSkipModal(ruleId, selector, pageUrl, containerSelector);
            } else {
                console.info('[a11y] IGNORE clicked for', ruleId, selector, '(skip flow unavailable in preview)');
            }
        } else if (kind === 'fix') {
            if (typeof openFixAiModal === 'function') {
                openFixAiModal(ruleId, selector, pageUrl, containerSelector);
            } else {
                console.info('[a11y] FIX WITH AI clicked for', ruleId, selector, '(fix flow unavailable in preview)');
            }
        }
    }

    function toggleSeverityDropdown(event) {
        if (event && event.stopPropagation) event.stopPropagation();
        var btn = document.getElementById('sevDropdownBtn');
        var menu = document.getElementById('sevDropdownMenu');
        if (!btn || !menu) return;
        var isOpen = menu.classList.toggle('open');
        btn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    }

    function selectSeverity(btn) {
        if (!btn) return;
        var severity = btn.getAttribute('data-severity') || 'all';
        var menu = btn.closest('.severity-dropdown-menu');
        if (menu) {
            menu.querySelectorAll('.severity-dropdown-item').forEach(function(el) {
                var isSame = el === btn;
                el.classList.toggle('active', isSame);
                el.setAttribute('aria-selected', isSame ? 'true' : 'false');
            });
        }
        var label = document.querySelector('#sevDropdownBtn .severity-dropdown-label');
        if (label) {
            var labelText = btn.querySelector('.sev-label');
            label.textContent = labelText ? labelText.textContent.trim() : btn.textContent.trim();
        }
        if (menu) menu.classList.remove('open');
        var btnEl = document.getElementById('sevDropdownBtn');
        if (btnEl) btnEl.setAttribute('aria-expanded', 'false');
        window.__dashboardState = window.__dashboardState || {};
        window.__dashboardState.severity = severity;
        applyDashboardFilters();
    }

    function updateSidebarTitle(state, totals) {
        var titleEl = document.getElementById('sidebarTitle');
        if (!titleEl) return;
        if (state.filter === 'passed') {
            titleEl.textContent = 'Passed Components (' + totals.passed + ') Packages (' + (totals.passedPkgs || 0) + ')';
        } else if (state.filter === 'pre-existing') {
            titleEl.textContent = 'Pre-existing (' + totals.preExistingGroups + ') Packages (' + (totals.preExistingPkgs || 0) + ')';
        } else if (state.filter === 'failed') {
            titleEl.textContent = 'Failed Components (' + totals.failedGroups + ') Packages (' + (totals.failedPkgs || 0) + ')';
        } else {
            var total = totals.failedGroups + totals.preExistingGroups + totals.passed;
            titleEl.textContent = 'Components (' + total + ') Packages (' + (totals.allPkgs || 0) + ')';
        }
    }

    function updateMainTitle(state, visibleCards, visibleInstances) {
        var titleEl = document.getElementById('mainTitle');
        var scopeEl = document.getElementById('mainScope');
        var countEl = document.getElementById('mainCount');
        var verb = '';
        if (state.filter === 'failed') verb = 'failed';
        else if (state.filter === 'pre-existing') verb = 'pre-existing';
        else if (state.filter === 'passed') verb = 'passed';

        if (titleEl) {
            if (state.rg) {
                var card = document.querySelector('.fi-card[data-rg="' + cssEscape(state.rg) + '"]');
                var name = card ? (card.querySelector('.card-rule-name') || {}).textContent : null;
                titleEl.textContent = name || 'Failed inspection';
            } else if (state.component) {
                titleEl.textContent = (verb ? capitalize(verb) + ' rules' : 'Rules') + ' in';
            } else if (state.pkg) {
                titleEl.textContent = (verb ? capitalize(verb) + ' components' : 'Components') + ' in';
            } else if (state.filter === 'passed') {
                titleEl.textContent = 'All passed components';
            } else if (state.filter === 'pre-existing') {
                titleEl.textContent = 'All pre-existing components';
            } else if (state.filter === 'failed') {
                titleEl.textContent = 'All failed components';
            } else {
                titleEl.textContent = 'All components';
            }
        }
        if (scopeEl) {
            if (state.component && !state.rg) {
                scopeEl.innerHTML = '<span class="main-scope-chip">' + escapeForHtml(state.component) + '</span>';
            } else if (state.pkg && !state.rg) {
                scopeEl.innerHTML = '<span class="main-scope-chip">' + escapeForHtml(state.pkg) + '</span>';
            } else {
                scopeEl.innerHTML = '';
            }
        }
        if (countEl) {
            var itemCount = state.filter === 'passed' ? visibleCards : visibleInstances;
            countEl.textContent = itemCount + ' item' + (itemCount === 1 ? '' : 's');
        }
    }

    function capitalize(s) {
        return s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
    }

    function escapeForHtml(s) {
        return String(s)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    }

    function cssEscape(val) {
        if (window.CSS && window.CSS.escape) return window.CSS.escape(String(val));
        return String(val).replace(/["'\\\\]/g, '\\\\$&');
    }

    function cardMatches(card, state) {
        if (state.rg) return card.getAttribute('data-rg') === state.rg;
        var severity = card.getAttribute('data-severity') || 'moderate';
        var hasNew = card.getAttribute('data-has-new') === '1';
        var hasPreExisting = card.getAttribute('data-has-pre-existing') === '1';
        var packages = (card.getAttribute('data-packages') || '').split('|').filter(Boolean);
        var cardComp = card.getAttribute('data-component') || '';

        if (state.filter === 'failed' && !hasNew) return false;
        if (state.filter === 'pre-existing' && !hasPreExisting) return false;
        if (state.severity !== 'all' && severity !== state.severity) return false;
        if (state.pkg && packages.indexOf(state.pkg) === -1) return false;
        if (state.component && cardComp !== state.component) return false;
        return true;
    }

    function passedMatches(card, state) {
        if (state.filter !== 'passed' && state.filter !== 'all') return false;
        if (state.rg) return false;
        var pkg = card.getAttribute('data-package') || '';
        if (state.pkg && pkg !== state.pkg) return false;
        return true;
    }

    function applyDashboardFilters() {
        var state = window.__dashboardState || { filter: 'failed', pkg: null, rg: null, severity: 'all' };
        var failedInspectionsList = document.getElementById('failedInspectionsList');
        var passedList = document.getElementById('passedList');
        var celebration = document.getElementById('celebration');
        if (!failedInspectionsList) return;

        var showPassedList = state.filter === 'passed' || state.filter === 'all';
        var showFailedList = state.filter !== 'passed';
        if (passedList) passedList.classList.toggle('is-hidden', !showPassedList);
        failedInspectionsList.classList.toggle('is-hidden', !showFailedList);

        var visibleCards = 0;
        var visibleInstances = 0;

        if (showPassedList && passedList) {
            var passedCards = passedList.querySelectorAll('.passed-card');
            passedCards.forEach(function(card) {
                var visible = passedMatches(card, state);
                card.classList.toggle('is-hidden', !visible);
                if (visible) visibleCards += 1;
            });
        }

        if (showFailedList) {
            var cards = failedInspectionsList.querySelectorAll('.fi-card');
            cards.forEach(function(card) {
                var visible = cardMatches(card, state);
                card.classList.toggle('is-hidden', !visible);
                if (visible) {
                    visibleCards += 1;
                    var instances = card.querySelectorAll('.fi-instance');
                    var instanceVisibleInCard = 0;
                    instances.forEach(function(inst) {
                        var pkg = inst.getAttribute('data-package') || '';
                        var instVisible = !state.pkg || pkg === state.pkg;
                        inst.classList.toggle('is-hidden', !instVisible);
                        if (instVisible) {
                            instanceVisibleInCard += 1;
                        }
                    });
                    // If no instances survive the package filter but card matched pkg list
                    // keep it visible but show all instances. Safer fallback:
                    if (instanceVisibleInCard === 0 && instances.length > 0) {
                        instances.forEach(function(i) { i.classList.remove('is-hidden'); });
                        instanceVisibleInCard = instances.length;
                    }
                    visibleInstances += instanceVisibleInCard;
                    var countEl = card.querySelector('.instances-count');
                    if (countEl) {
                        countEl.textContent = instanceVisibleInCard + ' element' + (instanceVisibleInCard === 1 ? '' : 's') + ' to fix';
                    }
                }
            });
        }

        // Hide component sections (and package wrappers) that have no
        // visible cards — keeps the main panel scoped to the active filter.
        document.querySelectorAll('#failedInspectionsList .fi-component-section').forEach(function(section) {
            var anyVisible = section.querySelectorAll('.fi-card:not(.is-hidden)').length > 0;
            section.classList.toggle('is-hidden', !anyVisible);
        });
        document.querySelectorAll('#failedInspectionsList .fi-package-section').forEach(function(pkgSection) {
            var anyVisible = pkgSection.querySelectorAll('.fi-component-section:not(.is-hidden)').length > 0;
            pkgSection.classList.toggle('is-hidden', !anyVisible);
        });

        // Totals for sidebar title — count distinct rule groups (data-rg),
        // not cards, since cards are duplicated per component.
        var totals = {
            failedGroups: 0,
            preExistingGroups: 0,
            passed: passedList ? passedList.querySelectorAll('.passed-card').length : 0,
        };
        var seenFailedRg = {};
        var seenPreExistingRg = {};
        document.querySelectorAll('#failedInspectionsList .fi-card').forEach(function(card) {
            var rg = card.getAttribute('data-rg') || '';
            if (card.getAttribute('data-has-new') === '1' && !seenFailedRg[rg]) {
                seenFailedRg[rg] = true;
                totals.failedGroups += 1;
            }
            if (card.getAttribute('data-has-pre-existing') === '1' && !seenPreExistingRg[rg]) {
                seenPreExistingRg[rg] = true;
                totals.preExistingGroups += 1;
            }
        });

        totals.failedPkgs = 0;
        totals.preExistingPkgs = 0;
        totals.passedPkgs = 0;
        totals.allPkgs = 0;
        document.querySelectorAll('.pkg-tree-node').forEach(function(node) {
            totals.allPkgs += 1;
            if (parseInt(node.getAttribute('data-failed') || '0', 10) > 0) totals.failedPkgs += 1;
            if (parseInt(node.getAttribute('data-pre-existing') || '0', 10) > 0) totals.preExistingPkgs += 1;
            if (parseInt(node.getAttribute('data-passed') || '0', 10) > 0) totals.passedPkgs += 1;
        });

        updateSidebarTitle(state, totals);
        updateMainTitle(state, visibleCards, visibleInstances);

        // Empty state — only celebrate when the user has actively cleared
        // the failed/pre-existing buckets, not whenever the active filter
        // happens to have no matching items.
        if (celebration) {
            var isEmpty = visibleCards === 0;
            var totalFailedCards = document.querySelectorAll('#failedInspectionsList .fi-card[data-has-new="1"]').length;
            var totalPreExistingCards = document.querySelectorAll('#failedInspectionsList .fi-card[data-has-pre-existing="1"]').length;
            var allResolved =
                (state.filter === 'failed' && totalFailedCards === 0) ||
                (state.filter === 'pre-existing' && totalPreExistingCards === 0);
            celebration.classList.toggle('show', isEmpty && allResolved);
        }

        // Tab counts
        var elFailed = document.querySelector('[data-count-failed]');
        var elPre = document.querySelector('[data-count-pre-existing]');
        var elPassed = document.querySelector('[data-count-passed]');
        var elAll = document.querySelector('[data-count-all]');
        if (elFailed) elFailed.textContent = String(totals.failedGroups);
        if (elPre) elPre.textContent = String(totals.preExistingGroups);
        if (elPassed) elPassed.textContent = String(totals.passed);
        if (elAll) elAll.textContent = String(totals.failedGroups + totals.preExistingGroups + totals.passed);

        // Severity dropdown counts
        updateSeverityCounts(state);

        // Clear button visibility
        var clearBtn = document.getElementById('pkgClearBtn');
        if (clearBtn) clearBtn.classList.toggle('hidden', !state.pkg && !state.rg);

        // Sidebar visibility per filter
        document.querySelectorAll('.pkg-tree-node').forEach(function(node) {
            var failedN = parseInt(node.getAttribute('data-failed') || '0', 10);
            var preExistingN = parseInt(node.getAttribute('data-pre-existing') || '0', 10);
            var passedN = parseInt(node.getAttribute('data-passed') || '0', 10);
            var keepPkg;
            if (state.filter === 'failed') keepPkg = failedN > 0;
            else if (state.filter === 'pre-existing') keepPkg = preExistingN > 0;
            else if (state.filter === 'passed') keepPkg = passedN > 0;
            else keepPkg = (failedN + preExistingN + passedN) > 0;
            node.classList.toggle('is-hidden', !keepPkg);
        });

        document.querySelectorAll('.pkg-tree-children .comp-tree-item').forEach(function(item) {
            var hasNew = item.getAttribute('data-has-new') === '1';
            var hasPreExisting = item.getAttribute('data-has-pre-existing') === '1';
            var isPassed = item.classList.contains('passed-comp');
            var keep;
            if (state.filter === 'failed') keep = hasNew;
            else if (state.filter === 'pre-existing') keep = hasPreExisting;
            else if (state.filter === 'passed') keep = isPassed;
            else keep = true;
            item.classList.toggle('is-hidden', !keep);
        });

        // Active package highlight
        document.querySelectorAll('.pkg-tree-node').forEach(function(node) {
            var name = node.getAttribute('data-pkg');
            node.classList.toggle('is-active', !!state.pkg && state.pkg === name);
        });

        // Active rule-group highlight (match both rg and pkg to disambiguate duplicates across packages)
        document.querySelectorAll('.comp-tree-item[data-rg]').forEach(function(item) {
            var rgId = item.getAttribute('data-rg');
            var itemPkg = item.getAttribute('data-pkg');
            var isActive = !!state.rg && state.rg === rgId && (!state.pkg || state.pkg === itemPkg);
            item.classList.toggle('active', isActive);
        });

        // Active component highlight (match component + pkg)
        document.querySelectorAll('.comp-tree-item[data-component]:not([data-rg])').forEach(function(item) {
            var compName = item.getAttribute('data-component');
            var itemPkg = item.getAttribute('data-pkg');
            var isActive = !!state.component && state.component === compName && state.pkg === itemPkg;
            item.classList.toggle('active', isActive);
        });
    }

    function updateSeverityCounts(state) {
        var counts = { critical: 0, serious: 0, moderate: 0 };
        document.querySelectorAll('#failedInspectionsList .fi-card').forEach(function(card) {
            var sev = card.getAttribute('data-severity') || 'moderate';
            var tempState = Object.assign({}, state, { severity: 'all' });
            if (cardMatches(card, tempState)) {
                if (counts[sev] !== undefined) counts[sev] += 1;
            }
        });
        document.querySelectorAll('.severity-dropdown-item').forEach(function(item) {
            var sev = item.getAttribute('data-severity');
            var countEl = item.querySelector('.sev-count');
            if (!countEl) return;
            if (sev === 'all') {
                countEl.textContent = '(' + (counts.critical + counts.serious + counts.moderate) + ')';
            } else if (counts[sev] !== undefined) {
                countEl.textContent = '(' + counts[sev] + ')';
            }
        });
    }

    function setActiveFilterTab(filter) {
        document.querySelectorAll('.filter-tab').forEach(function(tab) {
            var isSame = tab.getAttribute('data-filter') === filter;
            tab.classList.toggle('active', isSame);
            tab.setAttribute('aria-pressed', isSame ? 'true' : 'false');
        });
    }

    function pickInitialFilter() {
        var hasFailed = !!document.querySelector('.fi-card[data-has-new="1"]');
        var hasPreExisting = !!document.querySelector('.fi-card[data-has-pre-existing="1"]');
        var hasFilterTab = function(name) {
            return !!document.querySelector('.filter-tab[data-filter="' + name + '"]');
        };
        if (hasFailed && hasFilterTab('failed')) return 'failed';
        if (hasPreExisting && hasFilterTab('pre-existing')) return 'pre-existing';
        if (document.querySelector('.passed-card') && hasFilterTab('passed')) return 'passed';
        return 'all';
    }

    document.addEventListener('DOMContentLoaded', function() {
        var initialFilter = pickInitialFilter();
        window.__dashboardState = { filter: initialFilter, pkg: null, component: null, rg: null, severity: 'all' };
        setActiveFilterTab(initialFilter);

        document.querySelectorAll('.filter-tab').forEach(function(tab) {
            tab.addEventListener('click', function() {
                var filter = tab.getAttribute('data-filter') || 'all';
                window.__dashboardState.filter = filter;
                window.__dashboardState.rg = null;
                setActiveFilterTab(filter);
                applyDashboardFilters();
            });
        });

        document.querySelectorAll('.pkg-tree-node').forEach(function(node) {
            var pkgName = node.getAttribute('data-pkg');
            var header = node.querySelector('.pkg-tree-header');
            if (!header || !pkgName) return;
            header.addEventListener('click', function() {
                var current = window.__dashboardState.pkg;
                window.__dashboardState.pkg = (current === pkgName) ? null : pkgName;
                window.__dashboardState.component = null;
                window.__dashboardState.rg = null;
                applyDashboardFilters();
            });
        });

        // Click a component in the sidebar — filter to that component.
        document.querySelectorAll('.comp-tree-item[data-component]:not([data-rg])').forEach(function(item) {
            item.addEventListener('click', function(e) {
                e.stopPropagation();
                var pkg = item.getAttribute('data-pkg');
                var comp = item.getAttribute('data-component');
                var current = window.__dashboardState.component;
                if (current === comp) {
                    window.__dashboardState.pkg = null;
                    window.__dashboardState.component = null;
                } else {
                    window.__dashboardState.pkg = pkg || null;
                    window.__dashboardState.component = comp;
                }
                window.__dashboardState.rg = null;
                applyDashboardFilters();
            });
            item.addEventListener('keydown', function(e) {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    item.click();
                }
            });
        });

        document.querySelectorAll('.comp-tree-item[data-rg]').forEach(function(item) {
            item.addEventListener('click', function(e) {
                e.stopPropagation();
                var rg = item.getAttribute('data-rg');
                var pkg = item.getAttribute('data-pkg');
                var current = window.__dashboardState.rg;
                window.__dashboardState.rg = (current === rg) ? null : rg;
                window.__dashboardState.pkg = current === rg ? null : pkg || null;
                applyDashboardFilters();
            });
            item.addEventListener('keydown', function(e) {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    item.click();
                }
            });
        });

        document.querySelectorAll('.comp-tree-item.passed-comp').forEach(function(item) {
            item.addEventListener('click', function(e) {
                e.stopPropagation();
                var name = item.getAttribute('data-passed-name');
                var pkg = item.getAttribute('data-pkg');
                window.__dashboardState.filter = 'passed';
                window.__dashboardState.rg = null;
                window.__dashboardState.pkg = pkg || null;
                setActiveFilterTab('passed');
                applyDashboardFilters();
                if (name) {
                    var card = document.querySelector('.passed-card[data-pc-name="' + cssEscape(name) + '"]');
                    if (card) card.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            });
            item.addEventListener('keydown', function(e) {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    item.click();
                }
            });
        });

        document.querySelectorAll('.passed-card').forEach(function(card) {
            card.addEventListener('click', function(e) {
                e.stopPropagation();
                var name = card.getAttribute('data-pc-name') || '';
                var pkg = card.getAttribute('data-package') || '';
                window.__dashboardState.filter = 'passed';
                window.__dashboardState.rg = null;
                window.__dashboardState.pkg = pkg || null;
                setActiveFilterTab('passed');
                applyDashboardFilters();
                if (name) {
                    var sidebarItem = document.querySelector('.comp-tree-item.passed-comp[data-passed-name="' + cssEscape(name) + '"]');
                    if (sidebarItem) sidebarItem.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            });
            card.addEventListener('keydown', function(e) {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    card.click();
                }
            });
        });

        var clearBtn = document.getElementById('pkgClearBtn');
        if (clearBtn) {
            clearBtn.addEventListener('click', function() {
                window.__dashboardState.pkg = null;
                window.__dashboardState.rg = null;
                applyDashboardFilters();
            });
        }

        document.addEventListener('click', function(e) {
            var menu = document.getElementById('sevDropdownMenu');
            var btn = document.getElementById('sevDropdownBtn');
            if (!menu || !btn) return;
            if (!menu.contains(e.target) && !btn.contains(e.target)) {
                menu.classList.remove('open');
                btn.setAttribute('aria-expanded', 'false');
            }
        });

        applyDashboardFilters();
    });
`;
