/**
 * Inline JavaScript for BI event tracking in the HTML report.
 * Uses the globally-available `webBiLogger` (from the UMD bundle) to send
 * events 1100-1107 to frog.wix.com.
 *
 * All functions are wrapped in try/catch — BI must never break the report.
 */
export const biScripts = `
        // ── BI Logger Initialization ──────────────────────────────────
        var _biLogger = (function() {
            try {
                if (typeof webBiLogger !== 'undefined') {
                    return webBiLogger.factory().logger();
                }
            } catch(e) {
                console.warn('[bi] Failed to initialize BI logger:', e);
            }
            return null;
        })();

        var _biSessionId = (function() {
            try {
                var key = 'a11y-audit-bi-esi';
                var stored = sessionStorage.getItem(key);
                if (stored) return stored;
                var id = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
                    var r = Math.random() * 16 | 0;
                    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
                });
                sessionStorage.setItem(key, id);
                return id;
            } catch(e) {
                return 'unknown';
            }
        })();

        // ── BI Helpers ────────────────────────────────────────────────
        function _biReportViaFrog(evid, params) {
            try {
                var payload = new URLSearchParams();
                payload.set('src', '121');
                payload.set('evid', String(evid));
                payload.set('_', String(Date.now()));

                Object.keys(params || {}).forEach(function(key) {
                    var value = params[key];
                    if (value === undefined || value === null) return;
                    payload.set(key, String(value));
                });

                var img = new Image();
                window.__a11yBiFallbackRequests = window.__a11yBiFallbackRequests || [];
                window.__a11yBiFallbackRequests.push(img);
                img.onload = img.onerror = function() {
                    try {
                        var index = window.__a11yBiFallbackRequests.indexOf(img);
                        if (index >= 0) window.__a11yBiFallbackRequests.splice(index, 1);
                    } catch(e) {}
                };
                img.src = 'https://frog.wix.com/?' + payload.toString();
            } catch(e) {
                console.warn('[bi] Failed to report event ' + evid + ' via frog fallback:', e);
            }
        }

        function _biReport(evid, params) {
            try {
                if (_biLogger) {
                    _biLogger.report({ evid: evid, src: 121, endpoint: '', params: params });
                    return;
                }
                _biReportViaFrog(evid, params);
            } catch(e) {
                console.warn('[bi] Failed to report event ' + evid + ':', e);
            }
        }

        function _biCommon() {
            var ctx = window.A11Y_AUDIT_CONTEXT || {};
            var meta = window.A11Y_BI_META || {};
            return {
                esi: _biSessionId,
                repository: ctx.repository || '',
                prNumberString: ctx.prNumber ? String(ctx.prNumber) : ''
            };
        }

        function _biCommonWithTs() {
            var common = _biCommon();
            var meta = window.A11Y_BI_META || {};
            common.report_generated_ts = meta.reportGeneratedTs || '';
            common.reportGenetatedTs = meta.reportGeneratedTs || '';
            return common;
        }

        // ── Evid 1100: Dashboard View ─────────────────────────────────
        function biDashboardView() {
            try {
                var meta = window.A11Y_BI_META || {};
                var common = _biCommonWithTs();

                var reportData = null;
                try {
                    var el = document.getElementById('a11y-report-data');
                    if (el) reportData = JSON.parse(el.textContent || '{}');
                } catch(e) {}

                var payload = '';
                if (reportData && reportData.pages) {
                    try {
                        var failedAndSkipped = reportData.pages.filter(function(p) {
                            return p.status === 'failed' || p.status === 'skipped';
                        }).map(function(p) {
                            return { pageName: p.pageName, status: p.status, failedInspections: p.totalFailedInspectionsCount };
                        });
                        payload = JSON.stringify(failedAndSkipped);
                    } catch(e) {}
                }

                _biReport(1100, {
                    esi: common.esi,
                    report_generated_ts: common.report_generated_ts,
                    totalAuditsCount: meta.totalAuditsCount || '',
                    failedAuditsCount: meta.failedAuditsCount || '',
                    passedAuditsCount: meta.passedAuditsCount || '',
                    totalFailedInspections: meta.totalFailedInspections || 0,
                    warningsCount: meta.warningsCount || '',
                    repository: common.repository,
                    payload: payload,
                    prNumberString: common.prNumberString
                });
            } catch(e) {
                console.warn('[bi] biDashboardView error:', e);
            }
        }

        // ── Evid 1101: Dashboard Click ────────────────────────────────
        function biDashboardClick(ctaType, auditName, section, inspectionsCount, failedInspectionCount) {
            try {
                var common = _biCommonWithTs();
                _biReport(1101, {
                    esi: common.esi,
                    reportGenetatedTs: common.reportGenetatedTs,
                    cta_type: ctaType || '',
                    auditName: auditName || '',
                    repository: common.repository,
                    prNumberString: common.prNumberString,
                    section: section || '',
                    inspectionsCount: inspectionsCount != null ? String(inspectionsCount) : '',
                    failedInspectionCount: failedInspectionCount != null ? String(failedInspectionCount) : ''
                });
            } catch(e) {
                console.warn('[bi] biDashboardClick error:', e);
            }
        }

        // ── Evid 1102: Modal View ─────────────────────────────────────
        function biModalView(modalType, auditName, totalInspections, passedInspections, failedInspections, url, payload) {
            try {
                var common = _biCommonWithTs();
                _biReport(1102, {
                    esi: common.esi,
                    modal_type: modalType || '',
                    reportGenetatedTs: common.reportGenetatedTs,
                    totalInspectionsCount: totalInspections != null ? String(totalInspections) : '',
                    passedInspectionsCount: passedInspections != null ? String(passedInspections) : '',
                    failedInspectionsCount: failedInspections != null ? String(failedInspections) : '',
                    auditName: auditName || '',
                    prNumberString: common.prNumberString,
                    repository: common.repository,
                    url: url || '',
                    payload: payload || ''
                });
            } catch(e) {
                console.warn('[bi] biModalView error:', e);
            }
        }

        // ── Evid 1103: Modal CTA Click ────────────────────────────────
        function biModalCtaClick(modalType, ctaType, auditName, url, totalInspections, passedInspections, failedInspections, payload) {
            try {
                var common = _biCommonWithTs();
                _biReport(1103, {
                    esi: common.esi,
                    modal_type: modalType || '',
                    reportGenetatedTs: common.reportGenetatedTs,
                    prNumberString: common.prNumberString,
                    auditName: auditName || '',
                    url: url || '',
                    totalInspectionCount: totalInspections != null ? String(totalInspections) : '',
                    passedInspectionsCount: passedInspections != null ? String(passedInspections) : '',
                    failedInspectionsCount: failedInspections != null ? String(failedInspections) : '',
                    payload: payload || '',
                    cta_type: ctaType || ''
                });
            } catch(e) {
                console.warn('[bi] biModalCtaClick error:', e);
            }
        }

        // ── Evid 1104: Section Expand/Collapse ────────────────────────
        function biSectionExpandCollapse(expandCollapse, section, auditName, totalInspections, passedInspections, failedInspections, url, payload) {
            try {
                var common = _biCommonWithTs();
                _biReport(1104, {
                    esi: common.esi,
                    expand_collapse: expandCollapse || '',
                    modal_type: 'audit details',
                    section: section || '',
                    auditName: auditName || '',
                    totalInspectionsCount: totalInspections != null ? String(totalInspections) : '',
                    passedInspectionsCount: passedInspections != null ? String(passedInspections) : '',
                    failedInspectionsCount: failedInspections != null ? String(failedInspections) : '',
                    url: url || '',
                    prNumberString: common.prNumberString,
                    repository: common.repository,
                    payload: payload || ''
                });
            } catch(e) {
                console.warn('[bi] biSectionExpandCollapse error:', e);
            }
        }

        // ── Evid 1105: Inspection Expand/Collapse ─────────────────────
        function biInspectionExpandCollapse(expandCollapse, auditName, inspectionType, inspectionCategory, elementsCount, failedElementsCount, totalRulesCount, passedRulesCount, failedRulesCount, url, payload) {
            try {
                var common = _biCommonWithTs();
                _biReport(1105, {
                    esi: common.esi,
                    expand_collapse: expandCollapse || '',
                    elementsCount: elementsCount || 0,
                    failedElementsCount: failedElementsCount || 0,
                    payload: payload || '',
                    InspectionCategory: inspectionCategory || '',
                    auditName: auditName || '',
                    inspectionType: inspectionType || '',
                    totalRulesCount: totalRulesCount || 0,
                    passedRulesCount: passedRulesCount || 0,
                    failedRulesCount: failedRulesCount || 0,
                    prNumberString: common.prNumberString,
                    repository: common.repository,
                    reportGeneratedTS: common.report_generated_ts,
                    url: url || ''
                });
            } catch(e) {
                console.warn('[bi] biInspectionExpandCollapse error:', e);
            }
        }

        // ── Evid 1106: Rule Expand/Collapse ───────────────────────────
        function biRuleExpandCollapse(expandCollapse, auditName, ruleType, severity, inspectionType, inspectionCategory, elementsCount, passedElementsCount, failedElementsCount) {
            try {
                var common = _biCommonWithTs();
                _biReport(1106, {
                    esi: common.esi,
                    expand_collapse: expandCollapse || '',
                    repository: common.repository,
                    prNumberString: common.prNumberString,
                    auditName: auditName || '',
                    elementsCount: elementsCount || 0,
                    severity: severity || '',
                    inspectionType: inspectionType || '',
                    ruleType: ruleType || '',
                    inspectionCategory: inspectionCategory || '',
                    report_generated_ts: common.report_generated_ts,
                    failedElementsCount: failedElementsCount || 0,
                    passedElementsCount: passedElementsCount || 0
                });
            } catch(e) {
                console.warn('[bi] biRuleExpandCollapse error:', e);
            }
        }

        // ── Evid 1107: Elements Expand/Collapse ───────────────────────
        function biElementExpandCollapse(expandCollapse, auditName, ruleType, severity, inspectionType, inspectionCategory, elementType, elementId) {
            try {
                var common = _biCommonWithTs();
                _biReport(1107, {
                    esi: common.esi,
                    expand_collapse: expandCollapse || '',
                    repository: common.repository,
                    prNumberString: common.prNumberString,
                    auditName: auditName || '',
                    severity: severity || '',
                    inspectionType: inspectionType || '',
                    ruleType: ruleType || '',
                    inspectionCategory: inspectionCategory || '',
                    report_generated_ts: common.report_generated_ts,
                    elementType: elementType || '',
                    elementId: elementId || ''
                });
            } catch(e) {
                console.warn('[bi] biElementExpandCollapse error:', e);
            }
        }

        // ── BI Context Extraction Helpers ─────────────────────────────
        function _biGetAuditNameFromModal(modalEl) {
            try {
                if (!modalEl) return '';
                var titleEl = modalEl.querySelector('.modal-title h2');
                return titleEl ? titleEl.textContent.trim() : '';
            } catch(e) { return ''; }
        }

        function _biGetUrlFromModal(modalEl) {
            try {
                if (!modalEl) return '';
                var linkEl = modalEl.querySelector('.modal-url-link');
                return linkEl ? linkEl.textContent.trim() : '';
            } catch(e) { return ''; }
        }

        function _biGetSectionType(header) {
            try {
                var group = header.closest('.audits-group');
                if (!group) return '';
                if (group.classList.contains('audits-group-error')) return 'failed';
                if (group.classList.contains('audits-group-success')) return 'passed';
                if (group.classList.contains('audits-group-warning')) return 'warning';
                if (group.classList.contains('audits-group-serious')) return 'error';
                if (group.classList.contains('audits-group-muted')) return 'skipped';
                return '';
            } catch(e) { return ''; }
        }

        function _biGetInspectionContext(header) {
            try {
                var item = header.closest('.audits-group-item');
                if (!item) return {};
                var nameEl = item.querySelector('.audits-group-item-name');
                var auditNameEl = item.querySelector('.audits-group-item-audit-name');
                var failedInspectionsEl = item.querySelector('.audits-group-item-failed-inspections');
                var failedInspectionsText = failedInspectionsEl ? failedInspectionsEl.textContent.trim() : '';
                var failedInspectionsMatch = failedInspectionsText.match(/^(\\d+)/);
                return {
                    inspectionName: nameEl ? nameEl.textContent.trim() : '',
                    auditName: auditNameEl ? auditNameEl.textContent.trim() : '',
                    inspectionId: item.getAttribute('data-inspection-id') || '',
                    pageUrl: item.getAttribute('data-page-url') || '',
                    failedInspectionsCount: failedInspectionsMatch ? parseInt(failedInspectionsMatch[1], 10) : 0
                };
            } catch(e) { return {}; }
        }

        function _biGetModalInspectionCounts(modalEl) {
            try {
                if (!modalEl) return {};
                var items = modalEl.querySelectorAll('.audits-group-item');
                var total = items.length;
                var failed = 0;
                var passed = 0;
                items.forEach(function(item) {
                    var group = item.closest('.audits-group');
                    if (group && group.classList.contains('audits-group-error')) failed++;
                    else if (group && group.classList.contains('audits-group-success')) passed++;
                });
                return { total: total, passed: passed, failed: failed };
            } catch(e) { return {}; }
        }

        function _biGetFailedInspectionGroupContext(titleElement) {
            try {
                var group = titleElement.closest('.failed-inspection-group') || titleElement.closest('.failed-inspection-group-collapsible');
                if (!group) return {};
                var groupId = group.getAttribute('data-group-id') || '';
                var titleEl = group.querySelector('.failed-inspection-group-title-text, h4, h3');
                var ruleType = titleEl ? titleEl.textContent.trim() : groupId;
                var severity = group.getAttribute('data-severity') || '';
                var items = group.querySelectorAll('.failed-inspection-card, .failed-inspection-item');
                var failedItems = group.querySelectorAll('.failed-inspection-card:not(.failed-inspection-skipped), .failed-inspection-item:not(.failed-inspection-skipped)');
                return {
                    ruleType: ruleType,
                    severity: severity,
                    elementsCount: items.length,
                    failedElementsCount: failedItems.length,
                    passedElementsCount: items.length - failedItems.length
                };
            } catch(e) { return {}; }
        }

        function _biGetAuditNameFromElement(el) {
            try {
                var item = el.closest('.audits-group-item');
                if (item) {
                    var auditEl = item.querySelector('.audits-group-item-audit-name');
                    return auditEl ? auditEl.textContent.trim() : '';
                }
                return '';
            } catch(e) { return ''; }
        }

        function _biGetInspectionTypeFromElement(el) {
            try {
                var item = el.closest('.audits-group-item');
                if (item) {
                    var nameEl = item.querySelector('.audits-group-item-name');
                    return nameEl ? nameEl.textContent.trim() : '';
                }
                return '';
            } catch(e) { return ''; }
        }
`;
