/** Skip/Unskip button creation and injection into failed inspection cards. */
export const buttonScripts = `
        function createSkipButton(ruleId, elementSelector, pageUrl, containerSelector) {
            var btn = document.createElement('button');
            btn.className = 'skip-failed-inspection-btn';
            btn.type = 'button';
            btn.title = 'Skip this inspection';

            var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
            svg.setAttribute('fill', 'none');
            svg.setAttribute('stroke', 'currentColor');
            svg.setAttribute('viewBox', '0 0 24 24');
            var path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            path.setAttribute('stroke-linecap', 'round');
            path.setAttribute('stroke-linejoin', 'round');
            path.setAttribute('stroke-width', '2');
            path.setAttribute('d', 'M5 4l10 8-10 8V4z');
            svg.appendChild(path);
            var line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
            line.setAttribute('x1', '19');
            line.setAttribute('y1', '4');
            line.setAttribute('x2', '19');
            line.setAttribute('y2', '20');
            line.setAttribute('stroke', 'currentColor');
            line.setAttribute('stroke-width', '2');
            line.setAttribute('stroke-linecap', 'round');
            svg.appendChild(line);
            btn.appendChild(svg);
            btn.appendChild(document.createTextNode('Skip inspection'));

            btn.addEventListener('click', function(e) {
                e.stopPropagation();
                openSkipModal(ruleId, elementSelector, pageUrl, containerSelector);
            });
            return btn;
        }

        function injectSkipButtons() {
            if (!window.A11Y_AUDIT_CONTEXT) {
                console.warn('[failed-inspection-state] injectSkipButtons: no A11Y_AUDIT_CONTEXT');
                return;
            }

            var items = document.querySelectorAll('.audits-group-item[data-inspection-id][data-page-url]');
            console.info('[failed-inspection-state] injectSkipButtons: found', items.length, 'audit group items');
            items.forEach(function(item) {
                var pageUrl = item.getAttribute('data-page-url');
                if (!pageUrl) return;
                var containerSelector = item.getAttribute('data-container-selector') || '';

                var content = item.querySelector('.audits-group-item-content');
                if (!content) return;

                var cards = content.querySelectorAll('.failed-inspection-card, .failed-inspection-item');
                cards.forEach(function(card) {
                    if (card.querySelector('.skip-failed-inspection-btn')) return;
                    if (card.classList.contains('failed-inspection-benchmarked')) return;

                    var ruleId = getRuleId(card, item);
                    if (!ruleId) return;

                    var selectorEl = card.querySelector('.element-selector, .affected-element-selector');
                    if (!selectorEl) return;
                    var elSelector = (selectorEl.textContent || '').trim();
                    if (!elSelector) return;

                    var btnContainer = card.querySelector('.element-details') || card;
                    btnContainer.appendChild(createSkipButton(ruleId, elSelector, pageUrl, containerSelector));
                });
            });
        }

        function createUnskipButton(ruleId, elementSelector, pageUrl, containerSelector) {
            var btn = document.createElement('button');
            btn.className = 'unskip-failed-inspection-btn';
            btn.type = 'button';
            btn.title = 'Restore this inspection';

            var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
            svg.setAttribute('fill', 'none');
            svg.setAttribute('stroke', 'currentColor');
            svg.setAttribute('viewBox', '0 0 24 24');
            var path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            path.setAttribute('stroke-linecap', 'round');
            path.setAttribute('stroke-linejoin', 'round');
            path.setAttribute('stroke-width', '2');
            path.setAttribute('d', 'M3 10h10a5 5 0 0 1 5 5v0a5 5 0 0 1-5 5H3');
            svg.appendChild(path);
            btn.appendChild(svg);
            btn.appendChild(document.createTextNode('Restore'));

            btn.addEventListener('click', function(e) {
                e.stopPropagation();
                submitUnskip(btn, ruleId, elementSelector, pageUrl, containerSelector);
            });
            return btn;
        }

        function injectUnskipButtons() {
            if (!window.A11Y_AUDIT_CONTEXT) return;

            var skippedItems = document.querySelectorAll('.audits-group-muted .audits-group-item[data-inspection-id][data-page-url]');
            skippedItems.forEach(function(item) {
                var pageUrl = item.getAttribute('data-page-url');
                if (!pageUrl) return;
                var containerSelector = item.getAttribute('data-container-selector') || '';

                var content = item.querySelector('.audits-group-item-content');
                if (!content) return;

                var cards = content.querySelectorAll('.failed-inspection-card, .failed-inspection-item');
                cards.forEach(function(card) {
                    if (card.querySelector('.unskip-failed-inspection-btn')) return;

                    var ruleId = getRuleId(card, item);
                    if (!ruleId) return;

                    var selectorEl = card.querySelector('.element-selector, .affected-element-selector');
                    if (!selectorEl) return;
                    var elSelector = (selectorEl.textContent || '').trim();
                    if (!elSelector) return;

                    var btnContainer = card.querySelector('.element-details') || card;
                    btnContainer.appendChild(createUnskipButton(ruleId, elSelector, pageUrl, containerSelector));
                });
            });
        }

        function createFixWithAiButton(ruleId, elementSelector, pageUrl, containerSelector) {
            var btn = document.createElement('button');
            btn.className = 'fix-with-ai-btn';
            btn.type = 'button';
            btn.title = 'Fix with AI';

            var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
            svg.setAttribute('fill', 'none');
            svg.setAttribute('stroke', 'currentColor');
            svg.setAttribute('viewBox', '0 0 24 24');
            var path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            path.setAttribute('stroke-linecap', 'round');
            path.setAttribute('stroke-linejoin', 'round');
            path.setAttribute('stroke-width', '2');
            path.setAttribute('d', 'M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z');
            svg.appendChild(path);
            btn.appendChild(svg);
            btn.appendChild(document.createTextNode('Fix with AI'));

            btn.addEventListener('click', function(e) {
                e.stopPropagation();
                openFixAiModal(ruleId, elementSelector, pageUrl, containerSelector);
            });
            return btn;
        }

        function injectFixWithAiButtons() {
            if (!window.A11Y_AUDIT_CONTEXT) {
                return;
            }

            var items = document.querySelectorAll('.audits-group-item[data-inspection-id][data-page-url]');
            items.forEach(function(item) {
                var pageUrl = item.getAttribute('data-page-url');
                if (!pageUrl) return;
                var containerSelector = item.getAttribute('data-container-selector') || '';

                var content = item.querySelector('.audits-group-item-content');
                if (!content) return;

                var cards = content.querySelectorAll('.failed-inspection-card, .failed-inspection-item');
                cards.forEach(function(card) {
                    if (card.querySelector('.fix-with-ai-btn')) return;
                    if (card.classList.contains('failed-inspection-benchmarked')) return;

                    var ruleId = getRuleId(card, item);
                    if (!ruleId) return;

                    var selectorEl = card.querySelector('.element-selector, .affected-element-selector');
                    if (!selectorEl) return;
                    var elSelector = (selectorEl.textContent || '').trim();
                    if (!elSelector) return;

                    var btnContainer = card.querySelector('.element-details') || card;
                    btnContainer.appendChild(createFixWithAiButton(ruleId, elSelector, pageUrl, containerSelector));
                });
            });
        }
`;
