/**
 * Theme toggle styles and scripts for dark mode support.
 * Provides a toggle button component and JavaScript for theme switching
 * with localStorage persistence and system preference detection.
 */

/**
 * CSS styles for the theme toggle button.
 */
export const themeToggleStyles = `
    .theme-toggle {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 28px;
        height: 28px;
        padding: 0;
        background: transparent;
        border: none;
        border-radius: 0;
        cursor: pointer;
        color: var(--color-text-muted);
        transition: color 0.2s ease;
    }

    .theme-toggle:hover {
        background: transparent;
        color: var(--color-text-primary);
    }

    .theme-toggle:focus {
        outline: 2px solid var(--color-brand-primary);
        outline-offset: 2px;
    }

    .theme-toggle:focus:not(:focus-visible) {
        outline: none;
    }

    .theme-toggle:focus-visible {
        outline: 2px solid var(--color-brand-primary);
        outline-offset: 2px;
    }

    .theme-toggle svg {
        width: 16px;
        height: 16px;
        stroke-width: 1.5;
    }

    /* Sun icon (shown in dark mode) */
    .theme-toggle .icon-sun {
        display: none;
    }

    /* Moon icon (shown in light mode) */
    .theme-toggle .icon-moon {
        display: block;
    }

    [data-theme="dark"] .theme-toggle .icon-sun {
        display: block;
    }

    [data-theme="dark"] .theme-toggle .icon-moon {
        display: none;
    }
`;

/**
 * JavaScript for theme toggle functionality.
 * Handles:
 * - Theme initialization from localStorage or system preference
 * - Theme toggle on button click
 * - Persistence to localStorage
 */
export const themeToggleScripts = `
    (function() {
        const THEME_KEY = 'a11y-report-theme';
        
        function getSystemTheme() {
            if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
                return 'dark';
            }
            return 'light';
        }
        
        function getSavedTheme() {
            try {
                return localStorage.getItem(THEME_KEY);
            } catch (e) {
                return null;
            }
        }
        
        function saveTheme(theme) {
            try {
                localStorage.setItem(THEME_KEY, theme);
            } catch (e) {
                // localStorage not available
            }
        }
        
        function setTheme(theme) {
            if (theme === 'dark') {
                document.documentElement.setAttribute('data-theme', 'dark');
            } else {
                document.documentElement.removeAttribute('data-theme');
            }
            updateToggleButton(theme);
        }
        
        function updateToggleButton(theme) {
            const toggleBtn = document.querySelector('.theme-toggle');
            if (toggleBtn) {
                toggleBtn.setAttribute('aria-label', 
                    theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'
                );
            }
        }
        
        function toggleTheme() {
            const currentTheme = document.documentElement.getAttribute('data-theme');
            const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
            setTheme(newTheme);
            saveTheme(newTheme);

            try {
                if (typeof biDashboardClick === 'function') {
                    biDashboardClick('dark_mode');
                }
            } catch(e) {}
        }
        
        function initTheme() {
            const savedTheme = getSavedTheme();
            const theme = savedTheme || 'light';
            setTheme(theme);
            
            // Listen for system theme changes
            if (window.matchMedia) {
                window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function(e) {
                    // Only auto-switch if user hasn't set a preference
                    if (!getSavedTheme()) {
                        setTheme(e.matches ? 'dark' : 'light');
                    }
                });
            }
        }
        
        // Initialize theme immediately to prevent flash
        initTheme();
        
        // Expose toggle function globally
        window.toggleTheme = toggleTheme;
        
        // Re-initialize after DOM is ready (for toggle button aria-label)
        document.addEventListener('DOMContentLoaded', function() {
            const currentTheme = document.documentElement.getAttribute('data-theme') || 'light';
            updateToggleButton(currentTheme);
        });
    })();
`;

/**
 * HTML template for the theme toggle button.
 * Includes both sun and moon icons for visual feedback.
 */
export const themeToggleButton = `
    <button class="theme-toggle" onclick="toggleTheme()" aria-label="Switch to dark mode" title="Toggle dark mode">
        <svg class="icon-moon" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" 
                  d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
        </svg>
        <svg class="icon-sun" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" 
                  d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
        </svg>
    </button>
`;
