import { REPORT_TITLE } from '../../../../types';

/**
 * Safely serialize value to JSON for embedding in HTML <script> tags.
 * Escapes closing script tags to prevent HTML injection.
 */
export function toSafeJson(value: unknown): string {
  return JSON.stringify(value).replace(/<\//g, '<\\/');
}

export const getReportTitle = (): string => {
  return REPORT_TITLE;
};
