import React, { useEffect, useMemo, useRef } from 'react';

import { InspectionStatus } from '../../types';
import {
  allReportStyles,
  buildAllPassingData,
  buildBenchmarkData,
  buildMultiPackageData,
  defaultBenchmarkMetadata,
  FAILED_INSPECTION_STATE_STORYBOOK_SCRIPTS,
  FailedInspectionStateHtmlPreview,
  fillTemplate,
  MultiPageReportData,
  multiPageReportTemplate,
  scriptFunctions,
} from './helpers';

export default {
  title: 'Audit Report / Benchmark Active',
};

export const PrBlocked = () => {
  const data = buildBenchmarkData({ includeNewIssues: true });
  return <FailedInspectionStateHtmlPreview data={data} />;
};
PrBlocked.storyName = 'PR Blocked (New Failed Inspections)';

export const PrPassing = () => {
  const data = buildBenchmarkData({ includeNewIssues: false });
  return <FailedInspectionStateHtmlPreview data={data} />;
};
PrPassing.storyName = 'PR Passing (Benchmark Only)';

const buildFirstScanData = (): MultiPageReportData => {
  const base = buildMultiPackageData();
  const benchmarkPages = base.pages.map((p) => ({
    ...p,
    audits: p.audits.map((a) => ({ ...a, status: InspectionStatus.WARNING })),
    modalId: `benchmark-${p.modalId ?? p.pageName}`,
    status: InspectionStatus.WARNING,
  }));
  const benchmarkIssuesCount = benchmarkPages.reduce(
    (sum, p) => sum + p.totalFailedInspectionsCount,
    0,
  );

  return {
    benchmarkPages,
    metadata: {
      auditContext: base.metadata.auditContext,
      benchmarkIssuesCount,
      benchmarkMetadata: {
        ...defaultBenchmarkMetadata,
        originalIssueCount: benchmarkIssuesCount,
      },
      newIssuesCount: 0,
      timestamp: new Date().toLocaleString(),
    },
    pages: [],
    summary: {
      errorPages: 0,
      failedPages: 0,
      passedPages: 0,
      skippedPages: 0,
      totalExecutionTime: benchmarkPages.reduce(
        (sum, p) => sum + p.totalExecutionTime,
        0,
      ),
      totalFailedInspections: 0,
      totalPages: benchmarkPages.length,
    },
  };
};

export const FirstScan = () => {
  const data = buildFirstScanData();
  return (
    <FailedInspectionStateHtmlPreview
      data={data}
      mockScripts={FAILED_INSPECTION_STATE_STORYBOOK_SCRIPTS}
    />
  );
};
FirstScan.storyName = 'First Scan (Pre-existing Baseline)';

export const OnlyPassed = () => {
  const data = buildAllPassingData();
  return (
    <FailedInspectionStateHtmlPreview
      data={data}
      mockScripts={FAILED_INSPECTION_STATE_STORYBOOK_SCRIPTS}
    />
  );
};
OnlyPassed.storyName = 'All Passing (Auto-selects Passed)';

const FAILING_TEST_URL =
  'data:text/html,<html><head><title></title></head><body><button></button><img src="x"><input type="text"></body></html>';

export const ModalOpen = () => {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const data = buildBenchmarkData({ includeNewIssues: true });

  const html = useMemo(() => {
    const raw = multiPageReportTemplate(data);
    const filled = fillTemplate(raw, {
      scripts: scriptFunctions,
      styles: allReportStyles,
    });
    return filled.replace(
      '</head>',
      FAILED_INSPECTION_STATE_STORYBOOK_SCRIPTS + '</head>',
    );
  }, [data]);

  useEffect(() => {
    const iframe = iframeRef.current;
    if (!iframe) {
      return;
    }
    const handleLoad = () => {
      const win = iframe.contentWindow as any;
      if (win?.openSkipModal) {
        win.openSkipModal('label', 'input', FAILING_TEST_URL, '');
      }
    };
    iframe.addEventListener('load', handleLoad);
    return () => iframe.removeEventListener('load', handleLoad);
  }, [html]);

  return (
    <iframe
      ref={iframeRef}
      srcDoc={html}
      style={{ border: 'none', height: '100vh', width: '100%' }}
      title="Failed Inspection State Modal Preview"
    />
  );
};
ModalOpen.storyName = 'Skip Modal (Pre-Opened)';
